INSERT INTO `characters` (`id`, `project_id`, `type`, `input_data`, `output_data`, `created_at`) VALUES
(1, 5, 'screenplay', '{\"logline\":\"Logline chính: Khi một cô gái xinh đẹp và thông minh phải lòng một chàng trai tài năng nhưng bị đẩy vào thế giới tội phạm, cô phải lựa chọn giữa tình yêu và danh dự, trong một cuộc chiến đấu để bảo vệ bản thân và những người thân yêu.Phân tích các yếu tố:Nhân vật chính: Cô gái xinh đẹp và thông minh (Thúy Kiều)Mục tiêu: Bảo vệ bản thân và những người thân yêu, giữ gìn danh dự và tìm kiếm hạnh phúcXung đột: Thế giới tội phạm, sự phản đối của gia đình và xã hội, cuộc chiến đấu nội tâm giữa tình yêu và danh dựStakes: Mất đi danh dự, bị tổn thương về thể xác và tinh thần, mất đi người thân yêu2-3 phiên bản logline thay thế:Phiên bản 1: Trong một thế giới đầy rẫy tội phạm và tham nhũng, một cô gái trẻ phải đối mặt với những lựa chọn khó khăn khi yêu một chàng trai có quá khứ tối, và phải tìm cách bảo vệ bản thân và những người thân yêu.Phiên bản 2: Khi tình yêu và danh dự bị đẩy vào thế giới tội phạm, một cô gái thông minh và xinh đẹp phải sử dụng tất cả khả năng và trí tuệ của mình để bảo vệ bản thân và người thân yêu, và tìm kiếm con đường đến hạnh phúc.Phiên bản 3: Trong một cuộc chiến đấu giữa tình yêu và danh dự, một cô gái trẻ phải lựa chọn giữa việc theo đuổi hạnh phúc và giữ gìn danh dự, khi cô bị đẩy vào thế giới tội phạm và phải đối mặt với những thử thách khó khăn.\",\"theme\":\"Chủ đề chính (Universal Theme):Chủ đề chính của phim này là \\\"Sự đấu tranh giữa tình yêu và danh dự\\\" hoặc \\\"Tìm kiếm hạnh phúc trong thế giới đầy thách thức\\\". Chủ đề này đề cập đến cuộc chiến nội tâm của nhân vật chính khi phải đối mặt với các lựa chọn khó khăn và thử thách trong cuộc sống.Các chủ đề phụ:Tình yêu và sự hy sinh: Chủ đề này tập trung vào việc Thúy Kiều phải đối mặt với sự lựa chọn giữa tình yêu và danh dự, và liệu cô có sẵn sàng hy sinh một trong hai để đạt được hạnh phúc.Bảo vệ bản thân và những người thân yêu: Chủ đề này đề cập đến nỗ lực của Thúy Kiều trong việc bảo vệ bản thân và những người thân yêu khỏi thế giới tội phạm và các nguy hiểm khác.Danh dự và xã hội: Chủ đề này khám phá cách xã hội và gia đình ảnh hưởng đến quyết định của Thúy Kiều và cách cô phải đối mặt với áp lực từ phía bên ngoài.Câu hỏi chủ đề (Thematic Question):Câu hỏi chủ đề của phim này có thể là: \\\"Liệu tình yêu và danh dự có thể cùng tồn tại trong một thế giới đầy thách thức, hay chúng ta phải lựa chọn giữa hai điều này để đạt được hạnh phúc?\\\"Cách thể hiện chủ đề qua câu chuyện:Để thể hiện chủ đề qua câu chuyện, phim có thể sử dụng các phương tiện sau:Quyết định của Thúy Kiều: Cô sẽ phải đối mặt với các lựa chọn khó khăn và quyết định liệu có nên theo đuổi tình yêu với chàng trai tài năng hay giữ gìn danh dự và bảo vệ bản thân.Cuộc chiến đấu nội tâm: Phim có thể thể hiện cuộc chiến đấu nội tâm của Thúy Kiều thông qua các cảnh quay, đối thoại và hành động của cô.Tác động của xã hội và gia đình: Phim có thể thể hiện cách xã hội và gia đình ảnh hưởng đến quyết định của Thúy Kiều và cách cô phải đối mặt với áp lực từ phía bên ngoài.Kết quả của quyết định: Phim có thể thể hiện kết quả của quyết định của Thúy Kiều và cách nó ảnh hưởng đến cuộc sống của cô và những người thân yêu.Tổng thể, phim này có thể trở thành một câu chuyện cảm động và đầy thách thức, khám phá cuộc chiến đấu nội tâm của một cô gái trẻ khi phải đối mặt với các lựa chọn khó khăn và thử thách trong cuộc sống.\",\"character_count\":\"\"}', '<p>Dưới đây là mô tả chi tiết của các nhân vật trong phim:</p><p><strong>1. Thúy Kiều</strong></p><p>* Tên: Thúy Kiều<br>* Tuổi: 22<br>* Nghề nghiệp: Sinh viên đại học<br>* Ngoại hình: Thúy Kiều là một cô gái xinh đẹp với mái tóc đen dài, đôi mắt nâu sáng, và thân hình mảnh mai. Cô thường mặc trang phục nữ tính và thanh lịch.<br>* Tính cách: Thúy Kiều là một cô gái thông minh, tự tin, và độc lập. Cô có khả năng phân tích tình huống và đưa ra quyết định sáng suốt. Tuy nhiên, cô cũng có thể bị ảnh hưởng bởi cảm xúc và đôi khi đưa ra quyết định vội vàng.<br>* Backstory: Thúy Kiều đến từ một gia đình trung lưu, với bố mẹ yêu thương và hỗ trợ cô trong mọi quyết định. Cô đã lớn lên với một môi trường an toàn và ổn định, nhưng cũng cảm thấy bị gò bó bởi áp lực của xã hội và gia đình.<br>* Động lực: Thúy Kiều muốn tìm kiếm hạnh phúc và tự do trong cuộc sống, nhưng cũng phải đối mặt với áp lực của xã hội và gia đình.<br>* Arc phát triển dự kiến: Thúy Kiều sẽ phải đối mặt với các lựa chọn khó khăn và quyết định liệu có nên theo đuổi tình yêu với chàng trai tài năng hay giữ gìn danh dự và bảo vệ bản thân.<br>* Mối quan hệ với nhân vật khác: Thúy Kiều sẽ có mối quan hệ lãng mạn với chàng trai tài năng, nhưng cũng sẽ phải đối mặt với sự phản đối của gia đình và xã hội.</p><p><strong>2. Chàng trai tài năng (Minh)</strong></p><p>* Tên: Minh<br>* Tuổi: 25<br>* Nghề nghiệp: Nhạc sĩ<br>* Ngoại hình: Minh là một chàng trai tài năng với mái tóc ngắn, đôi mắt xanh sáng, và thân hình cường tráng. Cô thường mặc trang phục casual và thoải mái.<br>* Tính cách: Minh là một chàng trai tự tin, sáng tạo, và đam mê âm nhạc. Cô có khả năng sáng tạo và đổi mới, nhưng cũng có thể bị ảnh hưởng bởi quá khứ và cảm xúc.<br>* Backstory: Minh đến từ một gia đình nghèo, với bố mẹ ly hôn và cô phải tự lực cánh sinh từ nhỏ. Cô đã lớn lên với một môi trường khó khăn và bất ổn, nhưng cũng cảm thấy tự do và độc lập.<br>* Động lực: Minh muốn theo đuổi đam mê âm nhạc và tìm kiếm hạnh phúc, nhưng cũng phải đối mặt với áp lực của quá khứ và cảm xúc.<br>* Arc phát triển dự kiến: Minh sẽ phải đối mặt với các thách thức và quyết định liệu có nên tiếp tục theo đuổi đam mê âm nhạc hay tìm kiếm một con đường khác.<br>* Mối quan hệ với nhân vật khác: Minh sẽ có mối quan hệ lãng mạn với Thúy Kiều, nhưng cũng sẽ phải đối mặt với sự phản đối của gia đình và xã hội.</p><p><strong>3. Bố của Thúy Kiều (Ông Quang)</strong></p><p>* Tên: Ông Quang<br>* Tuổi: 50<br>* Nghề nghiệp: Doanh nhân<br>* Ngoại hình: Ông Quang là một người đàn ông trung tuổi với mái tóc bạc, đôi mắt nâu sáng, và thân hình cường tráng. Cô thường mặc trang phục trang trọng và nghiêm túc.<br>* Tính cách: Ông Quang là một người đàn ông nghiêm túc, bảo thủ, và yêu thương gia đình. Cô có khả năng đưa ra quyết định sáng suốt, nhưng cũng có thể bị ảnh hưởng bởi quan điểm truyền thống và áp lực của xã hội.<br>* Backstory: Ông Quang đến từ một gia đình trung lưu, với bố mẹ yêu thương và hỗ trợ cô trong mọi quyết định. Cô đã lớn lên với một môi trường an toàn và ổn định, nhưng cũng cảm thấy bị gò bó bởi áp lực của xã hội và gia đình.<br>* Động lực: Ông Quang muốn bảo vệ gia đình và duy trì danh dự, nhưng cũng phải đối mặt với áp lực của xã hội và cảm xúc.<br>* Arc phát triển dự kiến: Ông Quang sẽ phải đối mặt với các thách thức và quyết định liệu có nên tiếp tục bảo vệ gia đình và duy trì danh dự hay tìm kiếm một con đường khác.<br>* Mối quan hệ với nhân vật khác: Ông Quang sẽ có mối quan hệ gần gũi với Thúy Kiều, nhưng cũng sẽ phải đối mặt với sự phản đối của cô khi cô quyết định theo đuổi tình yêu với Minh.</p><p><strong>4. Mẹ của Thúy Kiều (Bà Liên)</strong></p><p>* Tên: Bà Liên<br>* Tuổi: 45<br>* Nghề nghiệp: Giáo viên<br>* Ngoại hình: Bà Liên là một người phụ nữ trung tuổi với mái tóc đen, đôi mắt nâu sáng, và thân hình mảnh mai. Cô thường mặc trang phục nữ tính và thanh lịch.<br>* Tính cách: Bà Liên là một người phụ nữ yêu thương, thông cảm, và hiểu biết. Cô có khả năng đưa ra quyết định sáng suốt, nhưng cũng có thể bị ảnh hưởng bởi cảm xúc và quan điểm truyền thống.<br>* Backstory: Bà Liên đến từ một gia đình trung lưu, với bố mẹ yêu thương và hỗ trợ cô trong mọi quyết định. Cô đã lớn lên với một môi trường an toàn và ổn định, nhưng cũng cảm thấy bị gò bó bởi áp lực của xã hội và gia đình.<br>* Động lực: Bà Liên muốn bảo vệ gia đình và duy trì danh dự, nhưng cũng phải đối mặt với áp lực của xã hội và cảm xúc.<br>* Arc phát triển dự kiến: Bà Liên sẽ phải đối mặt với các thách thức và quyết định liệu có nên tiếp tục bảo vệ gia đình và duy trì danh dự hay tìm kiếm một con đường khác.<br>* Mối quan hệ với nhân vật khác: Bà Liên sẽ có mối quan hệ gần gũi với Thúy Kiều, nhưng cũng sẽ phải đối mặt với sự phản đối của cô khi cô quyết định theo đuổi tình yêu với Minh.</p><p>Những nhân vật này sẽ tạo nên một câu chuyện đầy thách thức và cảm động, khám phá cuộc chiến đấu nội tâm của một cô gái trẻ khi phải đối mặt với các lựa chọn khó khăn và thử thách trong cuộc sống.</p>', '2026-02-04 02:35:33'),
(3, 14, 'screenplay', '{\"logline\":\"📝 LOGLINE CHÍNHMột chàng tiều phu nghèo phải đối mặt với thử thách sinh tồn khi chiếc rìu của mình bị rơi xuống sông, nhưng nhờ sự giúp đỡ của một ông cụ bí ẩn, anh phải vượt qua cám dỗ và chứng minh sự trung thực của mình. Với sự giúp đỡ của ông cụ, anh chàng tiều phu không chỉ tìm lại được chiếc rìu mà còn nhận được những phần thưởng bất ngờ.🔍 PHÂN TÍCH CÁC YẾU TỐNhân vật chính: Một chàng tiều phu nghèo, mồ côi cha mẹ từ nhỏ, chỉ có một chiếc rìu để kiếm sống.Mục tiêu: Tìm lại chiếc rìu bị rơi xuống sông để tiếp tục kiếm sống.Xung đột: Chiếc rìu bị rơi xuống sông và anh không thể lấy lại được, phải đối mặt với cám dỗ khi ông cụ tìm được những chiếc rìu bằng bạc và vàng.Stakes: Nếu không tìm lại được chiếc rìu, anh chàng tiều phu sẽ không có cách nào để kiếm sống và sẽ phải đối mặt với đói nghèo và tuyệt vọng.Thể loại: Phim fantasy,冒險, với yếu tố thần thoại và giáo dục về sự trung thực và lòng biết ơn.💡 LOGLINE THAY THẾKhi một chàng tiều phu nghèo mất chiếc rìu vào sông, ông phải đối mặt với một thử thách lớn để lấy lại nó, nhưng sự giúp đỡ của một ông cụ bí ẩn sẽ thay đổi mọi thứ.Trong một thế giới đầy rẫy những cám dỗ, một chàng tiều phu nghèo phải chứng minh sự trung thực của mình để nhận được sự giúp đỡ từ một ông cụ bí ẩn và tìm lại chiếc rìu quý giá của mình.Với sự giúp đỡ của một ông cụ bí ẩn, một chàng tiều phu nghèo không chỉ tìm lại được chiếc rìu mà còn học được bài học quý giá về sự trung thực và lòng biết ơn.\",\"theme\":\"🎯 CHỦ ĐỀ CHÍNHSự trung thực và khiêm tốn là chìa khóa để đạt được thành công và hạnh phúc thật sự.❓ CÂU HỎI CHỦ ĐỀLiệu một người có thể đạt được thành công và hạnh phúc bằng cách trung thực và khiêm tốn, hay họ cần phải dựa vào may mắn hoặc thủ đoạn?🔄 LIE vs TRUTHLIE (Điều nhân vật tin sai): Tôi cần phải dựa vào may mắn hoặc thủ đoạn để đạt được thành công và hạnh phúc.TRUTH (Sự thật cần học): Sự trung thực, khiêm tốn và nỗ lực là những yếu tố quan trọng nhất để đạt được thành công và hạnh phúc thật sự.Cách nhân vật học được sự thật: Qua quá trình tìm kiếm chiếc rìu bị mất, nhân vật sẽ phải đối mặt với các cám dỗ và thử thách, nhưng với sự giúp đỡ của ông cụ bí ẩn, anh sẽ học được giá trị của sự trung thực và khiêm tốn, và nhận ra rằng thành công và hạnh phúc đến từ việc trung thực và nỗ lực.📚 CHỦ ĐỀ PHỤGiá trị của sự giúp đỡ và hướng dẫn: Ông cụ bí ẩn sẽ giúp nhân vật vượt qua khó khăn và học được bài học quý giá.Cám dỗ và thử thách: Nhân vật sẽ phải đối mặt với các cám dỗ và thử thách, nhưng sẽ học được cách vượt qua chúng bằng sự trung thực và khiêm tốn.🎬 CÁCH THỂ HIỆN CHỦ ĐỀQua hành động: Hành trình tìm kiếm chiếc rìu của nhân vật sẽ thể hiện sự trung thực và nỗ lực của anh.Qua đối thoại: Ông cụ bí ẩn sẽ chia sẻ những lời khuyên và bài học quý giá với nhân vật, giúp anh học được sự trung thực và khiêm tốn.Qua hình ảnh/biểu tượng: Chiếc rìu bị mất sẽ trở thành biểu tượng cho sự mất mát và khó khăn, nhưng cũng là cơ hội cho nhân vật học được bài học quý giá về sự trung thực và khiêm tốn.\",\"character_count\":\"\"}', '<h2>🦸 NHÂN VẬT CHÍNH (PROTAGONIST)</h2><br><h3>Tào</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 25 tuổi, tiều phu</li></ul><br><ul><li><strong>Ngoại hình:</strong> Cao, gầy, tóc đen, đôi mắt nâu</li></ul><br><ul><li><strong>Tính cách:</strong> Trung thực, chăm chỉ, nhưng đôi khi quá tự ti và thiếu tự tin</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Thiếu tự tin và hay dựa vào may mắn</li></ul><br><ul><li><strong>Backstory:</strong> Mồ côi cha mẹ từ nhỏ, sống một mình và phải tự lực kiếm sống từ rất sớm</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Mất mát cha mẹ và cảm giác bất an khi không có ai để dựa dẫm</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Tìm lại chiếc rìu và tiếp tục kiếm sống</li></ul><br><ul><li><strong>NEED (Cần):</strong> Học được giá trị của sự trung thực và khiêm tốn để đạt được thành công và hạnh phúc thật sự</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Từ một người thiếu tự tin và dựa vào may mắn, trở thành một người tự tin và trung thực, hiểu được giá trị của sự nỗ lực và khiêm tốn</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Thể hiện sự trung thực và khiêm tốn là chìa khóa để đạt được thành công và hạnh phúc thật sự</li></ul></p><p><h2>😈 NHÂN VẬT ĐỐI KHÁNG (ANTAGONIST)</h2><br><h3>Cám dỗ</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> Không xác định, hiện thân của cám dỗ</li></ul><br><ul><li><strong>Ngoại hình:</strong> Đẹp, quyến rũ, với khả năng thay đổi hình dạng</li></ul><br><ul><li><strong>Tính cách:</strong> Xảo quyệt, lừa đảo, luôn tìm cách làm cho Tào sa vào cám dỗ</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Không thể tồn tại khi đối mặt với sự trung thực và khiêm tốn</li></ul><br><ul><li><strong>Backstory:</strong> Là hiện thân của cám dỗ, luôn tìm cách phá hoại sự trung thực và khiêm tốn của con người</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Không có, vì không phải là một nhân vật có cảm xúc</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Làm cho Tào sa vào cám dỗ và mất đi sự trung thực</li></ul><br><ul><li><strong>NEED (Cần):</strong> Không có, vì không phải là một nhân vật có nhu cầu</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Không thay đổi, vì luôn là hiện thân của cám dỗ</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Thể hiện sự đối lập với sự trung thực và khiêm tốn, làm cho Tào phải đối mặt với thử thách và học được bài học quý giá</li></ul></p><p><h2>👥 NHÂN VẬT PHỤ</h2><br><h3>Ông Cụ Bí Ẩn</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> Không xác định, có khả năng siêu nhiên</li></ul><br><ul><li><strong>Ngoại hình:</strong> Già, tóc trắng, đôi mắt sáng</li></ul><br><ul><li><strong>Tính cách:</strong> Khôn ngoan, nhân từ, luôn sẵn sàng giúp đỡ</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Không có, vì là một nhân vật hoàn hảo</li></ul><br><ul><li><strong>Backstory:</strong> Có khả năng siêu nhiên, luôn tìm cách giúp đỡ những người cần</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Không có, vì không phải là một nhân vật có cảm xúc</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Giúp Tào tìm lại chiếc rìu và học được bài học quý giá</li></ul><br><ul><li><strong>NEED (Cần):</strong> Không có, vì không phải là một nhân vật có nhu cầu</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Không thay đổi, vì luôn là một nhân vật hoàn hảo</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Thể hiện sự giúp đỡ và hướng dẫn, giúp Tào học được bài học quý giá về sự trung thực và khiêm tốn</li></ul></p><p><h2>🔗 SƠ ĐỒ MỐI QUAN HỆ</h2><br><ul><li>Tào và Cám dỗ: Đối lập, luôn tìm cách vượt qua cám dỗ</li></ul><br><ul><li>Tào và Ông Cụ Bí Ẩn: Đồng minh, luôn nhận được sự giúp đỡ và hướng dẫn</li></ul><br><ul><li>Cám dỗ và Ông Cụ Bí Ẩn: Đối lập, luôn tìm cách phá hoại sự trung thực và khiêm tốn của Tào</li></ul>', '2026-02-12 03:53:36'),
(4, 18, 'screenplay', '{\"logline\":\"Một nhà khoa học đơn độc ở thành phố New York hậu tận thế chạy đua với thời gian để tìm ra phương thuốc chữa trị một dịch bệnh chết người trong khi phải trốn tránh những kẻ săn lùng đột biến không ngừng truy đuổi.\",\"theme\":\"🎯 CHỦ ĐỀ CHÍNHSự sống còn và hy vọng trong tình cảnh tuyệt vọng, nơi con người phải đối mặt với những thách thức không thể vượt qua và tìm ra cách để tồn tại và chữa lành.❓ CÂU HỎI CHỦ ĐỀLiệu con người có thể tìm ra hy vọng và phương thức chữa trị trong một thế giới bị tàn phá bởi dịch bệnh và những kẻ săn lùng đột biến, hay họ sẽ bị nhấn chìm trong tuyệt vọng?🔄 LIE vs TRUTHLIE (Điều nhân vật tin sai): Nhân vật tin rằng chỉ có thể tự mình vượt qua khó khăn và không cần sự giúp đỡ của người khác, rằng sự sống còn chỉ dựa vào sức mạnh và trí tuệ cá nhân.TRUTH (Sự thật cần học): Sự thật là sự sống còn và chữa lành không chỉ dựa vào sức mạnh cá nhân, mà còn cần sự hợp tác, lòng nhân ái và sự đồng cảm với những người xung quanh, ngay cả trong tình cảnh tuyệt vọng.Cách nhân vật học được sự thật: Qua quá trình chiến đấu để tìm ra phương thuốc chữa trị và trốn tránh những kẻ săn lùng, nhân vật sẽ gặp gỡ những người khác cũng đang chiến đấu để tồn tại, và từ đó học được giá trị của sự hợp tác, lòng nhân ái và sự đồng cảm, nhận ra rằng chỉ có cùng nhau, họ mới có thể vượt qua khó khăn và tìm ra hy vọng.📚 CHỦ ĐỀ PHỤSự IMPORTANCE của sự hợp tác và đồng đội trong tình cảnh khó khăn.Ảnh hưởng của tuyệt vọng và sợ hãi đối với con người và cách họ phản ứng trước những thách thức.🎬 CÁCH THỂ HIỆN CHỦ ĐỀQua hành động: Nhân vật sẽ tham gia vào các hoạt động như tìm kiếm vật phẩm, xây dựng nơi ẩn náu, và chiến đấu chống lại những kẻ săn lùng, thể hiện sự quyết tâm và lòng kiên nhẫn của họ.Qua đối thoại: Nhân vật sẽ có những cuộc trò chuyện với những người khác về hy vọng, sự sống còn, và cách họ có thể giúp đỡ nhau, thể hiện sự thay đổi trong quan điểm và sự phát triển của nhân vật.Qua hình ảnh/biểu tượng: Hình ảnh của thành phố New York hậu tận thế, những kẻ săn lùng đột biến, và các biểu tượng của hy vọng như ánh sáng, hoa lá, sẽ được sử dụng để thể hiện chủ đề và tạo ra không khí u ám nhưng cũng đầy hy vọng.\",\"character_count\":\"\"}', '<h2>🦸 NHÂN VẬT CHÍNH (PROTAGONIST)</h2><br><h3>Dr. Emma Taylor</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 35 tuổi, Nhà khoa học chuyên về dịch tễ và miễn dịch</li></ul><br><ul><li><strong>Ngoại hình:</strong> Nữ, tóc nâu, mắt xanh, cao 1m65, gầy nhưng khỏe mạnh</li></ul><br><ul><li><strong>Tính cách:</strong> Cô là một người độc lập, tự lực, và quyết tâm. Cô luôn đặt công việc lên hàng đầu và sẵn sàng hy sinh bản thân để đạt được mục tiêu.</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Cô có xu hướng tự cô lập mình với những người khác và không tin tưởng vào sự giúp đỡ của người khác.</li></ul><br><ul><li><strong>Backstory:</strong> Cô mất gia đình trong dịch bệnh và từ đó cô quyết tâm tìm ra phương thuốc chữa trị để không ai phải trải qua nỗi đau như cô.</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Cô bị ám ảnh bởi việc không thể cứu được gia đình mình và cảm thấy có lỗi vì không thể ngăn chặn dịch bệnh.</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Cô muốn tìm ra phương thuốc chữa trị dịch bệnh và tiêu diệt những kẻ săn lùng đột biến.</li></ul><br><ul><li><strong>NEED (Cần):</strong> Cô cần học cách tin tưởng và hợp tác với những người khác để đạt được mục tiêu và tìm ra hy vọng.</li></ul><br><ul><li><strong>Arc dự kiến:</strong> [Từ một người độc lập và tự lực → trở thành một người học cách tin tưởng và hợp tác với những người khác]</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Cô thể hiện sự sống còn và hy vọng trong tình cảnh tuyệt vọng, và học cách tìm ra giá trị của sự hợp tác và lòng nhân ái.</li></ul></p><p><h2>😈 NHÂN VẬT ĐỐI KHÁNG (ANTAGONIST)</h2><br><h3>The Leader (Lãnh đạo của những kẻ săn lùng đột biến)</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> Không rõ tuổi, Lãnh đạo của những kẻ săn lùng đột biến</li></ul><br><ul><li><strong>Ngoại hình:</strong> Nam, cao lớn, mạnh mẽ, với những đặc điểm đột biến rõ ràng</li></ul><br><ul><li><strong>Tính cách:</strong> Anh ta là một người lãnh đạo tàn bạo và không có lòng thương xót. Anh ta chỉ quan tâm đến việc bảo vệ và mở rộng lãnh thổ của những kẻ săn lùng đột biến.</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Anh ta quá tự tin vào sức mạnh và khả năng của mình, và không thể hiểu được giá trị của sự hợp tác và lòng nhân ái.</li></ul><br><ul><li><strong>Backstory:</strong> Anh ta là một trong những người đầu tiên bị đột biến và đã trở thành lãnh đạo của những kẻ săn lùng đột biến.</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Anh ta bị ám ảnh bởi việc bị ruồng bỏ và sợ hãi bởi con người trước khi trở thành lãnh đạo của những kẻ săn lùng đột biến.</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Anh ta muốn tiêu diệt tất cả những người còn sống sót và kiểm soát thành phố New York.</li></ul><br><ul><li><strong>NEED (Cần):</strong> Anh ta cần học cách hiểu được giá trị của sự hợp tác và lòng nhân ái, nhưng điều này không thể xảy ra do tính cách và vai trò của anh ta.</li></ul><br><ul><li><strong>Arc dự kiến:</strong> [Không thay đổi, vẫn tiếp tục là một người lãnh đạo tàn bạo và không có lòng thương xót]</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Anh ta thể hiện sự đối lập với Dr. Emma Taylor, và là gương phản chiếu của cô. Anh ta cho thấy sự sống còn và hy vọng không chỉ dựa vào sức mạnh và khả năng cá nhân, mà còn cần sự hợp tác và lòng nhân ái.</li></ul></p><p><h2>👥 NHÂN VẬT PHỤ</h2><br><h3>Dr. Liam Chen - Người bạn và đồng nghiệp của Dr. Emma Taylor</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 30 tuổi, Nhà khoa học chuyên về công nghệ sinh học</li></ul><br><ul><li><strong>Ngoại hình:</strong> Nam, tóc đen, mắt nâu, cao 1m70, gầy nhưng khỏe mạnh</li></ul><br><ul><li><strong>Tính cách:</strong> Anh ta là một người thân thiện, hòa đồng, và luôn sẵn sàng giúp đỡ những người khác.</li></ul><br><ul><li><strong>Vai trò:</strong> Anh ta giúp Dr. Emma Taylor tìm ra phương thuốc chữa trị dịch bệnh và trở thành một người bạn và đồng nghiệp đáng tin cậy.</li></ul></p><p><h3>Maya - Một cô gái trẻ sống sót sau dịch bệnh</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 15 tuổi, Học sinh</li></ul><br><ul><li><strong>Ngoại hình:</strong> Nữ, tóc vàng, mắt xanh, thấp và gầy</li></ul><br><ul><li><strong>Tính cách:</strong> Cô là một người Optimistic, năng động, và luôn tìm cách giúp đỡ những người khác.</li></ul><br><ul><li><strong>Vai trò:</strong> Cô trở thành một người bạn và đồng minh của Dr. Emma Taylor, và giúp cô học cách tin tưởng và hợp tác với những người khác.</li></ul></p><p><h2>🔗 SƠ ĐỒ MỐI QUAN HỆ</h2><br><ul><li>Dr. Emma Taylor và Dr. Liam Chen: Đồng nghiệp và bạn bè</li></ul><br><ul><li>Dr. Emma Taylor và Maya: Người bảo vệ và người được bảo vệ</li></ul><br><ul><li>Dr. Emma Taylor và The Leader: Đối thủ và kẻ thù</li></ul><br><ul><li>Dr. Liam Chen và Maya: Người bạn và đồng minh</li></ul><br><ul><li>The Leader và những kẻ săn lùng đột biến: Lãnh đạo và thuộc hạ</li></ul>', '2026-02-12 04:05:40'),
(5, 23, 'story', '{\"theme\":\"Tuyệt vời! Dưới đây là phân tích chủ đề của câu chuyện \\\"Ba Lưỡi Rìu\\\" dựa trên nội dung bạn cung cấp:🎯 CHỦ ĐỀ CHÍNHSự trung thực và lòng tốt sẽ được đền đáp xứng đáng.❓ CÂU HỎI CHỦ ĐỀLiệu sự trung thực và không tham lam có mang lại may mắn và phần thưởng cho người nghèo khó?🔄 LIE vs TRUTHLIE (Điều nhân vật tin sai): Anh tiều phu có thể không tin rằng sự trung thực sẽ giúp anh thoát khỏi cảnh nghèo khó, hoặc có thể nghĩ rằng việc nhận một chiếc rìu giá trị hơn sẽ giúp anh đổi đời.TRUTH (Sự thật cần học): Sự trung thực và lòng tốt là những phẩm chất đáng quý và sẽ được đền đáp, thậm chí còn mang lại những điều tốt đẹp hơn mong đợi.Cách nhân vật học được sự thật: Anh tiều phu đã chứng minh sự trung thực của mình khi từ chối nhận những chiếc rìu bằng vàng và bạc không phải của mình. Chính sự trung thực này đã khiến anh được ông cụ (bụt) khen ngợi và ban thưởng.📚 CHỦ ĐỀ PHỤGiá trị của tài sản: Truyện cho thấy giá trị thực sự của một vật nằm ở công dụng và ý nghĩa của nó đối với người sở hữu, chứ không phải giá trị vật chất đơn thuần. Chiếc rìu sắt tuy không quý giá nhưng lại là công cụ kiếm sống quan trọng của anh tiều phu.Sự giúp đỡ và lòng trắc ẩn: Ông cụ (bụt) xuất hiện để giúp đỡ anh tiều phu nghèo khó, thể hiện lòng trắc ẩn và sự quan tâm đến những người gặp khó khăn.🎬 CÁCH THỂ HIỆN CHỦ ĐỀQua hành động:    - Anh tiều phu từ chối nhận rìu bạc và rìu vàng: Hành động này thể hiện sự trung thực và không tham lam của anh.    - Ông cụ (bụt) lặn xuống sông ba lần để tìm rìu: Thể hiện sự kiên nhẫn và lòng tốt muốn giúp đỡ người khác.Qua đối thoại:    - Câu trả lời trung thực của anh tiều phu khi ông cụ hỏi về chiếc rìu bị mất: \\\"Không phải lưỡi rìu của cháu cụ ạ, lưỡi rìu của cháu bằng sắt cơ.\\\"    - Lời khen của ông cụ khi trao thưởng cho anh tiều phu: \\\"Con quả là người thật thà và trung thực, không hề ham tiền bạc và lợi lộc. Nay ta tặng thêm cho con hai lưỡi rìu bằng vàng và bạc này.\\\"Qua hình ảnh/biểu tượng:    - Ba chiếc rìu (sắt, bạc, vàng): Biểu tượng cho giá trị vật chất khác nhau và sự lựa chọn giữa sự trung thực và lòng tham.    - Hình ảnh ông cụ tóc bạc, râu dài: Biểu tượng cho sự khôn ngoan, lòng tốt và sức mạnh siêu nhiên.\",\"story_content\":\"Ba lưỡi rìu\\nXưa có một anh chàng tiều phu nghèo, cha mẹ anh bệnh nặng nên qua đời sớm, anh phải sống mồ côi cha mẹ từ nhỏ và tài sản của anh chỉ có một chiếc rìu. Hàng ngày anh phải xách rìu vào rừng để đốn củi bán để lấy tiền kiếm sống qua ngày. Cạnh bìa rừng có một con sông nước chảy rất xiết, ai đó lỡ trượt chân rơi xuống sông thì rất khó bơi vào bờ.\\n\\nMột hôm, như thường ngày chàng tiều phu vác rìu vào rừng để đốn củi, trong lúc đang chặt củi cạnh bờ sông thì chẳng may chiếc rìu của chàng bị gãy cán và lưỡi rìu văng xuống sông. Vì dòng sông nước chảy quá xiết nên mặc dù biết bơi nhưng anh chàng vẫn không thể xuống sông để tìm lưỡi rìu. Thất vọng anh chàng tiều phu ngồi khóc than thở.\\n\\nBỗng từ đâu đó có một ông cụ tóc trắng bạc phơ, râu dài, đôi mắt rất hiền từ xuất hiện trước mặt chàng, ông cụ nhìn chàng tiêu phu và hỏi:\\n\\n-Này con, con đang có chuyện gì mà ta thấy con khóc và buồn bã như vậy?\\n\\nAnh chàng tiều phu trả lời ông cụ:\\n\\n-Thưa cụ, bố mẹ cháu mất sớm, cháu phải sống mồ côi từ nhỏ, gia cảnh nhà cháu rất nghèo, tài sản duy nhất của cháu là chiếc rìu sắt mà bố mẹ cháu trước lúc qua đời để lại. Có chiếc rìu đó cháu còn vào rừng đốn củi kiếm sống qua ngày, giờ đây nó đã bị rơi xuống sông, cháu không biết lấy gì để kiếm sống qua ngày nữa. Vì vậy cháu buồn lắm cụ ạ!\\n\\nÔng cụ đáp lời chàng tiều phu:\\n\\n-Ta tưởng chuyện gì lớn, cháu đừng khóc nữa, để ta lặn xuống sông lấy hộ cháu chiếc rìu lên.\\n\\nDứt lời, ông cụ lao mình xuống dòng sông đang chảy rất xiết. Một lúc sau, ông cụ ngoi lên khỏi mặt nước tay cầm một chiếc rìu bằng bạc sáng loáng và hỏi anh chàng tiều phu nghèo:\\n\\n– Đây có phải lưỡi rìu mà con đã làm rơi xuống không ?\\n\\nAnh chàng tiều phu nhìn lưỡi rìu bằng bạc thấy không phải của mình nên anh lắc đầu và bảo ông cụ:\\n\\n– Không phải lưỡi rìu của cháu cụ ạ, lưỡi rìu của cháu bằng sắt cơ.\\n\\nLần thứ hai, ông cụ lại lao mình xuống dòng sông chảy xiết để tìm chiếc rìu cho chàng tiều phu. Một lúc sau, ông cụ ngoi lên khỏi mặt nước tay cầm chiếc rìu bằng vàng và hỏi chàng tiều phu:\\n\\n-Đây có phải là lưỡi rìu mà con đã sơ ý làm rơi xuống sông không?\\n\\nAnh chàng tiều phu nhìn lưỡi rìu bằng vàng sáng chói, anh lại lắc đầu và bảo:\\n\\n-Không phải là lưỡi rìu của con cụ ạ\\n\\nLần thứ ba, ông cụ lại lao mình xuống sông và lần này khi lên ông cụ cầm trên tay là chiếc rìu bằng sắt của anh chàng tiều phu đánh rơi. Ông cụ lại hỏi:\\n\\n-Vậy đây có phải là lưỡi rìu của con không!\\n\\nThấy đúng là lưỡi rìu của mình rồi, anh chàng tiều phu reo lên sung sướng:\\n\\n-Vâng cụ, đây đúng là lưỡi rìu của con, con cảm ơn cụ đã tìm hộ con lưỡi rìu để con có cái đốn củi kiếm sống qua ngày.\\n\\nÔng cụ đưa cho anh chàng tiều phu lưỡi rìu bằng sắt của anh và khen:\\n\\n-Con quả là người thật thà và trung thực, không hề ham tiền bạc và lợi lộc. Nay ta tặng thêm cho con hai lưỡi rìu bằng vàng và bạc này. Đây là quà ta tặng con, con cứ vui vẻ nhận.\\n\\nAnh chàng tiều phu vui vẻ đỡ lấy hai lưỡi rìu mà ông cụ tặng và cảm tạ. Ông cụ hóa phép và biến mất. Lúc đó anh chàng tiều phu mới biết rằng mình vừa được bụt giúp đỡ.\"}', '<p>Tuyệt vời! Dưới đây là hồ sơ nhân vật chi tiết dựa trên câu chuyện \"Ba Lưỡi Rìu\" bạn cung cấp, tập trung vào các yếu tố quan trọng như tính cách, động lực, và vai trò của họ trong việc thể hiện chủ đề của câu chuyện.</p><p><h2>🦸 NHÂN VẬT CHÍNH (PROTAGONIST)</h2><br><h3>ANH TIỀU PHU</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> Trẻ tuổi, tiều phu (người đốn củi)</li></ul><br><ul><li><strong>Ngoại hình:</strong> Không được mô tả chi tiết, nhưng có thể hình dung là một người gầy gò, lam lũ vì cuộc sống khó khăn.</li></ul><br><ul><li><strong>Tính cách:</strong> Thật thà, chất phác, chăm chỉ, hiền lành, có lòng tự trọng.</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Nghèo khó, có thể thiếu tự tin do hoàn cảnh.</li></ul><br><ul><li><strong>Backstory:</strong> Mồ côi cha mẹ từ nhỏ, lớn lên trong nghèo khó, tài sản duy nhất là chiếc rìu.</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Sự mất mát cha mẹ và nỗi lo cơm áo gạo tiền luôn ám ảnh anh.</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Có đủ tiền để sống qua ngày, thoát khỏi cảnh nghèo khó.</li></ul><br><ul><li><strong>NEED (Cần):</strong> Giữ vững sự trung thực và lòng tốt, nhận ra giá trị thực sự của bản thân và cuộc sống.</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Từ một người tiều phu nghèo khó, lo lắng về cuộc sống → trở thành một người được đền đáp xứng đáng vì sự trung thực của mình, có cuộc sống tốt đẹp hơn.</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Thể hiện rằng sự trung thực và lòng tốt sẽ được đền đáp, và những phẩm chất này quan trọng hơn vật chất.</li></ul></p><p><h2>😈 NHÂN VẬT ĐỐI KHÁNG (ANTAGONIST)</h2><br>Không có nhân vật phản diện rõ ràng trong câu chuyện này. Tuy nhiên, <strong>SỰ NGHÈO KHÓ</strong> và <strong>CƠ HỘI ĐỂ THAM LAM</strong> có thể được xem là lực cản mà nhân vật chính phải vượt qua.</p><p><ul><li><strong>Sự Nghèo Khó:</strong> Là hoàn cảnh khó khăn mà anh tiều phu phải đối mặt hàng ngày, tạo ra áp lực và cám dỗ để anh có thể chọn con đường không trung thực.</li></ul><br><ul><li><strong>Cơ Hội Để Tham Lam:</strong> Sự xuất hiện của những chiếc rìu bằng vàng và bạc là một thử thách. Anh tiều phu có thể dễ dàng nói dối để có được những tài sản giá trị này.</li></ul></p><p>Việc anh tiều phu vượt qua những \"thế lực\" này bằng sự trung thực cho thấy sức mạnh của phẩm chất tốt đẹp và chiến thắng của nó trước những khó khăn và cám dỗ.</p><p><h2>👥 NHÂN VẬT PHỤ</h2><br><h3>ÔNG CỤ (BỤT)</h3><br><ul><li><strong>Vai trò:</strong> Người thử thách và ban thưởng.</li></ul><br><ul><li><strong>Tính cách:</strong> Hiền từ, nhân hậu, có phép thuật, công bằng.</li></ul><br><ul><li><strong>Mục đích:</strong> Thử thách lòng trung thực của anh tiều phu và ban thưởng cho những người có phẩm chất tốt đẹp.</li></ul><br><ul><li><strong>Mối quan hệ với protagonist:</strong> Người giúp đỡ, ân nhân.</li></ul></p><p><h2>🔗 SƠ ĐỒ MỐI QUAN HỆ</h2><br><ul><li><strong>Anh Tiều Phu ↔ Ông Cụ (Bụt):</strong> Mối quan hệ giữa người gặp khó khăn và người giúp đỡ. Ông cụ đóng vai trò như một người thử thách và sau đó là ân nhân của anh tiều phu.</li></ul><br><ul><li><strong>Anh Tiều Phu ↔ Sự Nghèo Khó:</strong> Mối quan hệ giữa người phải vật lộn với hoàn cảnh và chính hoàn cảnh đó. Sự nghèo khó là động lực để anh tiều phu làm việc chăm chỉ, nhưng cũng là cám dỗ để anh có thể chọn con đường không trung thực.</li></ul><br><ul><li><strong>Anh Tiều Phu ↔ Những Chiếc Rìu (Sắt, Bạc, Vàng):</strong> Biểu tượng cho giá trị vật chất và sự lựa chọn giữa trung thực và lòng tham. Chiếc rìu sắt là công cụ kiếm sống của anh, trong khi rìu bạc và vàng là thử thách về lòng trung thực.</li></ul></p><p>Phân tích này tập trung vào các yếu tố chính trong câu chuyện và làm nổi bật vai trò của từng nhân vật trong việc thể hiện chủ đề về sự trung thực và lòng tốt.<br></p>', '2026-02-28 13:48:47'),
(6, 19, 'screenplay', '{\"logline\":\"LOGLINE CHÍNHNhà khoa học đơn độc Dr. Emma Taylor tìm kiếm phương thuốc chữa trị dịch bệnh trong thành phố New York hậu tận thế, bị truy đuổi bởi những kẻ săn lùng đột biến. Nếu thất bại, loài người sẽ tuyệt chủng. PHÂN TÍCH CÁC YẾU TỐNhân vật chính: Dr. Emma Taylor, một nhà khoa học thông minh và quyết tâm.Mục tiêu: Tìm ra phương thức chữa trị dịch bệnh.Xung đột: Những kẻ săn lùng đột biến và áp lực thời gian.Stakes: Loài người sẽ tuyệt chủng nếu không tìm được phương thuốc.Thể loại: Khoa học viễn tưởng, hậu tận thế.💡 LOGLINE THAY THẾTrong thành phố New York bị phá hủy, Dr. Emma Taylor phải chạy trốn khỏi những kẻ đột biến hung dữ để tìm ra phương thuốc chữa trị dịch bệnh trước khi quá muộn.Với thời gian dần cạn kiệt, Dr. Emma Taylor phải đối mặt với nỗi sợ hãi và tuyệt vọng khi tìm kiếm phương thuốc chữa trị dịch bệnh trong một thế giới đã sụp đổ.Khi thành phố New York trở thành chiến trường của sự sống còn, Dr. Emma Taylor phải sử dụng tất cả kiến thức và sự quyết tâm của mình để tìm ra phương thuốc chữa trị dịch bệnh và bảo vệ tương lai của loài người.\",\"theme\":\"Tuyệt vời! Dựa trên logline bạn cung cấp, đây là phân tích chủ đề của bộ phim:🎯 CHỦ ĐỀ CHÍNHHy vọng và sự kiên trì của con người có thể chiến thắng nghịch cảnh ngay cả khi đối mặt với sự tuyệt vọng và nguy cơ diệt vong.❓ CÂU HỎI CHỦ ĐỀLiệu một cá nhân có thể cứu cả nhân loại khi đối mặt với những khó khăn không thể vượt qua và sự cô đơn tột cùng?🔄 LIE vs TRUTHLIE (Điều nhân vật tin sai): Dr. Emma Taylor tin rằng khoa học và lý trí là tất cả những gì cô cần để giải quyết vấn đề, và rằng cô phải tự mình làm điều đó vì không ai có thể tin tưởng được trong thế giới tàn khốc này. Cô tin rằng cảm xúc và sự kết nối với người khác là một sự yếu đuối có thể cản trở cô.TRUTH (Sự thật cần học): Dr. Emma Taylor cần học rằng sự kết nối, lòng tin và sự giúp đỡ từ người khác là chìa khóa để vượt qua những thử thách lớn nhất. Cô cần nhận ra rằng hy vọng và sự kiên trì không chỉ đến từ kiến thức khoa học mà còn từ sức mạnh của tinh thần đồng đội và lòng trắc ẩn.Cách nhân vật học được sự thật: Trong hành trình tìm kiếm phương thuốc, Emma buộc phải hợp tác với một nhóm người sống sót, mỗi người có những kỹ năng và kinh nghiệm riêng. Thông qua những khó khăn và thử thách họ cùng nhau vượt qua, Emma dần nhận ra giá trị của sự tin tưởng, lòng trắc ẩn và sức mạnh của cộng đồng. Cô học được rằng đôi khi, sự yếu đuối lại chính là sức mạnh lớn nhất, và rằng hy vọng có thể nảy sinh ngay cả trong những hoàn cảnh tăm tối nhất.📚 CHỦ ĐỀ PHỤSự tha hóa của con người trong bối cảnh hậu tận thế: Hành vi của những kẻ săn lùng đột biến phản ánh sự suy đồi đạo đức và những gì con người có thể làm để tồn tại khi xã hội sụp đổ.Giá trị của khoa học và kiến thức trong việc giải quyết các vấn đề toàn cầu: Sự tận tâm của Dr. Emma Taylor với khoa học thể hiện vai trò quan trọng của kiến thức trong việc tìm kiếm giải pháp cho những thách thức lớn nhất của nhân loại.🎬 CÁCH THỂ HIỆN CHỦ ĐỀQua hành động:    - Emma ban đầu từ chối sự giúp đỡ của người khác, nhưng sau đó buộc phải hợp tác và học cách tin tưởng họ. (LIE vs TRUTH)    - Những kẻ săn lùng đột biến thể hiện sự tàn bạo và ích kỷ, đối lập với lòng trắc ẩn của Emma và những người sống sót khác. (Chủ đề phụ 1)Qua đối thoại:    - Những cuộc trò chuyện giữa Emma và những người sống sót khác, nơi họ chia sẻ hy vọng và nỗi sợ hãi của mình, thể hiện sự kết nối và sức mạnh của cộng đồng.    - Những lời thoại thể hiện sự hoài nghi và bi quan ban đầu của Emma, sau đó dần thay đổi khi cô nhận ra giá trị của sự tin tưởng và hy vọng. (LIE vs TRUTH)Qua hình ảnh/biểu tượng:    - Hình ảnh thành phố New York đổ nát, nhưng vẫn còn những mầm xanh nảy nở, tượng trưng cho hy vọng và sự sống tiếp tục.    - Phòng thí nghiệm của Emma, nơi cô miệt mài nghiên cứu, tượng trưng cho sức mạnh của khoa học và kiến thức.    - Hành động chia sẻ thức ăn và nguồn lực giữa những người sống sót tượng trưng cho sự đoàn kết và lòng trắc ẩn.Phân tích này sẽ giúp bạn định hình câu chuyện, phát triển nhân vật và xây dựng một kết thúc ý nghĩa, truyền tải thông điệp mạnh mẽ về hy vọng và sự kiên trì của con người. Chúc bạn thành công!\",\"character_count\":\"\"}', '<h2>NHÂN VẬT CHÍNH</h2><br><h3>DR. EMMA TAYLOR</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 35, Nhà khoa học (vi sinh vật học, dịch tễ học)</li></ul><br><ul><li><strong>Ngoại hình:</strong> Gầy gò, tóc búi cao, luôn mặc áo blouse trắng lấm bẩn, đôi mắt thâm quầng nhưng ánh lên sự thông minh và kiên định.</li></ul><br><ul><li><strong>Tính cách:</strong> Thông minh, quyết đoán, tận tụy, độc lập, có phần lạnh lùng và xa cách.</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Khó tin tưởng người khác, quá dựa vào lý trí, xem nhẹ cảm xúc và sự kết nối.</li></ul><br><ul><li><strong>Backstory:</strong> Lớn lên trong một gia đình khoa học, bố mẹ đều là những nhà nghiên cứu nổi tiếng. Emma luôn cảm thấy áp lực phải chứng minh bản thân, dẫn đến việc cô tập trung cao độ vào học tập và nghiên cứu, bỏ qua các mối quan hệ cá nhân. Cô mất cả gia đình trong đợt bùng phát dịch bệnh đầu tiên, càng củng cố thêm niềm tin rằng chỉ có khoa học mới có thể cứu rỗi thế giới.</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Mất gia đình và cảm giác tội lỗi vì không thể cứu họ. Cô luôn ám ảnh bởi việc dịch bệnh sẽ lặp lại và hủy diệt loài người.</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Tìm ra phương thuốc chữa trị dịch bệnh và ngăn chặn sự tuyệt chủng của loài người.</li></ul><br><ul><li><strong>NEED (Cần):</strong> Học cách tin tưởng người khác, chấp nhận sự giúp đỡ và nhận ra rằng sức mạnh thực sự nằm ở sự kết nối và lòng trắc ẩn.</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Từ một nhà khoa học đơn độc, lạnh lùng và chỉ tin vào lý trí → trở thành một người lãnh đạo biết tin tưởng, hợp tác và tìm thấy sức mạnh trong sự kết nối với cộng đồng.</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Thể hiện sự kiên trì, hy vọng và sức mạnh của khoa học, nhưng đồng thời cũng cho thấy giới hạn của lý trí và tầm quan trọng của sự kết nối con người. Emma đại diện cho \"LIE\" ban đầu, tin rằng chỉ có khoa học và sự độc lập mới có thể cứu rỗi thế giới, nhưng dần dần học được \"TRUTH\" thông qua hành trình của mình.</li></ul></p><p><h2>NHÂN VẬT PHẢN DIỆN</h2><br><h3>KAI</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 40, Thủ lĩnh nhóm săn lùng đột biến.</li></ul><br><ul><li><strong>Ngoại hình:</strong> To lớn, cơ bắp, nhiều sẹo trên mặt và cơ thể. Ánh mắt hung dữ, tàn nhẫn.</li></ul><br><ul><li><strong>Tính cách:</strong> Tàn bạo, ích kỷ, chỉ quan tâm đến sự sống còn của bản thân và nhóm của mình. Mất niềm tin vào nhân loại.</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Mù quáng tin vào sức mạnh, không tin tưởng ai, sợ hãi sự yếu đuối.</li></ul><br><ul><li><strong>Backstory:</strong> Từng là một người lính cứu hỏa dũng cảm, nhưng sau khi chứng kiến sự sụp đổ của xã hội và sự tàn bạo của dịch bệnh, Kai trở nên mất niềm tin vào nhân loại. Anh ta tin rằng chỉ có sức mạnh và sự tàn nhẫn mới có thể giúp con người sống sót.</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Chứng kiến quá nhiều cái chết và sự tàn phá, mất niềm tin vào lòng tốt của con người.</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Thống trị những người sống sót còn lại, đảm bảo sự sống còn của nhóm mình bằng mọi giá.</li></ul><br><ul><li><strong>NEED (Cần):</strong> Đối mặt với nỗi sợ hãi của bản thân, nhận ra rằng sự tàn bạo không phải là giải pháp, và tìm lại chút lòng trắc ẩn còn sót lại.</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Không thay đổi. Kai củng cố niềm tin sai lầm của mình cho đến khi bị đánh bại, thể hiện sự bế tắc của việc chỉ tin vào sức mạnh và sự tàn nhẫn.</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Kai là GƯƠNG PHẢN CHIẾU của Emma, thể hiện một con đường khác khi đối mặt với sự tuyệt vọng. Anh ta đại diện cho sự tha hóa của con người khi mất đi hy vọng và lòng trắc ẩn. Kai cho thấy điều gì sẽ xảy ra nếu Emma không học được bài học về sự kết nối và lòng tin.</li></ul></p><p><h2>NHÂN VẬT PHỤ</h2><br><h3>LIAM - Mentor/Người bạn</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 50, cựu bác sĩ quân y.</li></ul><br><ul><li><strong>Mô tả:</strong> Một người đàn ông lớn tuổi, từng trải, thông minh và giàu kinh nghiệm. Liam trở thành người cố vấn cho Emma, giúp cô nhìn nhận vấn đề từ nhiều góc độ khác nhau và đưa ra những lời khuyên quý giá. Anh đại diện cho lòng trắc ẩn và sự hy sinh.</li></ul></p><p><h3>CHLOE - Love Interest/Người đồng hành</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 25, kỹ sư cơ khí.</li></ul><br><ul><li><strong>Mô tả:</strong> Một cô gái trẻ mạnh mẽ, thông minh và lạc quan. Chloe giúp Emma sửa chữa các thiết bị, cung cấp hỗ trợ kỹ thuật và mang đến một tia hy vọng trong thế giới tăm tối. Cô đại diện cho sức mạnh của tuổi trẻ và sự kiên cường.</li></ul></p><p><h3>MARCO - Người bảo vệ/Bạn đồng hành bất đắc dĩ</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 30, cựu cảnh sát.</li></ul><br><ul><li><strong>Mô tả:</strong> Một người đàn ông mạnh mẽ, giỏi chiến đấu và có kỹ năng sinh tồn tốt. Marco ban đầu hoài nghi về Emma, nhưng dần dần tin tưởng vào cô và trở thành người bảo vệ trung thành của cô. Anh đại diện cho sự tin tưởng và lòng trung thành.</li></ul></p><p><h2>SƠ ĐỒ MỐI QUAN HỆ</h2><br><ul><li><strong>Emma - Kai:</strong> Đối địch. Kai truy đuổi Emma để chiếm đoạt phương thuốc (hoặc giết cô để loại bỏ mối đe dọa). Họ là hai thái cực đối lập trong cách đối mặt với dịch bệnh và sự tuyệt vọng.</li></ul><br><ul><li><strong>Emma - Liam:</strong> Quan hệ thầy trò, bạn bè. Liam là người cố vấn, giúp Emma vượt qua khó khăn và học cách tin tưởng người khác.</li></ul><br><ul><li><strong>Emma - Chloe:</strong> Quan hệ tình cảm, đồng đội. Chloe mang đến sự lạc quan và hỗ trợ kỹ thuật cho Emma.</li></ul><br><ul><li><strong>Emma - Marco:</strong> Quan hệ từ hoài nghi đến tin tưởng, đồng đội. Marco bảo vệ Emma và giúp cô đối mặt với nguy hiểm.</li></ul><br>', '2026-03-08 08:04:14');
INSERT INTO `characters` (`id`, `project_id`, `type`, `input_data`, `output_data`, `created_at`) VALUES
(7, 29, 'screenplay', '{\"logline\":\"Mời bạn tham khảo những Logline sau: [Thể thao/Drama] Một tiền đạo ngôi sao ngạo mạn, bị ám ảnh bởi chức vô địch World Cup cuối cùng trong sự nghiệp, phải học cách tin tưởng đồng đội và vượt qua chấn thương dai dẳng, nếu không anh sẽ đánh mất vinh quang mãi mãi và sống trong hối hận. [Thể thao/Hài] Một đội bóng nghiệp dư toàn những kẻ lập dị, với mục tiêu giành chiến thắng trong giải đấu địa phương để cứu lấy sân bóng cộng đồng khỏi tay một tập đoàn bất động sản tham lam, phải đối mặt với những đối thủ mạnh hơn và sự thiếu phối hợp hài hước, nếu thất bại, họ sẽ mất đi nơi gắn bó và niềm đam mê duy nhất. [Thể thao/Giật gân] Một trọng tài bóng đá đầy tham vọng, bị ép buộc phải dàn xếp tỷ số một trận đấu quan trọng bởi một tổ chức mafia tàn bạo, phải tìm cách vạch trần sự thật và bảo vệ gia đình mình, nếu không anh sẽ phải trả giá bằng cả sự nghiệp và mạng sống.\",\"theme\":\"CHỦ ĐỀ CHÍNHSự hy sinh vì tập thể và chính trực là con đường duy nhất dẫn đến thành công và hạnh phúc đích thực.CÂU HỎI CHỦ ĐỀLiệu cá nhân có thể vượt qua cái tôi và những cám dỗ để đạt được thành công và sự thanh thản thực sự?LIE vs TRUTHLIE (Điều nhân vật tin sai): Thành công cá nhân và lợi ích trước mắt quan trọng hơn tất cả; gian dối và tham lam là con đường nhanh nhất để đạt được mục đích.TRUTH (Sự thật cần học): Hạnh phúc và thành công bền vững chỉ đến khi đặt lợi ích của tập thể lên trên cá nhân, và sống một cuộc đời chính trực.Cách nhân vật học được sự thật: Thông qua những khó khăn, thử thách, và sự hi sinh của bản thân cũng như những người xung quanh, nhân vật nhận ra rằng sự ích kỷ và gian dối chỉ mang lại đau khổ và thất bại. Họ học cách tin tưởng, hợp tác, và đấu tranh cho những giá trị đúng đắn.CHỦ ĐỀ PHỤ Sức mạnh của cộng đồng trong việc vượt qua khó khăn và bảo vệ những giá trị chung. Sự cám dỗ của quyền lực và tiền bạc có thể làm tha hóa con người, nhưng lòng dũng cảm và sự chính trực có thể chiến thắng.CÁCH THỂ HIỆN CHỦ ĐỀQua hành động:    - Tiền đạo ngôi sao hy sinh cơ hội ghi bàn để đồng đội có vị trí tốt hơn.    - Đội bóng nghiệp dư cùng nhau tập luyện và hỗ trợ lẫn nhau, vượt qua những mâu thuẫn cá nhân.    - Trọng tài từ chối dàn xếp tỷ số, chấp nhận đối mặt với nguy hiểm để bảo vệ sự thật.Qua đối thoại:    - Huấn luyện viên nói với tiền đạo: \\\"Chiến thắng không chỉ là ghi bàn, mà còn là sát cánh cùng đồng đội.\\\"    - Đội trưởng đội bóng nghiệp dư: \\\"Chúng ta có thể không giỏi nhất, nhưng chúng ta là một gia đình.\\\"    - Trọng tài nói với vợ: \\\"Anh không thể sống với việc phản bội lương tâm mình.\\\"Qua hình ảnh/biểu tượng:    - Hình ảnh cả đội ăn mừng chiến thắng cùng nhau, tượng trưng cho sự đoàn kết.    - Sân bóng cộng đồng được tân trang lại, tượng trưng cho sự hồi sinh và niềm hy vọng.    - Chiếc còi của trọng tài, biểu tượng của sự công bằng và chính trực.\",\"character_count\":\"11\"}', '<h2>NHÂN VẬT CHÍNH</h2></p><p><h3>LÂM \"LA\" ANH</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 28, Tiền đạo ngôi sao của đội tuyển quốc gia Việt Nam</li></ul><br><ul><li><strong>Ngoại hình:</strong> Cao to, vạm vỡ, có hình xăm biểu tượng trên cánh tay, vẻ ngoài lạnh lùng, tóc vuốt ngược.</li></ul><br><ul><li><strong>Tính cách:</strong> Tài năng, kiêu ngạo, quyết đoán trên sân cỏ, khó gần, ít chia sẻ cảm xúc thật.</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Quá tự tin vào khả năng cá nhân, coi thường đồng đội, nóng tính, ám ảnh bởi thành tích cá nhân.</li></ul><br><ul><li><strong>Backstory:</strong> Lớn lên trong nghèo khó, từ nhỏ đã phải nỗ lực vượt bậc để khẳng định bản thân. Sự nghiệp thăng tiến nhanh chóng khiến anh trở nên kiêu ngạo và xa cách.</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Chấn thương đầu gối nghiêm trọng trong quá khứ suýt chấm dứt sự nghiệp, khiến anh luôn sợ hãi thất bại và ám ảnh bởi việc phải chứng tỏ bản thân.</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Giành chức vô địch World Cup, khẳng định vị thế cầu thủ số một thế giới.</li></ul><br><ul><li><strong>NEED (Cần):</strong> Học cách tin tưởng đồng đội, vượt qua nỗi sợ hãi thất bại, hiểu được giá trị của sự hy sinh và tinh thần đồng đội.</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Từ một ngôi sao ích kỷ, chỉ biết đến bản thân và thành tích cá nhân → trở thành một người đội trưởng biết hy sinh vì tập thể, truyền cảm hứng cho đồng đội và trân trọng những giá trị đích thực của bóng đá.</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Thể hiện sự cám dỗ của thành công cá nhân và sự ảo tưởng về sức mạnh tuyệt đối, nhưng cuối cùng nhận ra rằng thành công thực sự chỉ đến khi biết hy sinh vì tập thể.</li></ul></p><p><h2>NHÂN VẬT PHẢN DIỆN</h2></p><p><h3>HOÀNG \"SÓI\" HẢI</h3><br><ul><li><strong>Tuổi/Nghề nghiệp:</strong> 28, Tiền đạo ngôi sao của đội tuyển quốc gia đối thủ (ví dụ: Thái Lan).</li></ul><br><ul><li><strong>Ngoại hình:</strong> Vẻ ngoài bóng bẩy, luôn xuất hiện với những món đồ hiệu đắt tiền, nụ cười giả tạo.</li></ul><br><ul><li><strong>Tính cách:</strong> Xảo quyệt, tham vọng, luôn tìm cách hạ bệ đối thủ bằng mọi thủ đoạn, không từ bất cứ điều gì để đạt được mục đích.</li></ul><br><ul><li><strong>Điểm yếu (Flaw):</strong> Thiếu tự tin vào khả năng thực sự của bản thân, phải dùng đến những chiêu trò bẩn thỉu để che đậy sự yếu kém.</li></ul><br><ul><li><strong>Backstory:</strong> Từng là bạn thân của Lâm Anh, nhưng luôn sống trong cái bóng của anh. Sự ganh tị và lòng tham khiến anh đi vào con đường sai trái.</li></ul><br><ul><li><strong>Ghost/Wound:</strong> Luôn cảm thấy mình thua kém Lâm Anh, ám ảnh bởi việc phải vượt qua anh bằng mọi giá.</li></ul><br><ul><li><strong>WANT (Muốn):</strong> Đánh bại Lâm Anh, giành chức vô địch World Cup bằng mọi thủ đoạn.</li></ul><br><ul><li><strong>NEED (Cần):</strong> Nhận ra rằng thành công bằng sự gian dối và thủ đoạn không bao giờ mang lại hạnh phúc thực sự.</li></ul><br><ul><li><strong>Arc dự kiến:</strong> Không có sự thay đổi tích cực. Tiếp tục lún sâu vào con đường tội lỗi, cuối cùng phải trả giá đắt cho những hành động của mình.</li></ul><br><ul><li><strong>Vai trò trong chủ đề:</strong> Là gương phản chiếu của Lâm Anh, thể hiện con đường mà Lâm Anh có thể đã đi nếu không học được bài học về sự hy sinh và chính trực. Thể hiện rõ sự tha hóa của con người khi đặt lợi ích cá nhân lên trên tất cả.</li></ul></p><p><h2>NHÂN VẬT PHỤ</h2></p><p><h3>ÔNG BA - Huấn luyện viên trưởng</h3><br><ul><li><strong>Vai trò:</strong> Mentor cho Lâm Anh. Người thầy nghiêm khắc nhưng giàu tình cảm, luôn tin tưởng vào tiềm năng của Lâm Anh và giúp anh nhận ra giá trị của tinh thần đồng đội. Ông là người truyền tải thông điệp về sự hy sinh và chính trực đến Lâm Anh.</li></ul></p><p><h3>MAI - Bạn gái của Lâm Anh</h3><br><ul><li><strong>Vai trò:</strong> Love Interest. Một cô gái mạnh mẽ, độc lập, luôn ủng hộ Lâm Anh nhưng không ngại chỉ trích những sai lầm của anh. Cô là người giúp Lâm Anh nhận ra giá trị của sự chân thành và tình yêu thương.</li></ul></p><p><h3>DŨNG - Đồng đội thân thiết của Lâm Anh</h3><br><ul><li><strong>Vai trò:</strong> Best Friend. Một cầu thủ tài năng nhưng khiêm tốn, luôn sẵn sàng hy sinh vì tập thể. Anh là người truyền cảm hứng cho Lâm Anh về tinh thần đồng đội và sự hy sinh.</li></ul></p><p><h3>BÌNH - Tiền vệ trung tâm</h3><br><ul><li><strong>Vai trò:</strong> Đại diện cho sự tận tâm và trung thành. Bình là một cầu thủ cần cù, luôn thi đấu hết mình vì đội bóng. Sự kiên trì của anh là nguồn động viên cho cả đội.</li></ul></p><p><h3>SƠN - Hậu vệ cánh</h3><br><ul><li><strong>Vai trò:</strong> Đại diện cho sự dũng cảm và kiên cường. Sơn là một hậu vệ mạnh mẽ, không ngại va chạm và luôn sẵn sàng bảo vệ đồng đội.</li></ul></p><p><h3>TUẤN - Thủ môn</h3><br><ul><li><strong>Vai trò:</strong> Đại diện cho sự tập trung và kỷ luật. Tuấn là một thủ môn xuất sắc, luôn giữ vững tinh thần và sự tập trung cao độ trong suốt trận đấu.</li></ul></p><p><h3>NAM - Tiền vệ tấn công trẻ</h3><br><ul><li><strong>Vai trò:</strong> Đại diện cho thế hệ trẻ đầy tiềm năng. Nam là một cầu thủ trẻ đầy nhiệt huyết, luôn khao khát học hỏi và cống hiến cho đội bóng.</li></ul></p><p><h3>CÔ HƯƠNG - Mẹ của Lâm Anh</h3><br><ul><li><strong>Vai trò:</strong> Đại diện cho tình mẫu tử thiêng liêng và sự hy sinh vô điều kiện. Cô luôn là nguồn động viên lớn nhất của Lâm Anh.</li></ul></p><p><h3>ÔNG TÙNG - Chủ tịch Liên đoàn bóng đá</h3><br><ul><li><strong>Vai trò:</strong> Đại diện cho quyền lực và tham nhũng. Ông là người tạo áp lực lên đội bóng để đạt được những mục tiêu cá nhân.</li></ul></p><p><h2>SƠ ĐỒ MỐI QUAN HỆ</h2></p><p>*   <strong>LÂM ANH - ÔNG BA:</strong> Mối quan hệ thầy trò, từ xa cách đến tin tưởng và kính trọng.<br>*   <strong>LÂM ANH - MAI:</strong> Mối quan hệ tình yêu, từ hời hợt đến sâu sắc và chân thành.<br>*   <strong>LÂM ANH - DŨNG:</strong> Mối quan hệ bạn bè, từ cạnh tranh đến hợp tác và tin tưởng.<br>*   <strong>LÂM ANH - HOÀNG HẢI:</strong> Mối quan hệ đối địch, từ bạn bè đến kẻ thù.<br>*   <strong>LÂM ANH - CÔ HƯƠNG:</strong> Mối quan hệ mẹ con, luôn yêu thương và ủng hộ.<br>*   <strong>LÂM ANH - ĐỒNG ĐỘI:</strong> Mối quan hệ đồng đội, từ xa cách đến đoàn kết và hy sinh vì nhau.<br>*   <strong>ÔNG TÙNG - ĐỘI BÓNG:</strong> Mối quan hệ quyền lực và áp lực, thể hiện sự tham nhũng và lợi dụng.<br>', '2026-03-30 03:35:27');

