INSERT INTO `loglines` (`id`, `project_id`, `input_data`, `output_data`, `created_at`) VALUES
(1, 5, '{\"movie_idea\":\"Truyện Kiều của tác giả Nguyễn Du ở hiện đại\"}', '<ul><li>Logline chính: </li></ul><br>Khi một cô gái xinh đẹp và thông minh phải lòng một chàng trai tài năng nhưng bị đẩy vào thế giới tội phạm, cô phải lựa chọn giữa tình yêu và danh dự, trong một cuộc chiến đấu để bảo vệ bản thân và những người thân yêu.</p><p><ul><li>Phân tích các yếu tố:</li></ul><br><ul><li>Nhân vật chính: Cô gái xinh đẹp và thông minh (Thúy Kiều)</li></ul><br><ul><li>Mục tiêu: Bảo vệ bản thân và những người thân yêu, giữ gìn danh dự và tìm kiếm hạnh phúc</li></ul><br><ul><li>Xung đột: Thế giới tội phạm, sự phản đối của gia đình và xã hội, cuộc chiến đấu nội tâm giữa tình yêu và danh dự</li></ul><br><ul><li>Stakes: Mất đi danh dự, bị tổn thương về thể xác và tinh thần, mất đi người thân yêu</li></ul></p><p><ul><li>2-3 phiên bản logline thay thế:</li></ul><br><ul><li>Phiên bản 1: Trong một thế giới đầy rẫy tội phạm và tham nhũng, một cô gái trẻ phải đối mặt với những lựa chọn khó khăn khi yêu một chàng trai có quá khứ tối, và phải tìm cách bảo vệ bản thân và những người thân yêu.</li></ul><br><ul><li>Phiên bản 2: Khi tình yêu và danh dự bị đẩy vào thế giới tội phạm, một cô gái thông minh và xinh đẹp phải sử dụng tất cả khả năng và trí tuệ của mình để bảo vệ bản thân và người thân yêu, và tìm kiếm con đường đến hạnh phúc.</li></ul><br><ul><li>Phiên bản 3: Trong một cuộc chiến đấu giữa tình yêu và danh dự, một cô gái trẻ phải lựa chọn giữa việc theo đuổi hạnh phúc và giữ gìn danh dự, khi cô bị đẩy vào thế giới tội phạm và phải đối mặt với những thử thách khó khăn.</li></ul>', '2026-01-31 04:02:35'),
(22, 14, '{\"movie_idea\":\"Xưa có một anh chàng tiều phu nghèo, cha mẹ anh bệnh nặng nên qua đời sớm, anh phải sống mồ côi cha mẹ từ nhỏ và tài sản của anh chỉ có một chiếc rìu. Hàng ngày anh phải xách rìu vào rừng để đốn củi bán để lấy tiền kiếm sống qua ngày. Cạnh bìa rừng có một con sông nước chảy rất xiết, ai đó lỡ trượt chân rơi xuống sông thì rất khó bơi vào bờ.\\n\\nMột hôm, như thường ngày chàng tiều phu vác rìu vào rừng để đốn củi, trong lúc đang chặt củi cạnh bờ sông thì chẳng may chiếc rìu của chàng bị gãy cán và lưỡi rìu văng xuống sông. Vì dòng sông nước chảy quá xiết nên mặc dù biết bơi nhưng anh chàng vẫn không thể xuống sông để tìm lưỡi rìu. Thất vọng anh chàng tiều phu ngồi khóc than thở.\\n\\nBỗng từ đâu đó có một ông cụ tóc trắng bạc phơ, râu dài, đôi mắt rất hiền từ xuất hiện trước mặt chàng, ông cụ nhìn chàng tiêu phu và hỏi:\\n\\n-Này con, con đang có chuyện gì mà ta thấy con khóc và buồn bã như vậy?\\n\\nAnh chàng tiều phu trả lời ông cụ:\\n\\n-Thưa cụ, bố mẹ cháu mất sớm, cháu phải sống mồ côi từ nhỏ, gia cảnh nhà cháu rất nghèo, tài sản duy nhất của cháu là chiếc rìu sắt mà bố mẹ cháu trước lúc qua đời để lại. Có chiếc rìu đó cháu còn vào rừng đốn củi kiếm sống qua ngày, giờ đây nó đã bị rơi xuống sông, cháu không biết lấy gì để kiếm sống qua ngày nữa. Vì vậy cháu buồn lắm cụ ạ!\\n\\nÔng cụ đáp lời chàng tiều phu:\\n\\n-Ta tưởng chuyện gì lớn, cháu đừng khóc nữa, để ta lặn xuống sông lấy hộ cháu chiếc rìu lên.\\n\\nDứt lời, ông cụ lao mình xuống dòng sông đang chảy rất xiết. Một lúc sau, ông cụ ngoi lên khỏi mặt nước tay cầm một chiếc rìu bằng bạc sáng loáng và hỏi anh chàng tiều phu nghèo:\\n\\n– Đây có phải lưỡi rìu mà con đã làm rơi xuống không ?\\n\\nAnh chàng tiều phu nhìn lưỡi rìu bằng bạc thấy không phải của mình nên anh lắc đầu và bảo ông cụ:\\n\\n– Không phải lưỡi rìu của cháu cụ ạ, lưỡi rìu của cháu bằng sắt cơ.\\n\\nLần thứ hai, ông cụ lại lao mình xuống dòng sông chảy xiết để tìm chiếc rìu cho chàng tiều phu. Một lúc sau, ông cụ ngoi lên khỏi mặt nước tay cầm chiếc rìu bằng vàng và hỏi chàng tiều phu:\\n\\n-Đây có phải là lưỡi rìu mà con đã sơ ý làm rơi xuống sông không?\\n\\nAnh chàng tiều phu nhìn lưỡi rìu bằng vàng sáng chói, anh lại lắc đầu và bảo:\\n\\n-Không phải là lưỡi rìu của con cụ ạ\\n\\nLần thứ ba, ông cụ lại lao mình xuống sông và lần này khi lên ông cụ cầm trên tay là chiếc rìu bằng sắt của anh chàng tiều phu đánh rơi. Ông cụ lại hỏi:\\n\\n-Vậy đây có phải là lưỡi rìu của con không!\\n\\nThấy đúng là lưỡi rìu của mình rồi, anh chàng tiều phu reo lên sung sướng:\\n\\n-Vâng cụ, đây đúng là lưỡi rìu của con, con cảm ơn cụ đã tìm hộ con lưỡi rìu để con có cái đốn củi kiếm sống qua ngày.\\n\\nÔng cụ đưa cho anh chàng tiều phu lưỡi rìu bằng sắt của anh và khen:\\n\\n-Con quả là người thật thà và trung thực, không hề ham tiền bạc và lợi lộc. Nay ta tặng thêm cho con hai lưỡi rìu bằng vàng và bạc này. Đây là quà ta tặng con, con cứ vui vẻ nhận.\\n\\nAnh chàng tiều phu vui vẻ đỡ lấy hai lưỡi rìu mà ông cụ tặng và cảm tạ. Ông cụ hóa phép và biến mất. Lúc đó anh chàng tiều phu mới biết rằng mình vừa được bụt giúp đỡ.\"}', '<h2>📝 LOGLINE CHÍNH</h2><br>Một chàng tiều phu nghèo phải đối mặt với thử thách sinh tồn khi chiếc rìu của mình bị rơi xuống sông, nhưng nhờ sự giúp đỡ của một ông cụ bí ẩn, anh phải vượt qua cám dỗ và chứng minh sự trung thực của mình. Với sự giúp đỡ của ông cụ, anh chàng tiều phu không chỉ tìm lại được chiếc rìu mà còn nhận được những phần thưởng bất ngờ.</p><p><h2>🔍 PHÂN TÍCH CÁC YẾU TỐ</h2><br><ul><li><strong>Nhân vật chính:</strong> Một chàng tiều phu nghèo, mồ côi cha mẹ từ nhỏ, chỉ có một chiếc rìu để kiếm sống.</li></ul><br><ul><li><strong>Mục tiêu:</strong> Tìm lại chiếc rìu bị rơi xuống sông để tiếp tục kiếm sống.</li></ul><br><ul><li><strong>Xung đột:</strong> Chiếc rìu bị rơi xuống sông và anh không thể lấy lại được, phải đối mặt với cám dỗ khi ông cụ tìm được những chiếc rìu bằng bạc và vàng.</li></ul><br><ul><li><strong>Stakes:</strong> Nếu không tìm lại được chiếc rìu, anh chàng tiều phu sẽ không có cách nào để kiếm sống và sẽ phải đối mặt với đói nghèo và tuyệt vọng.</li></ul><br><ul><li><strong>Thể loại:</strong> Phim fantasy,冒險, với yếu tố thần thoại và giáo dục về sự trung thực và lòng biết ơn.</li></ul></p><p><h2>💡 LOGLINE THAY THẾ</h2><br><ul><li>Khi một chàng tiều phu nghèo mất chiếc rìu vào sông, ông phải đối mặt với một thử thách lớn để lấy lại nó, nhưng sự giúp đỡ của một ông cụ bí ẩn sẽ thay đổi mọi thứ.</li></ul><br><ul><li>Trong một thế giới đầy rẫy những cám dỗ, một chàng tiều phu nghèo phải chứng minh sự trung thực của mình để nhận được sự giúp đỡ từ một ông cụ bí ẩn và tìm lại chiếc rìu quý giá của mình.</li></ul><br><ul><li>Với sự giúp đỡ của một ông cụ bí ẩn, một chàng tiều phu nghèo không chỉ tìm lại được chiếc rìu mà còn học được bài học quý giá về sự trung thực và lòng biết ơn.</li></ul>', '2026-02-11 03:28:01'),
(26, 19, '{\"movie_idea\":\"Một nhà khoa học đơn độc ở thành phố New York hậu tận thế chạy đua với thời gian để tìm ra phương thuốc chữa trị một dịch bệnh chết người trong khi phải trốn tránh những kẻ săn lùng đột biến không ngừng truy đuổi.\"}', '<h2>📝 LOGLINE CHÍNH</h2><br>Nhà khoa học đơn độc Dr. Emma Taylor tìm kiếm phương thuốc chữa trị dịch bệnh trong thành phố New York hậu tận thế, bị truy đuổi bởi những kẻ săn lùng đột biến. Nếu thất bại, loài người sẽ tuyệt chủng.</p><p><h2>🔍 PHÂN TÍCH CÁC YẾU TỐ</h2><br><ul><li><strong>Nhân vật chính:</strong> Dr. Emma Taylor, một nhà khoa học thông minh và quyết tâm.</li></ul><br><ul><li><strong>Mục tiêu:</strong> Tìm ra phương thức chữa trị dịch bệnh.</li></ul><br><ul><li><strong>Xung đột:</strong> Những kẻ săn lùng đột biến và áp lực thời gian.</li></ul><br><ul><li><strong>Stakes:</strong> Loài người sẽ tuyệt chủng nếu không tìm được phương thuốc.</li></ul><br><ul><li><strong>Thể loại:</strong> Khoa học viễn tưởng, hậu tận thế.</li></ul></p><p><h2>💡 LOGLINE THAY THẾ</h2><br><ul><li>Trong thành phố New York bị phá hủy, Dr. Emma Taylor phải chạy trốn khỏi những kẻ đột biến hung dữ để tìm ra phương thuốc chữa trị dịch bệnh trước khi quá muộn.</li></ul><br><ul><li>Với thời gian dần cạn kiệt, Dr. Emma Taylor phải đối mặt với nỗi sợ hãi và tuyệt vọng khi tìm kiếm phương thuốc chữa trị dịch bệnh trong một thế giới đã sụp đổ.</li></ul><br><ul><li>Khi thành phố New York trở thành chiến trường của sự sống còn, Dr. Emma Taylor phải sử dụng tất cả kiến thức và sự quyết tâm của mình để tìm ra phương thuốc chữa trị dịch bệnh và bảo vệ tương lai của loài người.</li></ul>', '2026-02-12 05:43:53'),
(28, 27, '{\"movie_idea\":\"bạn gái tôi đã hẹo\"}', '<h2>Mời bạn tham khảo những Logline sau:</h2></p><p><ul><li> <strong>Thể loại: Hài đen.</strong> Một chàng trai vụng về cố gắng che giấu cái chết đột ngột của bạn gái mình để nhận được khoản tiền bảo hiểm lớn, nhưng mọi chuyện trở nên hỗn loạn khi gia đình cô ấy bất ngờ đến thăm.</li></ul><br><ul><li> <strong>Thể loại: Kinh dị tâm lý.</strong> Sau cái chết bí ẩn của bạn gái, một nhà văn trẻ bị ám ảnh bởi những ảo ảnh kỳ lạ và phải khám phá sự thật đen tối đằng sau cái chết của cô để giữ lấy sanity của mình.</li></ul><br><ul><li> <strong>Thể loại: Lãng mạn siêu nhiên.</strong> Một nhạc sĩ đau khổ phát hiện ra rằng anh ta có thể giao tiếp với linh hồn bạn gái đã khuất của mình, nhưng để giữ kết nối mong manh này, anh ta phải giúp cô hoàn thành một nhiệm vụ dang dở trước khi cô tan biến mãi mãi.</li></ul><br>', '2026-03-04 08:44:06'),
(29, 29, '{\"movie_idea\":\"một bộ phim về trận bóng đá\"}', '<h2>Mời bạn tham khảo những Logline sau:</h2></p><p><ul><li> <strong>[Thể thao/Drama]</strong> Một tiền đạo ngôi sao ngạo mạn, bị ám ảnh bởi chức vô địch World Cup cuối cùng trong sự nghiệp, phải học cách tin tưởng đồng đội và vượt qua chấn thương dai dẳng, nếu không anh sẽ đánh mất vinh quang mãi mãi và sống trong hối hận.</li></ul><br><ul><li> <strong>[Thể thao/Hài]</strong> Một đội bóng nghiệp dư toàn những kẻ lập dị, với mục tiêu giành chiến thắng trong giải đấu địa phương để cứu lấy sân bóng cộng đồng khỏi tay một tập đoàn bất động sản tham lam, phải đối mặt với những đối thủ mạnh hơn và sự thiếu phối hợp hài hước, nếu thất bại, họ sẽ mất đi nơi gắn bó và niềm đam mê duy nhất.</li></ul><br><ul><li> <strong>[Thể thao/Giật gân]</strong> Một trọng tài bóng đá đầy tham vọng, bị ép buộc phải dàn xếp tỷ số một trận đấu quan trọng bởi một tổ chức mafia tàn bạo, phải tìm cách vạch trần sự thật và bảo vệ gia đình mình, nếu không anh sẽ phải trả giá bằng cả sự nghiệp và mạng sống.</li></ul><br>', '2026-03-30 03:33:28');

