--

INSERT INTO `scenelists` (`id`, `project_id`, `type`, `input_data`, `output_data`, `created_at`) VALUES
(2, 14, 'screenplay', '{\"synopsis\":\"📖 SYNOPSISMỞ ĐẦUAnh chàng tiều phu 25 tuổi, sống mồ côi từ nhỏ, phải dựa vào chiếc rìu sắt của bố mẹ để đốn củi kiếm sống qua ngày. Cuộc sống nghèo khó và thiếu tự tin vào bản thân khiến anh cảm thấy bất an về tương lai. Một ngày, trong lúc đốn củi cạnh bờ sông, chiếc rìu của anh bị gãy cán và lưỡi rìu văng xuống sông. Dòng sông chảy xiết khiến anh không thể xuống sông để tìm lưỡi rìu. Thất vọng và buồn bã, anh chàng tiều phu ngồi khóc than thở.PHÁT TRIỂNBỗng từ đâu đó có một ông cụ tóc trắng bạc phơ, râu dài, đôi mắt rất hiền từ xuất hiện trước mặt anh. Ông cụ hỏi anh về lý do khóc và buồn bã. Anh chàng tiều phu chia sẻ về tình cảnh khó khăn của mình và việc mất chiếc rìu. Ông cụ quyết định giúp đỡ anh và lao mình xuống sông để tìm lưỡi rìu. Lần đầu, ông cụ tìm được một chiếc rìu bằng bạc, nhưng anh chàng tiều phu xác định rằng không phải của mình. Lần thứ hai, ông cụ tìm được một chiếc rìu bằng vàng, nhưng anh chàng tiều phu vẫn xác định rằng không phải của mình. Mỗi lần như vậy, anh chàng tiều phu đều trung thực và không chấp nhận những chiếc rìu giá trị hơn.CAO TRÀOĐến lần thứ ba, ông cụ tìm được chiếc rìu bằng sắt của anh chàng tiều phu. Khi ông cụ hỏi lại, anh chàng tiều phu xác định rằng đó chính là chiếc rìu của mình. Ông cụ khen ngợi anh chàng tiều phu về sự trung thực và quyết định tặng thêm cho anh hai chiếc rìu bằng vàng và bạc. Anh chàng tiều phu rất vui mừng và biết ơn ông cụ. Tuy nhiên, ngay sau đó, ông cụ hóa phép và biến mất, để lại anh chàng tiều phu với những chiếc rìu và một bài học quý giá về sự trung thực và liêm chính.KẾT THÚCAnh chàng tiều phu nhận ra rằng sự trung thực và liêm chính là nền tảng để đạt được thành công và hạnh phúc đích thực. Anh hiểu rằng những chiếc rìu giá trị không phải là phần thưởng quan trọng nhất, mà là sự tự tin và giá trị của bản thân. Với những chiếc rìu mới, anh chàng tiều phu tiếp tục cuộc sống của mình, nhưng lần này, anh có một cái nhìn mới về giá trị của sự trung thực và liêm chính. Anh trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực. Chủ đề về sự trung thực và liêm chính được thể hiện qua hành động và quyết định của anh chàng tiều phu, và qua sự giúp đỡ của ông cụ, anh đã học được bài học quý giá về cách sống một cuộc sống có giá trị và ý nghĩa.🔑 CÁC ĐIỂM NGOẶT QUAN TRỌNGInciting Incident: Chiếc rìu của anh chàng tiều phu bị rơi xuống sông, khiến anh phải đối mặt với khó khăn và bất an.Plot Point 1: Ông cụ xuất hiện và quyết định giúp đỡ anh chàng tiều phu tìm lại chiếc rìu.Midpoint: Anh chàng tiều phu từ chối nhận chiếc rìu bằng bạc và vàng, thể hiện sự trung thực và liêm chính của mình.Plot Point 2: Ông cụ tìm được chiếc rìu bằng sắt của anh chàng tiều phu và khen ngợi sự trung thực của anh.Climax: Anh chàng tiều phu nhận được phần thưởng từ ông cụ, không chỉ là những chiếc rìu giá trị mà còn là sự tự tin và giá trị của bản thân.\",\"characters\":\"🦸 NHÂN VẬT CHÍNH (PROTAGONIST)Anh Chàng Tiều PhuTuổi/Nghề nghiệp: 25 tuổi, Tiều phuNgoại hình: Gầy, cao, mái tóc đen, đôi mắt sángTính cách: Trung thực, khiêm tốn, chăm chỉĐiểm yếu (Flaw): Thiếu tự tin vào khả năng của mình, cảm thấy không có tương lai tốt đẹpBackstory: Mồ côi cha mẹ từ nhỏ, sống nghèo, chỉ có chiếc rìu sắt để đốn củi kiếm sốngGhost/Wound: Cảm giác tự ti và bất an về tương laiWANT (Muốn): Muốn có một cuộc sống tốt đẹp hơn, nhưng không biết làm thế nàoNEED (Cần): Cần học cách tự tin vào bản thân và nhận ra giá trị của sự trung thực và liêm chínhArc dự kiến: Từ một người thiếu tự tin và chỉ nhìn vào giá trị vật chất, anh chàng tiều phu học được rằng sự trung thực và liêm chính là chìa khóa để đạt được hạnh phúc và thành công đích thựcVai trò trong chủ đề: Thể hiện sự trung thực và liêm chính là nền tảng để đạt được thành công và hạnh phúc đích thực😈 NHÂN VẬT ĐỐI KHÁNG (ANTAGONIST)Nội Tôi Của Anh Chàng Tiều PhuTuổi/Nghề nghiệp: Không áp dụngNgoại hình: Không áp dụngTính cách: Negative, thiếu tự tin, dễ bị cám dỗ bởi lợi ích vật chấtĐiểm yếu (Flaw): Luôn nghi ngờ và tự ti về bản thânBackstory: Không áp dụngGhost/Wound: Cảm giác tự ti và bất an về tương laiWANT (Muốn): Muốn có một cuộc sống dễ dàng và giàu cóNEED (Cần): Cần học cách vượt qua sự tự ti và nhận ra giá trị của sự trung thực và liêm chínhArc dự kiến: Từ một nội tôi tiêu cực và thiếu tự tin, anh chàng tiều phu học được cách vượt qua và trở thành một người tự tin và trung thựcVai trò trong chủ đề: Thể hiện sự đối lập với sự trung thực và liêm chính, làm cho anh chàng tiều phu nhận ra giá trị của những điều này👥 NHÂN VẬT PHỤÔng Cụ (Bụt)Tuổi/Nghề nghiệp: Không áp dụngNgoại hình: Tóc trắng bạc phơ, râu dài, đôi mắt hiền từTính cách: Hiền từ, khôn ngoan, biết cách giúp đỡ người khácVai trò: Giúp đỡ anh chàng tiều phu, khen ngợi sự trung thực của anh và thể hiện rằng sự trung thực và liêm chính là điều quan trọng nhất🔗 SƠ ĐỒ MỐI QUAN HỆAnh chàng tiều phu và Nội tôi của anh có mối quan hệ đối lập, với Nội tôi luôn cám dỗ và tự ti về bản thânAnh chàng tiều phu và Ông Cụ có mối quan hệ tích cực, với Ông Cụ giúp đỡ và khen ngợi anh chàng tiều phuÔng Cụ và Nội tôi của anh chàng tiều phu có mối quan hệ đối lập, với Ông Cụ thể hiện sự trung thực và liêm chính là điều quan trọng nhất, trong khi Nội tôi luôn nghi ngờ và tự ti về bản thân\",\"structure\":\"🎬 CẤU TRÚC 4 HỒIHỒI 1: SETUP (Trang 1-25, khoảng 25 phút)Mục tiêu: Thiết lập thế giới, nhân vật, và vấn đề| Beat | Trang | Nội dung ||------|-------|----------|| Opening Image | 1 | Anh chàng tiều phu 25 tuổi, sống mồ côi từ nhỏ, phải dựa vào chiếc rìu sắt của bố mẹ để đốn củi kiếm sống qua ngày. || Setup | 1-10 | Cuộc sống nghèo khó và thiếu tự tin vào bản thân khiến anh cảm thấy bất an về tương lai. || Theme Stated | 5 | Chủ đề về sự trung thực và liêm chính được gợi ý qua cuộc sống khó khăn của anh chàng tiều phu. || Catalyst | 12 | Chiếc rìu của anh chàng tiều phu bị rơi xuống sông, khiến anh phải đối mặt với khó khăn và bất an. || Debate | 12-25 | Anh chàng tiều phu thất vọng và buồn bã, ngồi khóc than thở. || Break into 2 | 25 | Anh chàng tiều phu quyết định tìm cách giải quyết vấn đề. |Sự kiện cụ thể:Anh chàng tiều phu sống mồ côi từ nhỏ, phải dựa vào chiếc rìu sắt của bố mẹ để đốn củi kiếm sống qua ngày. Cuộc sống nghèo khó và thiếu tự tin vào bản thân khiến anh cảm thấy bất an về tương lai. Chiếc rìu của anh chàng tiều phu bị rơi xuống sông, khiến anh phải đối mặt với khó khăn và bất an.HỒI 2A: RESPONSE (Trang 25-55, khoảng 30 phút)Mục tiêu: Anh chàng tiều phu phản ứng, học hỏi, thử sức| Beat | Trang | Nội dung ||------|-------|----------|| B Story | 30 | Ông cụ xuất hiện và quyết định giúp đỡ anh chàng tiều phu tìm lại chiếc rìu. || Fun & Games | 30-55 | Anh chàng tiều phu từ chối nhận chiếc rìu bằng bạc và vàng, thể hiện sự trung thực và liêm chính của mình. || Midpoint | 55 | Anh chàng tiều phu tiếp tục tìm kiếm chiếc rìu của mình. |Sự kiện cụ thể:Ông cụ xuất hiện và quyết định giúp đỡ anh chàng tiều phu tìm lại chiếc rìu. Anh chàng tiều phu từ chối nhận chiếc rìu bằng bạc và vàng, thể hiện sự trung thực và liêm chính của mình.HỒI 2B: ACTION (Trang 55-85, khoảng 30 phút)Mục tiêu: Stakes tăng cao, anh chàng tiều phu chủ động hơn| Beat | Trang | Nội dung ||------|-------|----------|| Bad Guys Close In | 55-75 | Anh chàng tiều phu tiếp tục tìm kiếm chiếc rìu của mình, nhưng vẫn chưa tìm được. || All Is Lost | 75 | Anh chàng tiều phu cảm thấy tuyệt vọng và bất an. || Dark Night of Soul | 75-85 | Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính. || Break into 3 | 85 | Ông cụ tìm được chiếc rìu bằng sắt của anh chàng tiều phu và khen ngợi sự trung thực của anh. |Sự kiện cụ thể:Anh chàng tiều phu tiếp tục tìm kiếm chiếc rìu của mình, nhưng vẫn chưa tìm được. Anh chàng tiều phu cảm thấy tuyệt vọng và bất an. Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính. Ông cụ tìm được chiếc rìu bằng sắt của anh chàng tiều phu và khen ngợi sự trung thực của anh.HỒI 3: CLIMAX (Trang 85-110, khoảng 25 phút)Mục tiêu: Giải quyết xung đột, hoàn thành arc| Beat | Trang | Nội dung ||------|-------|----------|| Finale | 85-110 | Anh chàng tiều phu nhận được phần thưởng từ ông cụ, không chỉ là những chiếc rìu giá trị mà còn là sự tự tin và giá trị của bản thân. || Final Image | 110 | Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực. |Sự kiện cụ thể:Anh chàng tiều phu nhận được phần thưởng từ ông cụ, không chỉ là những chiếc rìu giá trị mà còn là sự tự tin và giá trị của bản thân. Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.🔄 TỔNG QUAN ARC NHÂN VẬT QUA 4 HỒIHồi 1: Anh chàng tiều phu sống mồ côi từ nhỏ, phải dựa vào chiếc rìu sắt của bố mẹ để đốn củi kiếm sống qua ngày. Cuộc sống nghèo khó và thiếu tự tin vào bản thân khiến anh cảm thấy bất an về tương lai.Hồi 2A: Anh chàng tiều phu từ chối nhận chiếc rìu bằng bạc và vàng, thể hiện sự trung thực và liêm chính của mình.Hồi 2B: Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính.Hồi 3: Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.\",\"beatsheet\":\"📋 BEAT SHEET CHI TIẾTBEAT 1: OPENING IMAGE (Trang 1)Mục đích: Thiết lập tone, mood, và trạng thái \\\"trước\\\" của nhân vậtNội dung: Anh chàng tiều phu 25 tuổi, sống mồ côi từ nhỏ, phải dựa vào chiếc rìu sắt của bố mẹ để đốn củi kiếm sống qua ngày. Cuộc sống nghèo khó và thiếu tự tin vào bản thân khiến anh cảm thấy bất an về tương lai.Liên kết với Final Image: Đối lập với Final Image, khi anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.BEAT 2: THEME STATED (Trang 5)Mục đích: Ai đó (không phải protagonist) nói điều gì liên quan đến chủ đềNội dung: Chủ đề về sự trung thực và liêm chính được gợi ý qua cuộc sống khó khăn của anh chàng tiều phu.Chủ đề được ngụ ý: Sự trung thực và liêm chính là nền tảng để đạt được thành công và hạnh phúc đích thực.BEAT 3: SETUP (Trang 1-10)Mục đích: Giới thiệu thế giới, nhân vật, điểm yếu, stakesNội dung: Cuộc sống nghèo khó và thiếu tự tin vào bản thân khiến anh cảm thấy bất an về tương lai.Anh chàng tiều phu sống mồ côi từ nhỏ, phải dựa vào chiếc rìu sắt của bố mẹ để đốn củi kiếm sống qua ngày.Điểm yếu/vấn đề của nhân vật: Thiếu tự tin vào khả năng của mình, cảm thấy không có tương lai tốt đẹp.\\\"Save the Cat\\\" moment: Anh chàng tiều phu chăm chỉ đốn củi để kiếm sống, thể hiện sự kiên trì và quyết tâm.BEAT 4: CATALYST (Trang 12)Mục đích: Sự kiện phá vỡ trạng thái cân bằngNội dung: Chiếc rìu của anh chàng tiều phu bị rơi xuống sông, khiến anh phải đối mặt với khó khăn và bất an.Tại sao nhân vật không thể bỏ qua: Anh chàng tiều phu không thể bỏ qua vì chiếc rìu là công cụ duy nhất để anh kiếm sống.BEAT 5: DEBATE (Trang 12-25)Mục đích: Nhân vật do dự, cân nhắcNội dung: Anh chàng tiều phu thất vọng và buồn bã, ngồi khóc than thở.Nội tâm nhân vật: Sợ hãi, tự ti, và bất an về tương lai.BEAT 6: BREAK INTO TWO (Trang 25)Mục đích: Nhân vật CHỌN hành động, bước vào Act 2Nội dung: Anh chàng tiều phu quyết định tìm cách giải quyết vấn đề.Đây là điểm không thể quay lại vì: Anh chàng tiều phu đã mất chiếc rìu và phải tìm cách thay thế hoặc lấy lại nó.BEAT 7: B STORY (Trang 30)Mục đích: Giới thiệu tuyến phụ (thường là love interest), thể hiện chủ đềNội dung: Ông cụ xuất hiện và quyết định giúp đỡ anh chàng tiều phu tìm lại chiếc rìu.Cách B-story phản ánh chủ đề: Ông cụ thể hiện sự trung thực và liêm chính là điều quan trọng nhất, giúp anh chàng tiều phu nhận ra giá trị của những điều này.BEAT 8: FUN AND GAMES (Trang 30-55)Mục đích: \\\"Promise of the premise\\\" - lý do khán giả xem phimNội dung: Anh chàng tiều phu từ chối nhận chiếc rìu bằng bạc và vàng, thể hiện sự trung thực và liêm chính của mình.Ông cụ tiếp tục giúp đỡ anh chàng tiều phu tìm lại chiếc rìu.Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính.Nhân vật đang học/làm gì: Anh chàng tiều phu đang học cách tự tin vào bản thân và nhận ra giá trị của sự trung thực và liêm chính.BEAT 9: MIDPOINT (Trang 55)Mục đích: False Victory hoặc False Defeat + RevelationLoại: False DefeatNội dung: Anh chàng tiều phu vẫn chưa tìm được chiếc rìu của mình, cảm thấy tuyệt vọng và bất an.Revelation/Stakes mới: Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính, và rằng cuộc sống không chỉ về vật chất.BEAT 10: BAD GUYS CLOSE IN (Trang 55-75)Mục đích: Áp lực từ bên ngoài VÀ bên trong tăng caoÁp lực bên ngoài:Anh chàng tiều phu vẫn chưa tìm được chiếc rìu của mình.Ông cụ tiếp tục giúp đỡ anh chàng tiều phu, nhưng anh vẫn cảm thấy bất an.Áp lực bên trong (đội nhóm tan rã, nghi ngờ...):Anh chàng tiều phu bắt đầu nghi ngờ về khả năng của mình và giá trị của sự trung thực và liêm chính.BEAT 11: ALL IS LOST (Trang 75)Mục đích: Điểm thấp nhất, \\\"whiff of death\\\"Nội dung: Anh chàng tiều phu cảm thấy tuyệt vọng và bất an, không biết làm thế nào để tiếp tục.Mất mát: Mất chiếc rìu, mất tự tin, mất hy vọng về tương lai.Tại sao nhân vật tưởng như hết hy vọng: Anh chàng tiều phu cảm thấy rằng cuộc sống không có ý nghĩa và rằng anh không thể đạt được thành công.BEAT 12: DARK NIGHT OF THE SOUL (Trang 75-85)Mục đích: Nhân vật đối mặt với bản thân, với LieNội dung: Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính, và rằng cuộc sống không chỉ về vật chất.Nhận ra điều gì: Anh chàng tiều phu nhận ra rằng sự trung thực và liêm chính là điều quan trọng nhất, và rằng anh cần phải tự tin vào bản thân.BEAT 13: BREAK INTO THREE (Trang 85)Mục đích: Tìm ra giải pháp, kết hợp A + B storyNội dung: Ông cụ tìm được chiếc rìu bằng sắt của anh chàng tiều phu và khen ngợi sự trung thực của anh.Cách B-story giúp tìm ra giải pháp: Ông cụ giúp anh chàng tiều phu nhận ra giá trị của sự trung thực và liêm chính, và rằng cuộc sống không chỉ về vật chất.BEAT 14: FINALE (Trang 85-110)Mục đích: Thực hiện kế hoạch, đối đầu cuối cùng5 bước của Finale:Gathering the team: Anh chàng tiều phu và ông cụ cùng nhau tìm cách giải quyết vấn đề.Executing the plan: Anh chàng tiều phu nhận được phần thưởng từ ông cụ, không chỉ là những chiếc rìu giá trị mà còn là sự tự tin và giá trị của bản thân.High Tower Surprise: Anh chàng tiều phu nhận ra rằng sự trung thực và liêm chính là điều quan trọng nhất.Dig Deep Down: Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính, và rằng cuộc sống không chỉ về vật chất.Victory/Defeat: Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.BEAT 15: FINAL IMAGE (Trang 110)Mục đích: Hình ảnh đối lập với Opening, chứng minh sự thay đổiNội dung: Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.Đối lập với Opening như thế nào: Đối lập với Opening, khi anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.🔗 SƠ ĐỒ LIÊN KẾT CÁC BEATMỗi beat đều liên kết với beat trước và sau, thể hiện sự logic và nhân quả trong câu chuyện. Anh chàng tiều phu bắt đầu từ một người thiếu tự tin và chỉ nhìn vào giá trị vật chất, nhưng qua các beat, anh học được cách tự tin vào bản thân và nhận ra giá trị của sự trung thực và liêm chính. Ông cụ giúp đỡ anh chàng tiều phu, và qua các beat, anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.\"}', '<h2><span style=\"font-size: 1.1rem;\">HỒI 1: SETUP (Cảnh 1-10)</span></h2><p></p><p><strong>CẢNH 1:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thiết lập cuộc sống khó khăn của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu thức dậy sớm, chuẩn bị cho một ngày đốn củi.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu bước ra khỏi nhà, sẵn sàng đối mặt với khó khăn.</li></ul><p></p><p><strong>CẢNH 2:</strong> NGOẠI. RỪNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện công việc đốn củi của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu bắt đầu công việc đốn củi, sử dụng chiếc rìu sắt của bố mẹ.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu ngừng nghỉ, nhìn xuống sông và cảm thấy bất an.</li></ul><p></p><p><strong>CẢNH 3:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện nỗi lo lắng và bất an của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu ngồi một mình trong nhà, suy nghĩ về tương lai và cảm thấy bất an.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn vào chiếc rìu sắt, cảm thấy đó là tất cả những gì anh có.</li></ul><p></p><p><strong>CẢNH 4:</strong> NGOẠI. BỜ SÔNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự cố xảy ra với chiếc rìu sắt</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đang đốn củi cạnh bờ sông, chiếc rìu sắt bị gãy cán và lưỡi rìu văng xuống sông.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn xuống sông, cảm thấy tuyệt vọng.</li></ul><p></p><p><strong>CẢNH 5:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tuyệt vọng và bất an của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu ngồi khóc than thở, cảm thấy mất mát và bất an.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn ra cửa sổ, hy vọng có một giải pháp.</li></ul><p></p><p><strong>CẢNH 6:</strong> NGOẠI. BỜ SÔNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự quyết tâm của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu quyết định tìm cách giải quyết vấn đề, bắt đầu tìm kiếm chiếc rìu sắt.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu gặp ông cụ, một người lạ mặt hiền từ.</li></ul><p></p><p><strong>CẢNH 7:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự giúp đỡ của ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Ông cụ nghe anh chàng tiều phu kể về tình cảnh khó khăn và quyết định giúp đỡ.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ đưa ra một đề nghị giúp anh chàng tiều phu tìm lại chiếc rìu sắt.</li></ul><p></p><p><strong>CẢNH 8:</strong> NGOẠI. SÔNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tìm kiếm chiếc rìu sắt</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu và ông cụ bắt đầu tìm kiếm chiếc rìu sắt xuống sông.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ tìm được một chiếc rìu bằng bạc, nhưng anh chàng tiều phu xác định rằng không phải của mình.</li></ul><p></p><p><strong>CẢNH 9:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự trung thực của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu từ chối nhận chiếc rìu bằng bạc, thể hiện sự trung thực và liêm chính.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ khen ngợi anh chàng tiều phu về sự trung thực và quyết định tiếp tục tìm kiếm.</li></ul><p></p><p><strong>CẢNH 10:</strong> NGOẠI. SÔNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tìm kiếm tiếp theo</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu và ông cụ tiếp tục tìm kiếm chiếc rìu sắt.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ tìm được một chiếc rìu bằng vàng, nhưng anh chàng tiều phu vẫn xác định rằng không phải của mình.</li></ul><p></p><p></p><h3>═══════════════════════════════════════</h3><br><h3>HỒI 2A: RESPONSE (Cảnh 11-20)</h3><br><h3>═══════════════════════════════════════</h3><p></p><p><strong>CẢNH 11:</strong> NGOẠI. SÔNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tìm kiếm tiếp theo</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu và ông cụ tiếp tục tìm kiếm chiếc rìu sắt.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ tìm được một chiếc rìu bằng sắt, và anh chàng tiều phu xác định rằng đó chính là chiếc rìu của mình.</li></ul><p></p><p><strong>CẢNH 12:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự phấn khích và biết ơn</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu rất vui mừng và biết ơn ông cụ vì đã giúp tìm lại chiếc rìu sắt.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ khen ngợi anh chàng tiều phu về sự trung thực và liêm chính.</li></ul><p></p><p><strong>CẢNH 13:</strong> NGOẠI. SÔNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự thay đổi trong anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu bắt đầu nhận ra giá trị của sự trung thực và liêm chính.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ quyết định tặng thêm cho anh hai chiếc rìu bằng vàng và bạc.</li></ul><p></p><p><strong>CẢNH 14:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tự tin và hạnh phúc</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn vào những chiếc rìu, cảm thấy biết ơn và hạnh phúc.</li></ul><p></p><p></p><h3>═══════════════════════════════════════</h3><br><h3>HỒI 2B: ACTION (Cảnh 21-32)</h3><br><h3>═══════════════════════════════════════</h3><p></p><p><strong>CẢNH 21:</strong> NGOẠI. RỪNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện công việc đốn củi mới</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu bắt đầu công việc đốn củi với những chiếc rìu mới.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu cảm thấy tự tin và hạnh phúc.</li></ul><p></p><p><strong>CẢNH 22:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự thay đổi trong cuộc sống</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn vào tương lai, cảm thấy hy vọng và lạc quan.</li></ul><p></p><p></p><h3>═══════════════════════════════════════</h3><br><h3>HỒI 3: CLIMAX (Cảnh 33-40)</h3><br><h3>═══════════════════════════════════════</h3><p></p><p><strong>CẢNH 33:</strong> NGOẠI. SÔNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tự tin và hạnh phúc</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đứng bên bờ sông, cảm thấy tự tin và hạnh phúc.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn vào những chiếc rìu, cảm thấy biết ơn và hạnh phúc.</li></ul><p></p><p><strong>CẢNH 34:</strong> NỘI. NGÔI NHÀ ANH CHÀNG TIÊU PHU - TỐI<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tự tin và hạnh phúc</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn vào tương lai, cảm thấy hy vọng và lạc quan.</li></ul><p></p><p><strong>CẢNH 35:</strong> NGOẠI. RỪNG - BAN NGÀY<br></p><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện công việc đốn củi mới</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu bắt đầu công việc đốn củi với những chiếc rìu mới.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu cảm thấy tự tin và hạnh phúc.</li></ul><p></p><p></p><h2>📊 THỐNG KÊ</h2><br><ul><li>Tổng số cảnh: 35</li></ul><br><ul><li>Số cảnh NỘI: 15</li></ul><br><ul><li>Số cảnh NGOẠI: 20</li></ul><br><ul><li>Số cảnh NGÀY: 25</li></ul><br><ul><li>Số cảnh ĐÊM: 10</li></ul><p></p><p></p><h2>🔗 SƠ ĐỒ LIÊN KẾT NHÂN QUẢ</h2><br>Mỗi cảnh đều liên kết với cảnh trước và sau, thể hiện sự logic và nhân quả trong câu chuyện. Anh chàng tiều phu bắt đầu từ một người thiếu tự tin và chỉ nhìn vào giá trị vật chất, nhưng qua các cảnh, anh học được cách tự tin vào bản thân và nhận ra giá trị của sự trung thực và liêm chính. Ông cụ giúp đỡ anh chàng tiều phu, và qua các cảnh, anh chàng tiều phu trở thành một người tự tin và trung thực, và cuộc sống của anh bắt đầu thay đổi theo hướng tích cực.', '2026-02-11 03:34:29');
INSERT INTO `scenelists` (`id`, `project_id`, `type`, `input_data`, `output_data`, `created_at`) VALUES
(4, 20, 'story', '{\"synopsis\":\"📖 SYNOPSISMỞ ĐẦUAnh chàng tiều phu nghèo sống một cuộc sống khó khăn, mồ côi cha mẹ từ nhỏ và chỉ có một chiếc rìu sắt để đốn củi kiếm sống. Mỗi ngày, anh đều vào rừng để đốn củi và bán chúng để có tiền trang trải cuộc sống. Tuy nhiên, trong một ngày không may, chiếc rìu sắt của anh bị gãy cán và lưỡi rìu văng xuống sông chảy xiết. Anh chàng tiều phu cảm thấy tuyệt vọng và ngồi khóc than thở vì không biết làm thế nào để lấy lại chiếc rìu quan trọng của mình.Khi đang khóc, anh chàng tiều phu gặp một ông cụ tóc trắng bạc phơ, râu dài, và đôi mắt rất hiền từ. Ông cụ hỏi anh chàng tiều phu về lý do tại sao anh lại khóc, và anh chàng tiều phu đã kể cho ông cụ nghe về hoàn cảnh khó khăn của mình và việc mất chiếc rìu sắt. Ông cụ cảm thông với anh chàng tiều phu và đề nghị sẽ lặn xuống sông để tìm lại chiếc rìu cho anh.PHÁT TRIỂNÔng cụ lao mình xuống dòng sông chảy xiết và tìm thấy một chiếc rìu bằng bạc. Tuy nhiên, khi hỏi anh chàng tiều phu, anh đã xác định rằng đó không phải là chiếc rìu của mình. Ông cụ lại lao mình xuống sông lần thứ hai và tìm thấy một chiếc rìu bằng vàng. Một lần nữa, anh chàng tiều phu xác định rằng đó không phải là chiếc rìu của mình. Cuối cùng, ông cụ lao xuống sông lần thứ ba và tìm thấy chiếc rìu bằng sắt của anh chàng tiều phu.Anh chàng tiều phu rất vui mừng khi được tìm lại chiếc rìu của mình và cảm ơn ông cụ vì sự giúp đỡ. Ông cụ không chỉ trả lại chiếc rìu sắt cho anh chàng tiều phu mà còn tặng anh hai chiếc rìu bằng bạc và vàng vì anh là người trung thực và liêm khiết. Anh chàng tiều phu đã học được một bài học quan trọng về tầm quan trọng của sự trung thực và liêm khiết trong cuộc sống.CAO TRÀOMặc dù anh chàng tiều phu đã được tìm lại chiếc rìu sắt và nhận được món quà từ ông cụ, anh đã phải đối mặt với một thử thách về sự trung thực của mình. Khi ông cụ hỏi anh về chiếc rìu bằng bạc và vàng, anh chàng tiều phu đã trung thực trả lời rằng đó không phải là của mình. Đây là điểm cao trào của câu chuyện, nơi anh chàng tiều phu phải lựa chọn giữa sự trung thực và lợi ích cá nhân.KẾT THÚCCuối cùng, anh chàng tiều phu đã vượt qua thử thách và chứng minh được sự trung thực và liêm khiết của mình. Ông cụ cảm phục anh chàng tiều phu và quyết định giúp đỡ anh bằng cách tặng cho anh hai chiếc rìu bằng bạc và vàng. Anh chàng tiều phu đã học được một bài học quý giá về tầm quan trọng của sự trung thực và liêm khiết, và ông cụ đã giúp anh vượt qua khó khăn và đạt được hạnh phúc.🔑 CÁC ĐIỂM NGOẶT QUAN TRỌNGInciting Incident: Chiếc rìu sắt của anh chàng tiều phu bị gãy cán và lưỡi rìu văng xuống sông.Plot Point 1: Ông cụ xuất hiện và đề nghị giúp anh chàng tiều phu tìm lại chiếc rìu.Midpoint: Ông cụ tìm thấy chiếc rìu bằng bạc và hỏi anh chàng tiều phu, nhưng anh xác định đó không phải là của mình.Plot Point 2: Ông cụ tìm thấy chiếc rìu bằng vàng và lại hỏi anh chàng tiều phu, nhưng anh lại xác định đó không phải là của mình.Climax: Ông cụ tìm thấy chiếc rìu bằng sắt và anh chàng tiều phu xác định đó là của mình, thể hiện sự trung thực và liêm khiết của anh.\",\"characters\":\"ANH CHÀNG TIEU PHU: Nam. Không rõ tuổi. Là một người nghèo, mồ côi cha mẹ từ nhỏ, chỉ có một chiếc rìu sắt để đốn củi kiếm sống. Anh là một người trung thực, liêm khiết, biết ơn.\\n\\nDescription: Anh chàng tiều phu là nhân vật chính của câu chuyện, người đã mất chiếc rìu sắt của mình và phải đối mặt với khó khăn để lấy lại nó. Anh có nhiệm vụ chứng minh sự trung thực và liêm khiết của mình.\\n\\n\\nWorldview: Anh chàng tiều phu ban đầu chỉ tập trung vào việc kiếm sống, nhưng sau đó đã học được tầm quan trọng của sự trung thực và liêm khiết. Anh đã thay đổi cách nhìn nhận về cuộc sống và giá trị của sự trung thực.\\n\\n\\nRelation to main character: Anh chàng tiều phu là nhân vật chính, và câu chuyện xoay quanh cuộc đời của anh.\\n\\n\\nUnique traits: Trung thực, liêm khiết, biết ơn, kiên trì.\\n\\n\\nGhost/Wound: Mất mát và khó khăn trong cuộc sống, đặc biệt là việc mất chiếc rìu sắt của mình.\\n\\n\\nWant vs Need: Anh chàng tiều phu MUỐN tìm lại chiếc rìu sắt của mình, nhưng anh CẦN học được tầm quan trọng của sự trung thực và liêm khiết.\\n\\n\\nLie vs Truth: Anh chàng tiều phu ban đầu tin rằng chỉ có tiền bạc và tài sản mới giúp anh vượt qua khó khăn (LIE), nhưng sau đó đã học được rằng sự trung thực và liêm khiết là những giá trị quan trọng hơn cả (TRUTH).\\n\\n\\nArc (Hành trình thay đổi):\\n\\n- Hồi 1: Anh chàng tiều phu mất chiếc rìu sắt của mình và cảm thấy tuyệt vọng. Anh bắt đầu tìm kiếm sự giúp đỡ từ ông cụ.\\n- Hồi 2A: Anh chàng tiều phu được ông cụ giúp đỡ, nhưng anh phải đối mặt với thử thách về sự trung thực của mình khi ông cụ tìm thấy hai chiếc rìu bằng bạc và vàng.\\n- Hồi 2B: Anh chàng tiều phu phải đối mặt với khó khăn và thử thách về sự trung thực của mình, nhưng cuối cùng đã tìm thấy chiếc rìu sắt của mình.\\n- Hồi 3: Anh chàng tiều phu đã học được tầm quan trọng của sự trung thực và liêm khiết, và đã được ông cụ tặng thêm hai chiếc rìu khác.\\n\\nÔng CỬ: Nam. Không rõ tuổi. Là một người tốt bụng, hiền từ, muốn giúp đỡ người khác.\\n\\nDescription: Ông cụ là một người tốt bụng, muốn giúp đỡ anh chàng tiều phu nghèo. Ông có nhiệm vụ giúp đỡ anh chàng tiều phu và dạy cho anh về tầm quan trọng của sự trung thực và liêm khiết.\\n\\n\\nWorldview: Ông cụ có một cách nhìn nhận về cuộc sống rất tích cực, và anh muốn giúp đỡ người khác để họ có thể đạt được hạnh phúc.\\n\\n\\nRelation to main character: Ông cụ là người giúp đỡ anh chàng tiều phu, và có mối quan hệ tốt đẹp với anh.\\n\\n\\nUnique traits: Tốt bụng, hiền từ, biết cách giúp đỡ người khác.\\n\\n\\nGhost/Wound: Không rõ.\\n\\n\\nWant vs Need: Ông cụ MUỐN giúp đỡ anh chàng tiều phu, và anh CẦN giúp đỡ người khác để họ có thể đạt được hạnh phúc.\\n\\n\\nLie vs Truth: Ông cụ không có niềm tin sai lầm, và anh đã biết được tầm quan trọng của sự trung thực và liêm khiết.\\n\\n\\nArc (Hành trình thay đổi):\\n\\n- Hồi 1: Ông cụ gặp anh chàng tiều phu và quyết định giúp đỡ anh.\\n- Hồi 2A: Ông cụ giúp đỡ anh chàng tiều phu tìm kiếm chiếc rìu sắt của mình.\\n- Hồi 2B: Ông cụ tiếp tục giúp đỡ anh chàng tiều phu, và cuối cùng đã tìm thấy chiếc rìu sắt của anh.\\n- Hồi 3: Ông cụ đã giúp đỡ anh chàng tiều phu đạt được hạnh phúc, và đã tặng thêm hai chiếc rìu khác cho anh.\\n\\nĐánh giá: Arc nhân vật của anh chàng tiều phu và ông cụ là thuyết phục, vì họ đã trải qua một hành trình thay đổi rõ ràng và đã đạt được mục tiêu của mình. Tuy nhiên, arc nhân vật của ông cụ có thể được phát triển thêm để làm cho câu chuyện trở nên thú vị hơn.\",\"structure\":\"🎬 CẤU TRÚC 4 HỒIHỒI 1: SETUP (Trang 1-25, khoảng 25 phút)Mục tiêu hồi này: Thiết lập thế giới, nhân vật, và vấn đềAnh chàng tiều phu nghèo sống một cuộc sống khó khăn, mồ côi cha mẹ từ nhỏ và chỉ có một chiếc rìu sắt để đốn củi kiếm sống. Mỗi ngày, anh đều vào rừng để đốn củi và bán chúng để có tiền trang trải cuộc sống. Tuy nhiên, trong một ngày không may, chiếc rìu sắt của anh bị gãy cán và lưỡi rìu văng xuống sông chảy xiết. Anh chàng tiều phu cảm thấy tuyệt vọng và ngồi khóc than thở vì không biết làm thế nào để lấy lại chiếc rìu quan trọng của mình.Các điểm ngoặt quan trọng:Opening Image (Trang 1): Anh chàng tiều phu nghèo sống một cuộc sống khó khănCatalyst (Trang 10): Chiếc rìu sắt của anh bị gãy cán và lưỡi rìu văng xuống sôngBreak into Two (Trang 25): Anh chàng tiều phu gặp ông cụ và được ông cụ đề nghị giúp đỡHỒI 2A: RESPONSE (Trang 25-55, khoảng 30 phút)Mục tiêu hồi này: Anh chàng tiều phu phản ứng với sự giúp đỡ của ông cụÔng cụ lao mình xuống dòng sông chảy xiết và tìm thấy một chiếc rìu bằng bạc. Tuy nhiên, khi hỏi anh chàng tiều phu, anh đã xác định rằng đó không phải là chiếc rìu của mình. Ông cụ lại lao mình xuống sông lần thứ hai và tìm thấy một chiếc rìu bằng vàng. Một lần nữa, anh chàng tiều phu xác định rằng đó không phải là chiếc rìu của mình.Các điểm ngoặt quan trọng:B-Story Begins (Trang 30): Ông cụ giúp đỡ anh chàng tiều phuMidpoint (Trang 55): Ông cụ tìm thấy chiếc rìu bằng bạc và vàng, nhưng không phải là của anh chàng tiều phuHỒI 2B: ACTION (Trang 55-85, khoảng 30 phút)Mục tiêu hồi này: Anh chàng tiều phu phải đối mặt với thử thách về sự trung thực của mìnhCuối cùng, ông cụ lao xuống sông lần thứ ba và tìm thấy chiếc rìu bằng sắt của anh chàng tiều phu. Anh chàng tiều phu rất vui mừng khi được tìm lại chiếc rìu của mình và cảm ơn ông cụ vì sự giúp đỡ. Tuy nhiên, ông cụ không chỉ trả lại chiếc rìu sắt cho anh chàng tiều phu mà còn tặng anh hai chiếc rìu bằng bạc và vàng vì anh là người trung thực và liêm khiết.Các điểm ngoặt quan trọng:All Is Lost (Trang 75): Anh chàng tiều phu chưa tìm thấy chiếc rìu của mìnhDark Night of the Soul (Trang 75-85): Anh chàng tiều phu phải đối mặt với thử thách về sự trung thực của mìnhBreak into Three (Trang 85): Anh chàng tiều phu tìm thấy chiếc rìu của mình và được ông cụ tặng thêm hai chiếc rìu khácHỒI 3: CLIMAX (Trang 85-110, khoảng 25 phút)Mục tiêu hồi này: Giải quyết xung đột chính và hoàn thành arc nhân vậtAnh chàng tiều phu đã học được một bài học quan trọng về tầm quan trọng của sự trung thực và liêm khiết. Ông cụ cảm phục anh chàng tiều phu và quyết định giúp đỡ anh bằng cách tặng cho anh hai chiếc rìu bằng bạc và vàng. Anh chàng tiều phu đã vượt qua thử thách và chứng minh được sự trung thực và liêm khiết của mình.Các điểm ngoặt quan trọng:Climax (Trang 100-105): Anh chàng tiều phu được ông cụ tặng thêm hai chiếc rìu khácFinal Image (Trang 110): Anh chàng tiều phu đã học được một bài học quan trọng về sự trung thực và liêm khiết🔄 TỔNG QUAN ARC NHÂN VẬT QUA 4 HỒIAnh chàng tiều phu đã trải qua một hành trình thay đổi từ một người chỉ tập trung vào việc kiếm sống trở thành người đánh giá cao sự trung thực và liêm khiết. Anh đã học được tầm quan trọng của sự trung thực và liêm khiết trong cuộc sống và đã vượt qua thử thách về sự trung thực của mình. Cuối cùng, anh đã được ông cụ giúp đỡ và tặng thêm hai chiếc rìu khác, thể hiện sự trung thực và liêm khiết của mình.\",\"beatsheet\":\"📋 BEAT SHEET CHI TIẾTBEAT 1: OPENING IMAGE (Trang 1)Mục đích: Thiết lập tone, mood, và trạng thái \\\"trước\\\" của nhân vậtNội dung: Anh chàng tiều phu nghèo sống một cuộc sống khó khăn, mồ côi cha mẹ từ nhỏ và chỉ có một chiếc rìu sắt để đốn củi kiếm sống.Liên kết với Final Image: Đối lập với hình ảnh cuối khi anh chàng tiều phu đã tìm lại chiếc rìu sắt và nhận được món quà từ ông cụ, thể hiện sự thay đổi và phát triển của nhân vật.BEAT 2: THEME STATED (Trang 5)Mục đích: Ai đó (không phải protagonist) nói điều gì liên quan đến chủ đềNội dung: Không có thông tin cụ thể về một nhân vật nào đó nói về chủ đề, nhưng có thể suy đoán rằng chủ đề về sự trung thực và liêm khiết được ngụ ý thông qua hành động và quyết định của anh chàng tiều phu.Chủ đề được ngụ ý: Sự trung thực và liêm khiết là những giá trị quan trọng trong cuộc sống.BEAT 3: SETUP (Trang 1-10)Mục đích: Giới thiệu thế giới, nhân vật, điểm yếu, stakesNội dung: Anh chàng tiều phu sống một cuộc sống khó khăn, chỉ có một chiếc rìu sắt để đốn củi kiếm sống.Mối quan hệ quan trọng: Không có thông tin về mối quan hệ quan trọng nào ngoài mối quan hệ với ông cụ sau này.Điểm yếu/vấn đề của nhân vật: Anh chàng tiều phu chỉ tập trung vào việc kiếm sống, chưa đánh giá cao sự trung thực và liêm khiết.\\\"Save the Cat\\\" moment: Không có thông tin cụ thể, nhưng có thể xem việc anh chàng tiều phu trung thực về chiếc rìu sắt không phải của mình là một hành động cho thấy nhân vật đáng yêu.BEAT 4: CATALYST (Trang 12)Mục đích: Sự kiện phá vỡ trạng thái cân bằngNội dung: Chiếc rìu sắt của anh chàng tiều phu bị gãy cán và lưỡi rìu văng xuống sông chảy xiết.Tại sao nhân vật không thể bỏ qua: Anh chàng tiều phu cần chiếc rìu sắt để kiếm sống, không có nó, anh sẽ gặp khó khăn trong việc kiếm tiền.BEAT 5: DEBATE (Trang 12-25)Mục đích: Nhân vật do dự, cân nhắcNội dung: Anh chàng tiều phu cảm thấy tuyệt vọng và ngồi khóc than thở vì không biết làm thế nào để lấy lại chiếc rìu quan trọng của mình.Nội tâm nhân vật: Sợ hãi, tuyệt vọng, và bối rối về tương lai.BEAT 6: BREAK INTO TWO (Trang 25)Mục đích: Nhân vật CHỌN hành động, bước vào Act 2Nội dung: Anh chàng tiều phu gặp ông cụ và được ông cụ đề nghị giúp đỡ.Đây là điểm không thể quay lại vì: Anh chàng tiều phu đã bắt đầu một hành trình mới với sự giúp đỡ của ông cụ, không thể quay lại cuộc sống trước đó.BEAT 7: B STORY (Trang 30)Mục đích: Giới thiệu tuyến phụ (thường là love interest), thể hiện chủ đềNội dung: Ông cụ giúp đỡ anh chàng tiều phu tìm lại chiếc rìu sắt, thể hiện sự trung thực và liêm khiết.Cách B-story phản ánh chủ đề: Sự giúp đỡ của ông cụ và quyết định trung thực của anh chàng tiều phu phản ánh chủ đề về tầm quan trọng của sự trung thực và liêm khiết.BEAT 8: FUN AND GAMES (Trang 30-55)Mục đích: \\\"Promise of the premise\\\" - lý do khán giả xem phimNội dung: Ông cụ lao mình xuống dòng sông chảy xiết và tìm thấy một chiếc rìu bằng bạc.Ông cụ lại lao mình xuống sông lần thứ hai và tìm thấy một chiếc rìu bằng vàng.Anh chàng tiều phu xác định rằng những chiếc rìu đó không phải là của mình.Nhân vật đang học/làm gì: Anh chàng tiều phu đang học về tầm quan trọng của sự trung thực và liêm khiết thông qua hành động của mình và ông cụ.BEAT 9: MIDPOINT (Trang 55)Mục đích: False Victory hoặc False Defeat + RevelationLoại: False DefeatNội dung: Ông cụ tìm thấy chiếc rìu bằng bạc và vàng, nhưng không phải là của anh chàng tiều phu.Revelation/Stakes mới: Anh chàng tiều phu vẫn chưa tìm thấy chiếc rìu sắt của mình, và ông cụ tiếp tục giúp đỡ anh.BEAT 10: BAD GUYS CLOSE IN (Trang 55-75)Mục đích: Áp lực từ bên ngoài VÀ bên trong tăng caoÁp lực bên ngoài:Ông cụ lao xuống sông lần thứ ba để tìm chiếc rìu sắt.Áp lực thời gian và nguy cơ không tìm thấy chiếc rìu sắt.Áp lực bên trong (đội nhóm tan rã, nghi ngờ...):Anh chàng tiều phu cảm thấy tuyệt vọng và nghi ngờ về khả năng tìm lại chiếc rìu sắt.BEAT 11: ALL IS LOST (Trang 75)Mục đích: Điểm thấp nhất, \\\"whiff of death\\\"Nội dung: Anh chàng tiều phu chưa tìm thấy chiếc rìu sắt của mình, và cảm thấy tuyệt vọng về tương lai.Mất mát: Chiếc rìu sắt vẫn chưa được tìm thấy, và hy vọng của anh chàng tiều phu đang giảm dần.Tại sao nhân vật tưởng như hết hy vọng: Anh chàng tiều phu đã trải qua nhiều thất bại và chưa tìm thấy chiếc rìu sắt, khiến anh cảm thấy không còn hy vọng.BEAT 12: DARK NIGHT OF THE SOUL (Trang 75-85)Mục đích: Nhân vật đối mặt với bản thân, với LieNội dung: Anh chàng tiều phu phải đối mặt với thử thách về sự trung thực của mình khi ông cụ tìm thấy chiếc rìu sắt.Nhận ra điều gì: Anh chàng tiều phu nhận ra rằng sự trung thực và liêm khiết là quan trọng hơn cả, và anh sẵn sàng trung thực về chiếc rìu sắt.BEAT 13: BREAK INTO THREE (Trang 85)Mục đích: Tìm ra giải pháp, kết hợp A + B storyNội dung: Anh chàng tiều phu tìm thấy chiếc rìu sắt của mình, và ông cụ tặng anh hai chiếc rìu bằng bạc và vàng vì sự trung thực và liêm khiết của anh.Cách B-story giúp tìm ra giải pháp: Sự giúp đỡ của ông cụ và quyết định trung thực của anh chàng tiều phu dẫn đến việc tìm lại chiếc rìu sắt và nhận được món quà.BEAT 14: FINALE (Trang 85-110)Mục đích: Thực hiện kế hoạch, đối đầu cuối cùng5 bước của Finale:Gathering the team: Không áp dụng trong trường hợp này.Executing the plan: Ông cụ và anh chàng tiều phu đã tìm thấy chiếc rìu sắt.High Tower Surprise: Không áp dụng trong trường hợp này.Dig Deep Down: Anh chàng tiều phu đã trung thực về chiếc rìu sắt và nhận được món quà.Victory/Defeat: Anh chàng tiều phu đã tìm thấy chiếc rìu sắt và nhận được món quà, thể hiện sự trung thực và liêm khiết của mình.BEAT 15: FINAL IMAGE (Trang 110)Mục đích: Hình ảnh đối lập với Opening, chứng minh sự thay đổiNội dung: Anh chàng tiều phu đã tìm lại chiếc rìu sắt và nhận được món quà từ ông cụ, thể hiện sự thay đổi và phát triển của nhân vật.Đối lập với Opening như thế nào: Anh chàng tiều phu đã thay đổi từ một người chỉ tập trung vào việc kiếm sống trở thành người đánh giá cao sự trung thực và liêm khiết.🔗 SƠ ĐỒ LIÊN KẾT CÁC BEATMỗi beat trong câu chuyện đều có liên kết nhân quả với beat trước và sau, thể hiện sự logic và phát triển của câu chuyện. Từ việc mất chiếc rìu sắt đến việc tìm lại nó, anh chàng tiều phu đã trải qua nhiều thử thách và đã học được tầm quan trọng của sự trung thực và liêm khiết.\"}', '<h2>🎬 DANH SÁCH CẢNH</h2></p><p><h3>═══════════════════════════════════════</h3><br><h3>HỒI 1: SETUP (Cảnh 1-10)</h3><br><h3>═══════════════════════════════════════</h3></p><p><strong>CẢNH 1:</strong> NỘI. NGÔI NHÀ TIỂU PHU - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thiết lập cuộc sống khó khăn của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đang chuẩn bị đi đốn củi, thể hiện cuộc sống khó khăn của mình.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu cầm chiếc rìu sắt và bước ra khỏi nhà.</li></ul></p><p><strong>CẢNH 2:</strong> NGOẠI. RỪNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện công việc đốn củi của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đang đốn củi trong rừng, thể hiện sự khó khăn của công việc.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu dừng lại để nghỉ ngơi.</li></ul></p><p><strong>CẢNH 3:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự cố xảy ra với chiếc rìu sắt</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đang đi dọc theo sông, chiếc rìu sắt của anh bị gãy cán và lưỡi rìu văng xuống sông.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu cảm thấy tuyệt vọng.</li></ul></p><p><strong>CẢNH 4:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện nỗi tuyệt vọng của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đang ngồi khóc than thở vì không biết làm thế nào để lấy lại chiếc rìu quan trọng của mình.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn thấy ông cụ đang đi tới.</li></ul></p><p><strong>CẢNH 5:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự gặp gỡ giữa anh chàng tiều phu và ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu gặp ông cụ, và ông cụ hỏi về lý do tại sao anh lại khóc.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu kể cho ông cụ nghe về hoàn cảnh khó khăn của mình.</li></ul></p><p><strong>CẢNH 6:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự giúp đỡ của ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Ông cụ đề nghị sẽ lặn xuống sông để tìm lại chiếc rìu cho anh chàng tiều phu.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ bắt đầu lặn xuống sông.</li></ul></p><p><strong>CẢNH 7:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tìm kiếm của ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Ông cụ đang tìm kiếm chiếc rìu sắt trong sông.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ tìm thấy một chiếc rìu bằng bạc.</li></ul></p><p><strong>CẢNH 8:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự xác định của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu xác định rằng chiếc rìu bằng bạc không phải là của mình.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ tiếp tục tìm kiếm.</li></ul></p><p><strong>CẢNH 9:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tìm kiếm tiếp theo của ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Ông cụ lại lao mình xuống sông lần thứ hai và tìm thấy một chiếc rìu bằng vàng.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu lại xác định rằng chiếc rìu bằng vàng không phải là của mình.</li></ul></p><p><strong>CẢNH 10:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự quyết tâm của ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Ông cụ quyết định tìm kiếm lần thứ ba.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ lao xuống sông lần thứ ba.</li></ul></p><p><h3>═══════════════════════════════════════</h3><br><h3>HỒI 2A: RESPONSE (Cảnh 11-20)</h3><br><h3>═══════════════════════════════════════</h3></p><p><strong>CẢNH 11:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tìm kiếm lần thứ ba của ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Ông cụ đang tìm kiếm chiếc rìu sắt trong sông lần thứ ba.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ tìm thấy chiếc rìu bằng sắt.</li></ul></p><p><strong>CẢNH 12:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự xác định cuối cùng của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu xác định rằng chiếc rìu bằng sắt là của mình.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu cảm thấy vui mừng.</li></ul></p><p><strong>CẢNH 13:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự biết ơn của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu cảm ơn ông cụ vì sự giúp đỡ.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Ông cụ mỉm cười.</li></ul></p><p><strong>CẢNH 14:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tặng quà của ông cụ</li></ul><br><ul><li><strong>Tóm tắt:</strong> Ông cụ tặng anh chàng tiều phu hai chiếc rìu bằng bạc và vàng vì anh là người trung thực và liêm khiết.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu cảm thấy bất ngờ và biết ơn.</li></ul></p><p><strong>CẢNH 15:</strong> NGOẠI. SÔNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu, Ông cụ</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự thay đổi của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đã học được một bài học quan trọng về tầm quan trọng của sự trung thực và liêm khiết.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu và ông cụ chia tay.</li></ul></p><p><h3>═══════════════════════════════════════</h3><br><h3>HỒI 2B: ACTION (Cảnh 21-32)</h3><br><h3>═══════════════════════════════════════</h3></p><p><strong>CẢNH 21:</strong> NGOẠI. RỪNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự thay đổi của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đang đi trong rừng, cảm thấy tự tin và biết ơn vì đã tìm lại chiếc rìu sắt và nhận được món quà từ ông cụ.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn thấy một người cần giúp đỡ.</li></ul></p><p><strong>CẢNH 22:</strong> NGOẠI. RỪNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự giúp đỡ của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu giúp đỡ người cần giúp đỡ, thể hiện sự thay đổi và phát triển của nhân vật.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Người cần giúp đỡ cảm ơn anh chàng tiều phu.</li></ul></p><p><strong>CẢNH 23:</strong> NGOẠI. RỪNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự tự tin của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu cảm thấy tự tin và biết ơn vì đã tìm lại chiếc rìu sắt và nhận được món quà từ ông cụ.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu tiếp tục đi trong rừng.</li></ul></p><p><strong>CẢNH 24:</strong> NGOẠI. RỪNG - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự phát triển của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đã học được một bài học quan trọng về tầm quan trọng của sự trung thực và liêm khiết, và đã trở thành một người tốt hơn.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu trở về nhà.</li></ul></p><p><strong>CẢNH 25:</strong> NỘI. NGÔI NHÀ TIỂU PHU - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự trở về của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu trở về nhà, cảm thấy tự tin và biết ơn vì đã tìm lại chiếc rìu sắt và nhận được món quà từ ông cụ.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu bắt đầu một cuộc sống mới.</li></ul></p><p><h3>═══════════════════════════════════════</h3><br><h3>HỒI 3: CLIMAX (Cảnh 33-40)</h3><br><h3>═══════════════════════════════════════</h3></p><p><strong>CẢNH 33:</strong> NỘI. NGÔI NHÀ TIỂU PHU - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự thay đổi của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đã học được một bài học quan trọng về tầm quan trọng của sự trung thực và liêm khiết, và đã trở thành một người tốt hơn.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu nhìn lại cuộc sống trước đây.</li></ul></p><p><strong>CẢNH 34:</strong> NỘI. NGÔI NHÀ TIỂU PHU - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự biết ơn của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu cảm ơn ông cụ vì sự giúp đỡ và món quà.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu mỉm cười.</li></ul></p><p><strong>CẢNH 35:</strong> NỘI. NGÔI NHÀ TIỂU PHU - BAN NGÀY<br><ul><li><strong>Nhân vật:</strong> Anh chàng tiều phu</li></ul><br><ul><li><strong>Mục đích:</strong> Thể hiện sự phát triển của anh chàng tiều phu</li></ul><br><ul><li><strong>Tóm tắt:</strong> Anh chàng tiều phu đã trở thành một người tốt hơn, biết ơn vì đã tìm lại chiếc rìu sắt và nhận được món quà từ ông cụ.</li></ul><br><ul><li><strong>Kết thúc với:</strong> Anh chàng tiều phu bắt đầu một cuộc sống mới.</li></ul></p><p><h2>📊 THỐNG KÊ</h2><br><ul><li>Tổng số cảnh: 35</li></ul><br><ul><li>Số cảnh NỘI: 5</li></ul><br><ul><li>Số cảnh NGOẠI: 30</li></ul><br><ul><li>Số cảnh NGÀY: 35</li></ul><br><ul><li>Số cảnh ĐÊM: 0</li></ul></p><p><h2>🔗 SƠ ĐỒ LIÊN KẾT NHÂN QUẢ</h2><br>Mỗi cảnh trong danh sách đều có liên kết nhân quả với cảnh trước và sau, thể hiện sự logic và phát triển của câu chuyện. Từ việc mất chiếc rìu sắt đến việc tìm lại nó, anh chàng tiều phu đã trải qua nhiều thử thách và đã học được tầm quan trọng của sự trung thực và liêm khiết.', '2026-02-25 15:08:22'),
(5, 23, 'story', '{\"synopsis\":\"Tuyệt vời! Dưới đây là SYNOPSIS của câu chuyện \\\"Ba Lưỡi Rìu\\\" được viết theo phong cách biên kịch Hollywood chuyên nghiệp, đáp ứng đầy đủ các yêu cầu và lưu ý bạn đã đưa ra:📖 SYNOPSISMỞ ĐẦUMột anh chàng TIỀU PHU trẻ tuổi sống trong cảnh nghèo khó sau khi cha mẹ qua đời. Tài sản duy nhất của anh là chiếc rìu sắt cũ kỹ, thứ giúp anh kiếm sống bằng việc đốn củi trong rừng. Anh là người hiền lành, chất phác, luôn cố gắng làm việc chăm chỉ để vượt qua khó khăn. Tuy nhiên, cuộc sống mưu sinh vất vả khiến anh nhiều lúc cảm thấy chán nản và lo lắng về tương lai mờ mịt.Một ngày nọ, khi đang đốn củi bên bờ sông chảy xiết, lưỡi rìu của anh không may bị gãy và văng xuống nước. Anh tuyệt vọng vì mất đi công cụ kiếm sống duy nhất. Ngồi bên bờ sông, anh khóc than cho số phận hẩm hiu của mình.PHÁT TRIỂNTrong lúc tuyệt vọng, một ÔNG CỤ tóc bạc phơ, dáng vẻ hiền từ xuất hiện trước mặt anh. Ông cụ hỏi han và biết được câu chuyện của anh. Cảm động trước hoàn cảnh của chàng tiều phu, ông cụ đề nghị giúp anh tìm lại chiếc rìu.Ông cụ lặn xuống sông và mang lên một chiếc rìu bằng bạc sáng loáng. Anh tiều phu thật thà từ chối, nói rằng đó không phải là rìu của mình. Ông cụ tiếp tục lặn xuống lần thứ hai, mang lên một chiếc rìu bằng vàng rực rỡ. Anh tiều phu vẫn kiên quyết từ chối, khẳng định chiếc rìu của anh chỉ là một chiếc rìu sắt bình thường.CAO TRÀOÔng cụ lặn xuống sông lần thứ ba và cuối cùng mang lên chiếc rìu sắt cũ kỹ của anh. Anh tiều phu mừng rỡ nhận lại chiếc rìu của mình. Ông cụ khen ngợi sự trung thực và lòng tốt của anh, nói rằng anh không hề tham lam tiền bạc và lợi lộc.Anh tiều phu cảm thấy xấu hổ khi được khen ngợi, anh chỉ nghĩ đơn giản rằng mình không thể nhận một thứ không thuộc về mình. Ông cụ tiết lộ mình là một vị thần và quyết định ban thưởng cho anh vì sự trung thực của mình.KẾT THÚCÔng cụ trao cho anh hai chiếc rìu bằng vàng và bạc như một món quà. Anh tiều phu vô cùng biết ơn và hứa sẽ sử dụng những món quà này một cách khôn ngoan. Từ đó, cuộc sống của anh trở nên tốt đẹp hơn, nhưng anh vẫn giữ vững sự trung thực và lòng tốt của mình, luôn sẵn lòng giúp đỡ những người gặp khó khăn. Anh hiểu rằng sự trung thực và lòng tốt mới là những tài sản quý giá nhất.🔑 CÁC ĐIỂM NGOẶT QUAN TRỌNGInciting Incident: Chiếc rìu của anh tiều phu bị gãy và rơi xuống sông, khiến anh mất đi công cụ kiếm sống duy nhất.Plot Point 1: Ông cụ xuất hiện và đề nghị giúp anh tìm lại chiếc rìu.Midpoint: Ông cụ mang lên chiếc rìu bằng bạc, anh tiều phu từ chối. (Sự xuất hiện của chiếc rìu bạc đánh dấu bước ngoặt, khi anh tiều phu đối mặt với cám dỗ của sự giàu có.)Plot Point 2: Ông cụ mang lên chiếc rìu bằng vàng, anh tiều phu tiếp tục từ chối. (Anh tiều phu tiếp tục chứng minh sự trung thực của mình.)Climax: Ông cụ tiết lộ mình là thần và ban thưởng cho anh tiều phu vì sự trung thực của mình.\",\"characters\":\"Tuyệt vời! Dưới đây là hồ sơ nhân vật chi tiết dựa trên câu chuyện \\\"Ba Lưỡi Rìu\\\" bạn cung cấp, tập trung vào các yếu tố quan trọng như tính cách, động lực, và vai trò của họ trong việc thể hiện chủ đề của câu chuyện.🦸 NHÂN VẬT CHÍNH (PROTAGONIST)ANH TIỀU PHUTuổi/Nghề nghiệp: Trẻ tuổi, tiều phu (người đốn củi)Ngoại hình: Không được mô tả chi tiết, nhưng có thể hình dung là một người gầy gò, lam lũ vì cuộc sống khó khăn.Tính cách: Thật thà, chất phác, chăm chỉ, hiền lành, có lòng tự trọng.Điểm yếu (Flaw): Nghèo khó, có thể thiếu tự tin do hoàn cảnh.Backstory: Mồ côi cha mẹ từ nhỏ, lớn lên trong nghèo khó, tài sản duy nhất là chiếc rìu.Ghost/Wound: Sự mất mát cha mẹ và nỗi lo cơm áo gạo tiền luôn ám ảnh anh.WANT (Muốn): Có đủ tiền để sống qua ngày, thoát khỏi cảnh nghèo khó.NEED (Cần): Giữ vững sự trung thực và lòng tốt, nhận ra giá trị thực sự của bản thân và cuộc sống.Arc dự kiến: Từ một người tiều phu nghèo khó, lo lắng về cuộc sống → trở thành một người được đền đáp xứng đáng vì sự trung thực của mình, có cuộc sống tốt đẹp hơn.Vai trò trong chủ đề: Thể hiện rằng sự trung thực và lòng tốt sẽ được đền đáp, và những phẩm chất này quan trọng hơn vật chất.😈 NHÂN VẬT ĐỐI KHÁNG (ANTAGONIST)Không có nhân vật phản diện rõ ràng trong câu chuyện này. Tuy nhiên, SỰ NGHÈO KHÓ và CƠ HỘI ĐỂ THAM LAM có thể được xem là lực cản mà nhân vật chính phải vượt qua.Sự Nghèo Khó: Là hoàn cảnh khó khăn mà anh tiều phu phải đối mặt hàng ngày, tạo ra áp lực và cám dỗ để anh có thể chọn con đường không trung thực.Cơ Hội Để Tham Lam: Sự xuất hiện của những chiếc rìu bằng vàng và bạc là một thử thách. Anh tiều phu có thể dễ dàng nói dối để có được những tài sản giá trị này.Việc anh tiều phu vượt qua những \\\"thế lực\\\" này bằng sự trung thực cho thấy sức mạnh của phẩm chất tốt đẹp và chiến thắng của nó trước những khó khăn và cám dỗ.👥 NHÂN VẬT PHỤÔNG CỤ (BỤT)Vai trò: Người thử thách và ban thưởng.Tính cách: Hiền từ, nhân hậu, có phép thuật, công bằng.Mục đích: Thử thách lòng trung thực của anh tiều phu và ban thưởng cho những người có phẩm chất tốt đẹp.Mối quan hệ với protagonist: Người giúp đỡ, ân nhân.🔗 SƠ ĐỒ MỐI QUAN HỆAnh Tiều Phu ↔ Ông Cụ (Bụt): Mối quan hệ giữa người gặp khó khăn và người giúp đỡ. Ông cụ đóng vai trò như một người thử thách và sau đó là ân nhân của anh tiều phu.Anh Tiều Phu ↔ Sự Nghèo Khó: Mối quan hệ giữa người phải vật lộn với hoàn cảnh và chính hoàn cảnh đó. Sự nghèo khó là động lực để anh tiều phu làm việc chăm chỉ, nhưng cũng là cám dỗ để anh có thể chọn con đường không trung thực.Anh Tiều Phu ↔ Những Chiếc Rìu (Sắt, Bạc, Vàng): Biểu tượng cho giá trị vật chất và sự lựa chọn giữa trung thực và lòng tham. Chiếc rìu sắt là công cụ kiếm sống của anh, trong khi rìu bạc và vàng là thử thách về lòng trung thực.Phân tích này tập trung vào các yếu tố chính trong câu chuyện và làm nổi bật vai trò của từng nhân vật trong việc thể hiện chủ đề về sự trung thực và lòng tốt.\",\"structure\":\"Tuyệt vời! Dưới đây là phân tích cấu trúc 4 hồi chi tiết dựa trên truyện \\\"Ba Lưỡi Rìu\\\" theo Story Circle của Dan Harmon.🎬 CẤU TRÚC 4 HỒIHỒI 1: SETUP (Trang 1-25, khoảng 25 phút - Tương đối ngắn trong truyện này)Mục tiêu hồi này: Giới thiệu anh tiều phu, cuộc sống nghèo khó của anh, và sự kiện chiếc rìu rơi xuống sông, tạo ra vấn đề cần giải quyết.Anh tiều phu sống cuộc sống nghèo khó, mồ côi và phải kiếm sống bằng việc đốn củi. (YOU - Comfort Zone). Anh ta cần chiếc rìu để kiếm sống và thoát khỏi cảnh nghèo khổ (NEED). Một ngày nọ, chiếc rìu bị gãy và rơi xuống sông (Catalyst - Trang 1). Anh tiều phu tuyệt vọng, không biết làm gì để kiếm sống. Anh ngồi khóc than bên bờ sông, lưỡng lự không biết phải làm gì (Debate). Anh ta không có lựa chọn nào khác ngoài việc chấp nhận số phận hoặc tìm kiếm sự giúp đỡ (Break into Two - Trang 3).Các điểm ngoặt quan trọng:Opening Image (Trang 1): Anh tiều phu đốn củi trong rừng, thể hiện cuộc sống nghèo khó.Catalyst (Trang 1): Chiếc rìu bị gãy và rơi xuống sông.Break into Two (Trang 3): Anh tiều phu quyết định chấp nhận số phận hoặc tìm kiếm sự giúp đỡ (implied).HỒI 2A: RESPONSE (Trang 25-55, khoảng 30 phút - Tương đối ngắn)Mục tiêu hồi này: Anh tiều phu gặp ông cụ, hy vọng được giúp đỡ, và bắt đầu quá trình thử thách lòng trung thực.Ông cụ xuất hiện và hỏi han anh tiều phu (GO - Trang 3). Anh tiều phu kể lại câu chuyện của mình và bày tỏ sự tuyệt vọng. Ông cụ đề nghị giúp anh tìm lại chiếc rìu (SEARCH). Ông cụ lặn xuống sông và mang lên chiếc rìu bạc (B-Story Begins - Trang 4). Anh tiều phu từ chối nhận vì đó không phải là của mình. Đây là một \\\"thắng lợi giả\\\" vì anh đã có cơ hội đổi đời nhưng lại từ chối vì sự trung thực (Midpoint - Trang 5).Các điểm ngoặt quan trọng:B-Story Begins (Trang 4): Sự xuất hiện của chiếc rìu bạc.Midpoint (Trang 5): Anh tiều phu từ chối chiếc rìu bạc, chứng minh sự trung thực. (False victory + Revelation: Sự trung thực quan trọng hơn vật chất)HỒI 2B: ACTION (Trang 55-85, khoảng 30 phút - Tương đối ngắn)Mục tiêu hồi này: Cám dỗ tăng cao, anh tiều phu tiếp tục chứng minh sự trung thực của mình.Việc từ chối chiếc rìu bạc có thể khiến anh tiều phu cảm thấy hối tiếc hoặc lo lắng về tương lai (Bad Guys Close In - Trang 5). Ông cụ tiếp tục lặn xuống và mang lên chiếc rìu vàng (All Is Lost - Trang 6). Anh tiều phu lại từ chối, khẳng định chiếc rìu của mình chỉ là rìu sắt. Đây là khoảnh khắc anh phải đối mặt với cám dỗ lớn nhất (Dark Night of the Soul - Trang 6). Anh tiều phu nhận ra rằng sự trung thực là quan trọng hơn việc có được một tài sản lớn (Break into Three - Trang 6).Các điểm ngoặt quan trọng:All Is Lost (Trang 6): Sự xuất hiện của chiếc rìu vàng.Dark Night of the Soul (Trang 6): Anh tiều phu đối mặt với cám dỗ của sự giàu có.Break into Three (Trang 6): Anh tiều phu nhận ra giá trị của sự trung thực.HỒI 3: CLIMAX (Trang 85-110, khoảng 25 phút - Tương đối ngắn)Mục tiêu hồi này: Anh tiều phu được đền đáp và cuộc sống thay đổi.Ông cụ mang lên chiếc rìu sắt của anh tiều phu (RETURN - Trang 7). Anh vui mừng nhận lại chiếc rìu của mình. Ông cụ khen ngợi và ban thưởng cho anh hai chiếc rìu vàng và bạc (Climax - Trang 7). Anh tiều phu trở nên giàu có hơn nhưng vẫn giữ vững sự trung thực và lòng tốt (CHANGE - Trang 8). Kết thúc truyện không có hình ảnh đối lập rõ ràng, nhưng có thể hiểu rằng anh tiều phu giờ đây không còn phải lo lắng về cuộc sống nghèo khó nữa. (Final Image)Các điểm ngoặt quan trọng:Climax (Trang 7): Anh tiều phu được ban thưởng.Final Image (Trang 8): Cuộc sống của anh tiều phu trở nên tốt đẹp hơn.🔄 TỔNG QUAN ARC NHÂN VẬT QUA 4 HỒIAnh tiều phu bắt đầu là một người nghèo khó, lo lắng về cuộc sống. Qua thử thách mất rìu và cám dỗ của sự giàu có, anh đã chứng minh được sự trung thực của mình. Cuối cùng, anh được đền đáp xứng đáng và có một cuộc sống tốt đẹp hơn, đồng thời vẫn giữ vững những phẩm chất tốt đẹp.Đánh giá nhịp phim và tỷ lệ phân bổ:Truyện \\\"Ba Lưỡi Rìu\\\" có cấu trúc khá đơn giản và ngắn gọn. Tỷ lệ phân bổ thời gian cho các hồi không đồng đều, với Hồi 1 và Hồi 2A/2B khá ngắn. Điều này có thể là do truyện tập trung vào việc truyền tải thông điệp đạo đức hơn là xây dựng một cốt truyện phức tạp.Đề xuất cách tổ chức lại (nếu cần):Để cải thiện cấu trúc, có thể mở rộng Hồi 1 bằng cách mô tả chi tiết hơn về cuộc sống của anh tiều phu và những khó khăn mà anh phải đối mặt. Hồi 2A/2B có thể được làm phong phú hơn bằng cách thêm các tình tiết phụ, ví dụ như anh tiều phu gặp những người khác trong rừng và họ khuyên anh nên nhận chiếc rìu bạc/vàng. Hồi 3 có thể được kéo dài bằng cách mô tả chi tiết hơn về cuộc sống mới của anh tiều phu sau khi được ban thưởng, và cách anh sử dụng sự giàu có của mình để giúp đỡ người khác. Tuy nhiên, cần lưu ý rằng việc thay đổi cấu trúc có thể ảnh hưởng đến thông điệp đơn giản và trực tiếp của câu chuyện.\",\"beatsheet\":\"Tuyệt vời! Dưới đây là BEAT SHEET chi tiết cho truyện \\\"Ba Lưỡi Rìu\\\", bám sát nội dung gốc và tuân thủ cấu trúc Save the Cat.📋 BEAT SHEET CHI TIẾTBEAT 1: OPENING IMAGE (Trang 1)Mục đích: Thiết lập tone nghèo khó, cuộc sống mưu sinh vất vả của nhân vật chính.Nội dung: Anh tiều phu vác rìu vào rừng đốn củi để kiếm sống.Liên kết với Final Image: Cuộc sống nghèo khó đối lập với cuộc sống sung túc sau này.BEAT 2: THEME STATED (Trang 5)Mục đích: Thể hiện chủ đề về sự trung thực và lòng tham.Nội dung: Ông cụ khen anh tiều phu \\\"Con quả là người thật thà và trung thực, không hề ham tiền bạc và lợi lộc.\\\"Chủ đề được ngụ ý: Trung thực và lòng tốt quan trọng hơn vật chất.BEAT 3: SETUP (Trang 1-10)Mục đích: Giới thiệu nhân vật, hoàn cảnh, và vấn đề.Nội dung:Anh tiều phu mồ côi, nghèo khó, sống bằng nghề đốn củi.Tài sản duy nhất là chiếc rìu sắt.Tính cách thật thà, chất phác.\\\"Save the Cat\\\" moment: Không có hành động cụ thể nào thể hiện sự đáng yêu, nhưng việc chăm chỉ làm việc để kiếm sống có thể xem là một dạng \\\"Save the Cat\\\".BEAT 4: CATALYST (Trang 1)Mục đích: Sự kiện làm thay đổi cuộc sống của nhân vật.Nội dung: Chiếc rìu bị gãy cán và lưỡi rìu văng xuống sông.Tại sao nhân vật không thể bỏ qua: Mất đi công cụ kiếm sống duy nhất.BEAT 5: DEBATE (Trang 12-25)Mục đích: Nhân vật do dự, cân nhắc về tình huống.Nội dung: Anh tiều phu ngồi khóc than, không biết làm gì để kiếm sống. (Lưỡng lự giữa việc chấp nhận số phận và tìm kiếm sự giúp đỡ).Nội tâm nhân vật: Tuyệt vọng, lo lắng, buồn bã.BEAT 6: BREAK INTO TWO (Trang 25)Mục đích: Nhân vật quyết định hành động.Nội dung: Ông cụ xuất hiện và đề nghị giúp anh tìm lại rìu. (Sự xuất hiện của ông cụ là yếu tố bên ngoài thúc đẩy nhân vật bước vào một hành trình mới).Đây là điểm không thể quay lại vì: Anh tiều phu bắt đầu dựa vào sự giúp đỡ từ bên ngoài, thay đổi hoàn toàn cục diện.BEAT 7: B STORY (Trang 30)Mục đích: Giới thiệu tuyến phụ, thể hiện chủ đề.Nội dung: Mối quan hệ giữa anh tiều phu và ông cụ.Cách B-story phản ánh chủ đề: Sự giúp đỡ của ông cụ thể hiện lòng tốt và sự đền đáp cho người trung thực.BEAT 8: FUN AND GAMES (Trang 30-55)Mục đích: \\\"Promise of the premise\\\" - thử thách lòng trung thực.Nội dung:Ông cụ lặn xuống sông, mang lên rìu bạc.Anh tiều phu từ chối.Ông cụ lặn xuống sông, mang lên rìu vàng.Anh tiều phu từ chối.Nhân vật đang học/làm gì: Thể hiện sự trung thực, không ham của cải.BEAT 9: MIDPOINT (Trang 55)Mục đích: False Victory hoặc False Defeat + RevelationLoại: False Victory (Có cơ hội đổi đời nhưng từ chối)Nội dung: Anh tiều phu từ chối rìu bạc.Revelation/Stakes mới: Sự trung thực quan trọng hơn vật chất, thử thách lòng tham.Tại sao đây là điểm không thể quay lại: Anh đã chứng minh sự trung thực của mình, không còn cơ hội để thay đổi quyết định.BEAT 10: BAD GUYS CLOSE IN (Trang 55-75)Mục đích: Áp lực từ bên ngoài và bên trong tăng cao.Áp lực bên ngoài: Sự nghèo khó vẫn còn đè nặng.Áp lực bên trong: Cám dỗ của sự giàu có từ chiếc rìu vàng.Có thể có sự nghi ngờ bản thân \\\"Liệu mình có nên nhận chiếc rìu vàng không?\\\".BEAT 11: ALL IS LOST (Trang 75)Mục đích: Điểm thấp nhất, \\\"whiff of death\\\".Nội dung: Anh tiều phu từ chối rìu vàng, vẫn phải đối mặt với cuộc sống nghèo khó.Mất mát: Cơ hội đổi đời.Tại sao nhân vật tưởng như hết hy vọng: Anh vẫn nghèo, không có rìu để kiếm sống.BEAT 12: DARK NIGHT OF THE SOUL (Trang 75-85)Mục đích: Nhân vật đối mặt với bản thân, với Lie.Nội dung: Anh tiều phu suy nghĩ về sự lựa chọn của mình, có thể hối tiếc nhưng vẫn tin vào sự trung thực.Nhận ra điều gì: Sự trung thực là giá trị quan trọng nhất.BEAT 13: BREAK INTO THREE (Trang 85)Mục đích: Tìm ra giải pháp, kết hợp A + B story.Nội dung: Ông cụ tiếp tục giúp đỡ.Cách B-story giúp tìm ra giải pháp: Sự giúp đỡ của ông cụ (B-story) là yếu tố quyết định giúp anh tiều phu vượt qua khó khăn (A-story).BEAT 14: FINALE (Trang 85-110)Mục đích: Thực hiện kế hoạch, đối đầu cuối cùng.Gathering the team: Không có team, chỉ có anh và ông cụ.Executing the plan: Ông cụ lặn xuống lấy rìu sắt.High Tower Surprise: Ông cụ tiết lộ mình là bụt và ban thưởng.Dig Deep Down: Anh tiều phu thể hiện sự trung thực, không tham lam.Victory/Defeat: Anh tiều phu được ban thưởng, cuộc sống thay đổi.BEAT 15: FINAL IMAGE (Trang 110)Mục đích: Hình ảnh đối lập với Opening, chứng minh sự thay đổi.Nội dung: Anh tiều phu giàu có hơn, nhưng vẫn giữ sự trung thực và lòng tốt.Đối lập với Opening như thế nào: Từ nghèo khó thành sung túc, nhưng vẫn giữ phẩm chất tốt đẹp.🔗 SƠ ĐỒ LIÊN KẾT CÁC BEATChiếc rìu rơi xuống sông (Catalyst) khiến anh tiều phu tuyệt vọng (Debate). Ông cụ xuất hiện (Break into Two) và bắt đầu thử thách lòng trung thực của anh (Fun and Games). Việc từ chối rìu bạc/vàng (Midpoint, All is Lost) dẫn đến khoảnh khắc suy ngẫm (Dark Night of the Soul). Cuối cùng, anh được đền đáp (Finale) và có cuộc sống tốt đẹp hơn (Final Image). Các beat liên kết chặt chẽ với nhau theo logic nhân quả, thúc đẩy câu chuyện tiến lên và thể hiện chủ đề.Ghi chú: Truyện thiếu một số yếu tố thường thấy trong cấu trúc Save the Cat, như một \\\"Save the Cat\\\" moment rõ ràng và áp lực từ \\\"bad guys\\\" (ngoài sự nghèo khó). Tuy nhiên, các beat chính vẫn được giữ nguyên và liên kết chặt chẽ với nhau.\"}', '<h2>🎬 DANH SÁCH CẢNH</h2></p><p><h3>HỒI 1: SETUP</h3></p><p>Cảnh 1: NGOẠI. RỪNG - SÁNG. Anh tiều phu trẻ tuổi, quần áo sờn rách, vác chiếc rìu cũ kỹ đi vào rừng.<br>Cảnh 2: NGOẠI. RỪNG - SÁNG. Anh tiều phu vung rìu đốn củi, mồ hôi nhễ nhại dưới ánh nắng gay gắt.<br>Cảnh 3: NỘI. NHÀ - TỐI. Anh tiều phu ngồi ăn bữa cơm đạm bạc một mình trong căn nhà tranh xơ xác.<br>Cảnh 4: NGOẠI. RỪNG - SÁNG. Anh tiều phu tiếp tục đốn củi, vẻ mặt mệt mỏi và chán nản.<br>Cảnh 5: NGOẠI. BỜ SÔNG - TRƯA. Trong lúc đốn củi gần bờ sông, lưỡi rìu của anh bị gãy và văng xuống nước.<br>Cảnh 6: NGOẠI. BỜ SÔNG - TRƯA. Anh tiều phu tuyệt vọng ngồi bên bờ sông, khóc than cho số phận hẩm hiu.<br>Cảnh 7: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu vẫn ngồi thẫn thờ bên bờ sông, không biết phải làm gì để kiếm sống.</p><p><h3>HỒI 2A: RESPONSE</h3></p><p>Cảnh 8: NGOẠI. BỜ SÔNG - CHIỀU. Một ông cụ tóc bạc phơ, dáng vẻ hiền từ xuất hiện trước mặt anh tiều phu.<br>Cảnh 9: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ hỏi han và biết được câu chuyện của anh tiều phu.<br>Cảnh 10: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ đề nghị giúp anh tiều phu tìm lại chiếc rìu bị mất.<br>Cảnh 11: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ lặn xuống sông, anh tiều phu hồi hộp chờ đợi trên bờ.<br>Cảnh 12: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ ngoi lên, tay cầm một chiếc rìu bằng bạc sáng loáng.<br>Cảnh 13: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu nhìn chiếc rìu bạc, lắc đầu từ chối vì đó không phải là của mình.<br>Cảnh 14: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ khen ngợi sự trung thực của anh tiều phu.<br>Cảnh 15: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu cảm thấy xấu hổ khi được khen ngợi.</p><p><h3>HỒI 2B: ACTION</h3></p><p>Cảnh 16: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ tiếp tục lặn xuống sông lần thứ hai.<br>Cảnh 17: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu lo lắng, tự hỏi liệu có nên nhận chiếc rìu nếu nó quá đẹp.<br>Cảnh 18: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ ngoi lên, tay cầm một chiếc rìu bằng vàng rực rỡ.<br>Cảnh 19: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu kinh ngạc nhìn chiếc rìu vàng, nhưng vẫn kiên quyết từ chối.<br>Cảnh 20: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ hỏi lại anh tiều phu một lần nữa để chắc chắn.<br>Cảnh 21: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu khẳng định chiếc rìu của mình chỉ là một chiếc rìu sắt bình thường.<br>Cảnh 22: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ mỉm cười hài lòng trước sự trung thực của anh tiều phu.<br>Cảnh 23: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu nhìn xuống dòng sông, lo lắng về tương lai.</p><p><h3>HỒI 3: CLIMAX</h3></p><p>Cảnh 24: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ lặn xuống sông lần thứ ba.<br>Cảnh 25: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu chờ đợi trong hồi hộp, hy vọng ông cụ sẽ tìm thấy chiếc rìu sắt của mình.<br>Cảnh 26: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ ngoi lên, tay cầm chiếc rìu sắt cũ kỹ của anh tiều phu.<br>Cảnh 27: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu mừng rỡ nhận lại chiếc rìu của mình.<br>Cảnh 28: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ khen ngợi sự trung thực và lòng tốt của anh tiều phu.<br>Cảnh 29: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ tiết lộ mình là một vị thần.<br>Cảnh 30: NGOẠI. BỜ SÔNG - CHIỀU. Ông cụ ban thưởng cho anh tiều phu hai chiếc rìu bằng vàng và bạc.<br>Cảnh 31: NGOẠI. BỜ SÔNG - CHIỀU. Anh tiều phu vô cùng biết ơn và hứa sẽ sử dụng những món quà này một cách khôn ngoan.<br>Cảnh 32: NGOẠI. RỪNG - CHIỀU. Anh tiều phu vác rìu vàng và bạc trở về nhà, lòng tràn ngập niềm vui.<br>Cảnh 33: NỘI. NHÀ - TỐI. Anh tiều phu ngắm nhìn hai chiếc rìu quý giá trong căn nhà tranh của mình.<br>Cảnh 34: NGOẠI. RỪNG - SÁNG. Anh tiều phu đốn củi bằng chiếc rìu vàng, cuộc sống đã thay đổi.<br>Cảnh 35: NGOẠI. LÀNG - NGÀY. Anh tiều phu giúp đỡ những người nghèo khó trong làng bằng số tiền kiếm được từ rìu vàng và bạc.<br>Cảnh 36: NỘI. NHÀ - TỐI. Anh tiều phu ngồi suy ngẫm về sự trung thực và lòng tốt, những tài sản quý giá nhất.<br>Cảnh 37: NGOẠI. RỪNG - SÁNG. Anh tiều phu tiếp tục đốn củi, nhưng giờ đây anh làm việc với niềm vui và lòng biết ơn.<br>Cảnh 38: NGOẠI. BỜ SÔNG - NGÀY. Anh tiều phu nhìn xuống dòng sông, nhớ lại bài học về sự trung thực mà ông cụ đã dạy cho anh.<br>Cảnh 39: NGOẠI. LÀNG - NGÀY. Anh tiều phu sống một cuộc sống hạnh phúc và ý nghĩa, luôn sẵn lòng giúp đỡ những người gặp khó khăn.<br>', '2026-02-28 16:22:14');
INSERT INTO `scenelists` (`id`, `project_id`, `type`, `input_data`, `output_data`, `created_at`) VALUES
(6, 19, 'screenplay', '{\"synopsis\":\"SYNOPSISMỞ ĐẦUTrong thành phố New York đổ nát sau đại dịch, Dr. Emma Taylor, một nhà khoa học tài năng nhưng cô độc, sống trong một phòng thí nghiệm ẩn mình. Emma bị ám ảnh bởi cái chết của gia đình mình trong đợt bùng phát đầu tiên, tin rằng chỉ có khoa học mới có thể cứu rỗi thế giới. Cô dành toàn bộ thời gian để nghiên cứu, tìm kiếm phương thuốc chữa trị căn bệnh đang biến con người thành những sinh vật đột biến khát máu. Emma tin rằng sự kết nối với người khác là một sự yếu đuối, và cô phải tự mình làm điều này.Một đêm, khi Emma đang tiến hành thí nghiệm quan trọng, phòng thí nghiệm của cô bị tấn công bởi một nhóm đột biến. Cô may mắn trốn thoát, nhưng mẫu virus gốc mà cô thu thập được cũng bị đánh cắp. Sự kiện này (Inciting Incident) buộc Emma phải rời khỏi nơi ẩn náu an toàn của mình và dấn thân vào một cuộc hành trình nguy hiểm để lấy lại mẫu virus và tiếp tục nghiên cứu.PHÁT TRIỂNEmma lần theo dấu vết của bọn đột biến, dẫn cô đến một khu vực bị tàn phá nặng nề của thành phố. Tại đây, cô gặp Marco, một cựu cảnh sát sống sót, người ban đầu hoài nghi nhưng sau đó đồng ý giúp đỡ Emma sau khi chứng kiến sự quyết tâm của cô. Marco cung cấp cho Emma sự bảo vệ và những kỹ năng sinh tồn cần thiết để đối phó với thế giới bên ngoài.Trong hành trình của mình, Emma và Marco chạm trán với Liam, một cựu bác sĩ quân y giàu kinh nghiệm. Liam nhận ra tiềm năng trong nghiên cứu của Emma và cung cấp cho cô những kiến thức y học quý giá. Ông cũng khuyên Emma nên mở lòng và tin tưởng người khác. Cả ba tiếp tục hành trình, đối mặt với những thử thách ngày càng leo thang, từ những cuộc chạm trán với đột biến đến những cuộc đụng độ với các băng đảng tranh giành quyền lực.Điểm giữa (Midpoint) xảy ra khi Emma, Marco và Liam tìm thấy một phòng thí nghiệm bỏ hoang khác. Tại đây, họ phát hiện ra rằng Kai, thủ lĩnh của nhóm săn lùng đột biến, không chỉ muốn virus để thống trị mà còn đang tiến hành những thí nghiệm tàn bạo trên người sống sót để tạo ra một loại siêu đột biến. Emma nhận ra rằng cô không chỉ phải tìm ra phương thuốc mà còn phải ngăn chặn Kai.CAO TRÀOKhi Emma và nhóm của mình cố gắng xâm nhập vào căn cứ của Kai để lấy lại virus và ngăn chặn thí nghiệm, họ bị phục kích. Marco hy sinh thân mình để giúp Emma và Liam trốn thoát (All Is Lost). Cái chết của Marco khiến Emma đau khổ và dằn vặt. Cô cảm thấy có lỗi vì đã không tin tưởng và kết nối với anh sớm hơn.Liam, nhận thấy Emma đang mất tinh thần, đã nhắc nhở cô về lý do cô bắt đầu hành trình này và tầm quan trọng của hy vọng. Ông kể cho Emma nghe về quá khứ của mình, về những mất mát mà ông đã trải qua, và về cách ông vẫn giữ được lòng trắc ẩn trong một thế giới tàn khốc. Emma nhận ra rằng cô không đơn độc và rằng sức mạnh thực sự nằm ở sự kết nối với người khác.Emma quyết định đối mặt với Kai. Cô tập hợp những người sống sót khác, bao gồm cả Chloe, một kỹ sư cơ khí tài năng mà cô đã gặp trước đó, và lên kế hoạch tấn công căn cứ của Kai. Trong trận chiến cuối cùng (Climax), Emma sử dụng kiến thức khoa học của mình để chống lại Kai và những đột biến của hắn.KẾT THÚCEmma đối đầu trực tiếp với Kai. Trong cuộc chiến, Kai chế nhạo Emma vì sự yếu đuối và lòng trắc ẩn của cô. Emma đáp trả bằng cách cho Kai thấy rằng chính sự tin tưởng và sự đoàn kết của cô với những người khác đã giúp cô mạnh mẽ hơn. Emma đánh bại Kai và phá hủy phòng thí nghiệm của hắn, ngăn chặn âm mưu tạo ra siêu đột biến.Sau trận chiến, Emma và những người sống sót bắt đầu xây dựng lại cộng đồng của mình. Emma tiếp tục nghiên cứu phương thuốc chữa trị, nhưng lần này, cô không còn đơn độc. Cô hợp tác với Chloe, Liam và những người khác, chia sẻ kiến thức và kinh nghiệm của mình. Emma đã học được rằng hy vọng và sự kiên trì của con người có thể chiến thắng nghịch cảnh, và rằng sức mạnh thực sự nằm ở sự kết nối và lòng trắc ẩn.CÁC ĐIỂM NGOẶT QUAN TRỌNGInciting Incident: Phòng thí nghiệm của Emma bị tấn công và mẫu virus gốc bị đánh cắp, buộc cô phải rời khỏi nơi ẩn náu và dấn thân vào cuộc hành trình nguy hiểm.Plot Point 1: Emma gặp Marco, người trở thành đồng minh và bảo vệ cô, đánh dấu sự khởi đầu của việc cô học cách tin tưởng người khác.Midpoint: Emma phát hiện ra âm mưu của Kai về việc tạo ra siêu đột biến, nâng cao stakes và thay đổi mục tiêu của cô từ chỉ tìm phương thuốc sang ngăn chặn một mối đe dọa lớn hơn.Plot Point 2: Marco hy sinh thân mình để cứu Emma và Liam, khiến Emma đau khổ và buộc cô phải đối mặt với sự thật rằng cô cần sự giúp đỡ của người khác.Climax: Emma đối đầu với Kai trong trận chiến cuối cùng, sử dụng kiến thức khoa học và sự đoàn kết của mình để đánh bại hắn.\",\"characters\":\"NHÂN VẬT CHÍNHDR. EMMA TAYLORTuổi/Nghề nghiệp: 35, Nhà khoa học (vi sinh vật học, dịch tễ học)Ngoại hình: Gầy gò, tóc búi cao, luôn mặc áo blouse trắng lấm bẩn, đôi mắt thâm quầng nhưng ánh lên sự thông minh và kiên định.Tính cách: Thông minh, quyết đoán, tận tụy, độc lập, có phần lạnh lùng và xa cách.Điểm yếu (Flaw): Khó tin tưởng người khác, quá dựa vào lý trí, xem nhẹ cảm xúc và sự kết nối.Backstory: Lớn lên trong một gia đình khoa học, bố mẹ đều là những nhà nghiên cứu nổi tiếng. Emma luôn cảm thấy áp lực phải chứng minh bản thân, dẫn đến việc cô tập trung cao độ vào học tập và nghiên cứu, bỏ qua các mối quan hệ cá nhân. Cô mất cả gia đình trong đợt bùng phát dịch bệnh đầu tiên, càng củng cố thêm niềm tin rằng chỉ có khoa học mới có thể cứu rỗi thế giới.Ghost/Wound: Mất gia đình và cảm giác tội lỗi vì không thể cứu họ. Cô luôn ám ảnh bởi việc dịch bệnh sẽ lặp lại và hủy diệt loài người.WANT (Muốn): Tìm ra phương thuốc chữa trị dịch bệnh và ngăn chặn sự tuyệt chủng của loài người.NEED (Cần): Học cách tin tưởng người khác, chấp nhận sự giúp đỡ và nhận ra rằng sức mạnh thực sự nằm ở sự kết nối và lòng trắc ẩn.Arc dự kiến: Từ một nhà khoa học đơn độc, lạnh lùng và chỉ tin vào lý trí → trở thành một người lãnh đạo biết tin tưởng, hợp tác và tìm thấy sức mạnh trong sự kết nối với cộng đồng.Vai trò trong chủ đề: Thể hiện sự kiên trì, hy vọng và sức mạnh của khoa học, nhưng đồng thời cũng cho thấy giới hạn của lý trí và tầm quan trọng của sự kết nối con người. Emma đại diện cho \\\"LIE\\\" ban đầu, tin rằng chỉ có khoa học và sự độc lập mới có thể cứu rỗi thế giới, nhưng dần dần học được \\\"TRUTH\\\" thông qua hành trình của mình.NHÂN VẬT PHẢN DIỆNKAITuổi/Nghề nghiệp: 40, Thủ lĩnh nhóm săn lùng đột biến.Ngoại hình: To lớn, cơ bắp, nhiều sẹo trên mặt và cơ thể. Ánh mắt hung dữ, tàn nhẫn.Tính cách: Tàn bạo, ích kỷ, chỉ quan tâm đến sự sống còn của bản thân và nhóm của mình. Mất niềm tin vào nhân loại.Điểm yếu (Flaw): Mù quáng tin vào sức mạnh, không tin tưởng ai, sợ hãi sự yếu đuối.Backstory: Từng là một người lính cứu hỏa dũng cảm, nhưng sau khi chứng kiến sự sụp đổ của xã hội và sự tàn bạo của dịch bệnh, Kai trở nên mất niềm tin vào nhân loại. Anh ta tin rằng chỉ có sức mạnh và sự tàn nhẫn mới có thể giúp con người sống sót.Ghost/Wound: Chứng kiến quá nhiều cái chết và sự tàn phá, mất niềm tin vào lòng tốt của con người.WANT (Muốn): Thống trị những người sống sót còn lại, đảm bảo sự sống còn của nhóm mình bằng mọi giá.NEED (Cần): Đối mặt với nỗi sợ hãi của bản thân, nhận ra rằng sự tàn bạo không phải là giải pháp, và tìm lại chút lòng trắc ẩn còn sót lại.Arc dự kiến: Không thay đổi. Kai củng cố niềm tin sai lầm của mình cho đến khi bị đánh bại, thể hiện sự bế tắc của việc chỉ tin vào sức mạnh và sự tàn nhẫn.Vai trò trong chủ đề: Kai là GƯƠNG PHẢN CHIẾU của Emma, thể hiện một con đường khác khi đối mặt với sự tuyệt vọng. Anh ta đại diện cho sự tha hóa của con người khi mất đi hy vọng và lòng trắc ẩn. Kai cho thấy điều gì sẽ xảy ra nếu Emma không học được bài học về sự kết nối và lòng tin.NHÂN VẬT PHỤLIAM - Mentor/Người bạnTuổi/Nghề nghiệp: 50, cựu bác sĩ quân y.Mô tả: Một người đàn ông lớn tuổi, từng trải, thông minh và giàu kinh nghiệm. Liam trở thành người cố vấn cho Emma, giúp cô nhìn nhận vấn đề từ nhiều góc độ khác nhau và đưa ra những lời khuyên quý giá. Anh đại diện cho lòng trắc ẩn và sự hy sinh.CHLOE - Love Interest/Người đồng hànhTuổi/Nghề nghiệp: 25, kỹ sư cơ khí.Mô tả: Một cô gái trẻ mạnh mẽ, thông minh và lạc quan. Chloe giúp Emma sửa chữa các thiết bị, cung cấp hỗ trợ kỹ thuật và mang đến một tia hy vọng trong thế giới tăm tối. Cô đại diện cho sức mạnh của tuổi trẻ và sự kiên cường.MARCO - Người bảo vệ/Bạn đồng hành bất đắc dĩTuổi/Nghề nghiệp: 30, cựu cảnh sát.Mô tả: Một người đàn ông mạnh mẽ, giỏi chiến đấu và có kỹ năng sinh tồn tốt. Marco ban đầu hoài nghi về Emma, nhưng dần dần tin tưởng vào cô và trở thành người bảo vệ trung thành của cô. Anh đại diện cho sự tin tưởng và lòng trung thành.SƠ ĐỒ MỐI QUAN HỆEmma - Kai: Đối địch. Kai truy đuổi Emma để chiếm đoạt phương thuốc (hoặc giết cô để loại bỏ mối đe dọa). Họ là hai thái cực đối lập trong cách đối mặt với dịch bệnh và sự tuyệt vọng.Emma - Liam: Quan hệ thầy trò, bạn bè. Liam là người cố vấn, giúp Emma vượt qua khó khăn và học cách tin tưởng người khác.Emma - Chloe: Quan hệ tình cảm, đồng đội. Chloe mang đến sự lạc quan và hỗ trợ kỹ thuật cho Emma.Emma - Marco: Quan hệ từ hoài nghi đến tin tưởng, đồng đội. Marco bảo vệ Emma và giúp cô đối mặt với nguy hiểm.\",\"structure\":\"CẤU TRÚC 4 HỒIHỒI 1: SETUP (Trang 1-25, khoảng 25 phút)Mục tiêu hồi này: Giới thiệu thế giới hậu tận thế, Dr. Emma Taylor và nỗi ám ảnh của cô, thiết lập vấn đề và thúc đẩy cô vào hành trình.Mở đầu với hình ảnh New York đổ nát, nhưng đầy rẫy nguy hiểm. Dr. Emma Taylor, một nhà khoa học tài năng nhưng cô độc, sống trong phòng thí nghiệm ẩn mình. Cô làm việc không ngừng nghỉ, bị ám ảnh bởi cái chết của gia đình trong đợt dịch trước. Emma tin rằng chỉ khoa học mới có thể cứu rỗi thế giới, và sự kết nối với người khác là một sự yếu đuối. Chúng ta thấy Emma trong cuộc sống thường ngày: thí nghiệm, đọc sách, sống khép kín. Cô luôn mặc áo blouse trắng lấm bẩn, đôi mắt thâm quầng nhưng ánh lên sự thông minh và kiên định. Catalyst xảy ra khi phòng thí nghiệm của Emma bị tấn công bởi một nhóm đột biến. Cô may mắn trốn thoát, nhưng mẫu virus gốc bị đánh cắp. Sau sự kiện này, Emma do dự. Cô có nên rời khỏi nơi an toàn của mình không? Liệu cô có thể tin tưởng ai không? Nhưng nỗi ám ảnh về việc tìm ra phương thuốc và ngăn chặn dịch bệnh lặp lại đã thúc đẩy cô quyết định dấn thân vào hành trình nguy hiểm để lấy lại mẫu virus.Các điểm ngoặt quan trọng:Opening Image (Trang 1): New York đổ nát, phòng thí nghiệm ẩn mình của Emma.Catalyst (Trang 12): Phòng thí nghiệm bị tấn công, mẫu virus bị đánh cắp.Break into Two (Trang 25): Emma quyết định rời khỏi nơi ẩn náu để lấy lại virus.HỒI 2A: RESPONSE (Trang 25-55, khoảng 30 phút)Mục tiêu hồi này: Emma bắt đầu hành trình, gặp gỡ Marco và Liam, đối mặt với những thử thách ban đầu và thu thập thông tin quan trọng.Emma lần theo dấu vết của bọn đột biến, dẫn cô đến khu vực bị tàn phá nặng nề. Tại đây, cô gặp Marco, một cựu cảnh sát sống sót. Ban đầu Marco hoài nghi, nhưng sau khi chứng kiến sự quyết tâm của Emma, anh đồng ý giúp đỡ. Marco cung cấp cho Emma sự bảo vệ và kỹ năng sinh tồn cần thiết. Tuyến B-Story bắt đầu khi Marco kể về quá khứ của anh và lý do anh sống sót. Emma và Marco chạm trán với Liam, một cựu bác sĩ quân y giàu kinh nghiệm. Liam nhận ra tiềm năng trong nghiên cứu của Emma và cung cấp cho cô những kiến thức y học quý giá. Ông cũng khuyên Emma nên mở lòng và tin tưởng người khác. Cả ba tiếp tục hành trình, đối mặt với những thử thách ngày càng leo thang, từ những cuộc chạm trán với đột biến đến những cuộc đụng độ với các băng đảng tranh giành quyền lực. Midpoint xảy ra khi Emma, Marco và Liam tìm thấy một phòng thí nghiệm bỏ hoang khác. Tại đây, họ phát hiện ra rằng Kai, thủ lĩnh của nhóm săn lùng đột biến, không chỉ muốn virus để thống trị mà còn đang tiến hành những thí nghiệm tàn bạo trên người sống sót để tạo ra một loại siêu đột biến. Emma nhận ra rằng cô không chỉ phải tìm ra phương thuốc mà còn phải ngăn chặn Kai.Các điểm ngoặt quan trọng:B-Story Begins (Trang 30): Marco kể về quá khứ của mình.Midpoint (Trang 55): Phát hiện ra âm mưu của Kai về siêu đột biến.HỒI 2B: ACTION (Trang 55-85, khoảng 30 phút)Mục tiêu hồi này: Stakes tăng cao, Emma và nhóm của mình bị dồn vào thế khó, mất mát lớn nhất xảy ra, Emma đối mặt với nỗi đau và tìm ra động lực mới.Hậu quả từ Midpoint, Emma và nhóm của mình cố gắng xâm nhập vào căn cứ của Kai để lấy lại virus và ngăn chặn thí nghiệm. Họ bị phục kích. Marco hy sinh thân mình để giúp Emma và Liam trốn thoát (All Is Lost). Cái chết của Marco khiến Emma đau khổ và dằn vặt. Cô cảm thấy có lỗi vì đã không tin tưởng và kết nối với anh sớm hơn. Đây là Dark Night of the Soul của Emma. Cô mất niềm tin và cảm thấy tuyệt vọng. Liam, nhận thấy Emma đang mất tinh thần, đã nhắc nhở cô về lý do cô bắt đầu hành trình này và tầm quan trọng của hy vọng. Ông kể cho Emma nghe về quá khứ của mình, về những mất mát mà ông đã trải qua, và về cách ông vẫn giữ được lòng trắc ẩn trong một thế giới tàn khốc. Nhờ Liam, Emma nhận ra rằng cô không đơn độc và rằng sức mạnh thực sự nằm ở sự kết nối với người khác. Break into Three: Emma quyết định đối mặt với Kai.Các điểm ngoặt quan trọng:All Is Lost (Trang 75): Marco hy sinh.Dark Night of the Soul (Trang 75-85): Emma đau khổ và dằn vặt.Break into Three (Trang 85): Emma quyết định đối mặt với Kai.HỒI 3: CLIMAX (Trang 85-110, khoảng 25 phút)Mục tiêu hồi này: Emma đối đầu với Kai, sử dụng kiến thức và sự đoàn kết để chiến thắng, hoàn thành arc nhân vật và mang lại hy vọng cho tương lai.Emma tập hợp những người sống sót khác, bao gồm cả Chloe, một kỹ sư cơ khí tài năng mà cô đã gặp trước đó, và lên kế hoạch tấn công căn cứ của Kai. Trong trận chiến cuối cùng (Climax), Emma sử dụng kiến thức khoa học của mình để chống lại Kai và những đột biến của hắn. Emma đối đầu trực tiếp với Kai. Trong cuộc chiến, Kai chế nhạo Emma vì sự yếu đuối và lòng trắc ẩn của cô. Emma đáp trả bằng cách cho Kai thấy rằng chính sự tin tưởng và sự đoàn kết của cô với những người khác đã giúp cô mạnh mẽ hơn. Emma đánh bại Kai và phá hủy phòng thí nghiệm của hắn, ngăn chặn âm mưu tạo ra siêu đột biến. Sau trận chiến, Emma và những người sống sót bắt đầu xây dựng lại cộng đồng của mình. Emma tiếp tục nghiên cứu phương thuốc chữa trị, nhưng lần này, cô không còn đơn độc. Cô hợp tác với Chloe, Liam và những người khác, chia sẻ kiến thức và kinh nghiệm của mình. Final Image: Emma làm việc trong phòng thí nghiệm mới với Chloe và Liam, cùng nhau hướng về tương lai. Hình ảnh này đối lập với Opening Image: từ một nhà khoa học cô độc trong phòng thí nghiệm tăm tối đến một người lãnh đạo được bao quanh bởi những người đồng đội, cùng nhau xây dựng lại thế giới.Các điểm ngoặt quan trọng:Climax (Trang 100-105): Emma đối đầu với Kai.Final Image (Trang 110): Emma làm việc trong phòng thí nghiệm mới với đồng đội.TỔNG QUAN ARC NHÂN VẬT QUA 4 HỒIDr. Emma Taylor bắt đầu là một nhà khoa học cô độc, lạnh lùng và chỉ tin vào lý trí, bị ám ảnh bởi quá khứ và sợ hãi sự kết nối. Qua hành trình tìm kiếm phương thuốc và đối mặt với những mất mát, Emma dần học được giá trị của sự tin tưởng, lòng trắc ẩn và sức mạnh của cộng đồng. Cuối cùng, cô trở thành một người lãnh đạo biết tin tưởng, hợp tác và tìm thấy sức mạnh trong sự kết nối với những người khác, mang lại hy vọng cho tương lai.\",\"beatsheet\":\"BEAT SHEET CHI TIẾTBEAT 1: OPENING IMAGE (Trang 1)Mục đích: Thiết lập tone, mood hậu tận thế, giới thiệu trạng thái \\\"trước\\\" của Emma: cô độc, ám ảnh, chỉ tin vào khoa học.Nội dung: New York đổ nát sau đại dịch. Dr. Emma Taylor, trong phòng thí nghiệm ẩn mình, làm việc không ngừng nghỉ. Áo blouse trắng lấm bẩn, đôi mắt thâm quầng. Khung cảnh tối tăm, chỉ có ánh đèn phòng thí nghiệm chiếu sáng các dụng cụ khoa học. Cô đang cố gắng phân tích một mẫu virus.Liên kết với Final Image: Đối lập hoàn toàn: Emma không còn cô độc, làm việc trong phòng thí nghiệm sáng sủa với đồng đội, hướng tới tương lai.BEAT 2: THEME STATED (Trang 5)Mục đích: Ngụ ý về chủ đề: sự kết nối và lòng trắc ẩn quan trọng hơn sự cô lập và lý trí.Nội dung: Trong một đoạn hồi tưởng ngắn, bố của Emma nói: \\\"Khoa học có thể giải quyết nhiều vấn đề, nhưng chính sự đồng cảm và sự giúp đỡ lẫn nhau mới giúp chúng ta vượt qua khó khăn.\\\" (Đây là hồi tưởng, không phải hiện tại)Chủ đề được ngụ ý: Sự kết nối con người và lòng trắc ẩn là chìa khóa để sinh tồn và vượt qua nghịch cảnh, không chỉ là khoa học.BEAT 3: SETUP (Trang 1-10)Mục đích: Giới thiệu thế giới hậu tận thế, nhân vật Emma, điểm yếu, nỗi ám ảnh, stakes.Nội dung:Cuộc sống thường ngày của Emma: Thí nghiệm, đọc sách, sống khép kín trong phòng thí nghiệm. Cô luôn tự làm mọi thứ, không tin tưởng ai.Các mối quan hệ quan trọng: Không có mối quan hệ nào. Cô sống hoàn toàn một mình, tránh xa mọi người. Hồi tưởng ngắn về gia đình cô đã mất.Điểm yếu/vấn đề của nhân vật: Khó tin tưởng người khác, quá dựa vào lý trí, xem nhẹ cảm xúc và sự kết nối. Nỗi ám ảnh về việc tìm ra phương thuốc.\\\"Save the Cat\\\" moment: Emma chăm sóc một con chuột bạch bị thương trong phòng thí nghiệm, cho thấy chút lòng trắc ẩn ẩn sâu bên trong.BEAT 4: CATALYST (Trang 12)Mục đích: Sự kiện phá vỡ trạng thái cân bằng: phòng thí nghiệm bị tấn công, mẫu virus bị đánh cắp.Nội dung: Phòng thí nghiệm của Emma bị tấn công bởi một nhóm đột biến. Cô may mắn trốn thoát, nhưng mẫu virus gốc quan trọng bị đánh cắp.Tại sao nhân vật không thể bỏ qua: Mẫu virus là hy vọng duy nhất để tìm ra phương thuốc. Nếu nó rơi vào tay kẻ xấu, hậu quả sẽ khôn lường. Nỗi ám ảnh của cô trỗi dậy mạnh mẽ.BEAT 5: DEBATE (Trang 12-25)Mục đích: Emma do dự, cân nhắc việc rời khỏi nơi ẩn náu an toàn.Nội dung:Các lý do để đi: Phải lấy lại mẫu virus để cứu thế giới. Không thể để công sức của mình đổ sông đổ biển. Nỗi ám ảnh thúc đẩy cô.Các lý do để không đi: Thế giới bên ngoài quá nguy hiểm. Cô có thể chết. Cô không tin tưởng ai để giúp đỡ mình.Nội tâm nhân vật: Sợ hãi, lo lắng, nhưng nỗi ám ảnh và trách nhiệm lớn hơn tất cả. Hồi tưởng về cái chết của gia đình thúc đẩy cô hành động.BEAT 6: BREAK INTO TWO (Trang 25)Mục đích: Emma CHỌN hành động: rời khỏi phòng thí nghiệm để lấy lại mẫu virus.Nội dung: Emma thu thập những vật dụng cần thiết, chuẩn bị vũ khí tự chế và rời khỏi phòng thí nghiệm. Cô quyết định dấn thân vào cuộc hành trình nguy hiểm.Đây là điểm không thể quay lại vì: Một khi đã bước ra khỏi nơi ẩn náu, Emma sẽ phải đối mặt với vô vàn nguy hiểm. Cô không thể quay lại cuộc sống cô độc như trước.BEAT 7: B STORY (Trang 30)Mục đích: Giới thiệu Marco, người sẽ giúp Emma học cách tin tưởng người khác.Nội dung: Emma lần theo dấu vết bọn đột biến và gặp Marco, một cựu cảnh sát sống sót, trong một khu vực đổ nát. Ban đầu Marco hoài nghi, nhưng sau khi chứng kiến sự quyết tâm của Emma, anh đồng ý giúp đỡ. Marco kể về quá khứ của mình và lý do anh sống sót.Cách B-story phản ánh chủ đề: Marco là người từng mất mát nhiều, nhưng vẫn giữ được lòng tốt và sự tin tưởng vào con người. Anh đại diện cho sự kết nối và hy vọng mà Emma đang thiếu.BEAT 8: FUN AND GAMES (Trang 30-55)Mục đích: \\\"Promise of the premise\\\" - Emma và Marco hợp tác để tìm kiếm mẫu virus, đối mặt với những thử thách trong thế giới hậu tận thế.Nội dung:Cảnh fun 1: Emma sử dụng kiến thức khoa học để giải quyết các vấn đề, ví dụ như chế tạo một loại thuốc nổ tự chế để phá cửa.Cảnh fun 2: Marco dạy Emma cách tự vệ và chiến đấu với đột biến.Cảnh fun 3: Emma, Marco và Liam (người mà họ gặp sau đó) cùng nhau vượt qua một khu vực đầy rẫy cạm bẫy.Nhân vật đang học/làm gì: Emma học cách tin tưởng và hợp tác với người khác, Marco và Liam giúp Emma thích nghi với thế giới bên ngoài, cả ba cùng nhau thu thập thông tin về Kai và âm mưu của hắn.BEAT 9: MIDPOINT (Trang 55)Mục đích: False Discovery + Revelation: Emma phát hiện ra âm mưu của Kai về việc tạo ra siêu đột biến.Loại: False DiscoveryNội dung: Emma, Marco và Liam tìm thấy một phòng thí nghiệm bỏ hoang khác. Tại đây, họ phát hiện ra rằng Kai không chỉ muốn virus để thống trị mà còn đang tiến hành những thí nghiệm tàn bạo trên người sống sót để tạo ra một loại siêu đột biến.Revelation/Stakes mới: Emma nhận ra rằng cô không chỉ phải tìm ra phương thuốc mà còn phải ngăn chặn Kai và âm mưu tạo ra siêu đột biến, stakes tăng cao.Tại sao đây là điểm không thể quay lại: Mục tiêu của Emma đã thay đổi. Giờ đây, cô phải đối mặt với một mối đe dọa lớn hơn nhiều so với ban đầu.BEAT 10: BAD GUYS CLOSE IN (Trang 55-75)Mục đích: Áp lực từ bên ngoài (Kai truy đuổi) và bên trong (mâu thuẫn trong nhóm) tăng cao.Áp lực bên ngoài:Kai và nhóm của hắn truy đuổi Emma, Marco và Liam. Họ liên tục phải trốn chạy và chiến đấu.Các nguồn lực của Emma và nhóm ngày càng cạn kiệt.Áp lực bên trong (đội nhóm tan rã, nghi ngờ...):Emma và Marco có những bất đồng về cách tiếp cận vấn đề. Emma muốn dựa vào khoa học, còn Marco muốn sử dụng bạo lực.Emma cảm thấy có lỗi vì đã kéo Marco và Liam vào cuộc chiến này.BEAT 11: ALL IS LOST (Trang 75)Mục đích: Điểm thấp nhất: Marco hy sinh để cứu Emma và Liam.Nội dung: Trong một cuộc phục kích, Marco hy sinh thân mình để giúp Emma và Liam trốn thoát.Mất mát: Cái chết của Marco, người bạn đồng hành đầu tiên của Emma.Tại sao nhân vật tưởng như hết hy vọng: Emma cảm thấy có lỗi vì đã không tin tưởng và kết nối với Marco sớm hơn. Cô mất niềm tin vào bản thân và cảm thấy tuyệt vọng. Cô nghĩ rằng mình không thể làm được gì cả.BEAT 12: DARK NIGHT OF THE SOUL (Trang 75-85)Mục đích: Emma đối mặt với nỗi đau, sự mất mát và sự cô đơn.Nội dung: Emma ngồi một mình trong bóng tối, dằn vặt vì cái chết của Marco. Cô hồi tưởng lại những khoảnh khắc bên anh và nhận ra rằng anh đã dạy cho cô rất nhiều điều về sự tin tưởng và lòng trắc ẩn.Nhận ra điều gì: Emma nhận ra rằng cô không đơn độc và rằng sức mạnh thực sự nằm ở sự kết nối với người khác. Cô bắt đầu hiểu được tầm quan trọng của những điều mà Marco và Liam đã cố gắng dạy cô. Manh mối về Truth: cô cần sự giúp đỡ của người khác để thành công.BEAT 13: BREAK INTO THREE (Trang 85)Mục đích: Emma tìm ra giải pháp: đối mặt với Kai và hợp tác với những người sống sót khác.Nội dung: Liam, nhận thấy Emma đang mất tinh thần, đã nhắc nhở cô về lý do cô bắt đầu hành trình này và tầm quan trọng của hy vọng. Ông kể cho Emma nghe về quá khứ của mình và về cách ông vẫn giữ được lòng trắc ẩn trong một thế giới tàn khốc. Emma quyết định đối mặt với Kai và tập hợp những người sống sót khác để chống lại hắn.Cách B-story giúp tìm ra giải pháp: Nhờ Marco (B-story), Emma đã học được cách tin tưởng và kết nối với người khác. Điều này giúp cô có đủ dũng khí để đối mặt với Kai và tập hợp những người sống sót.BEAT 14: FINALE (Trang 85-110)Mục đích: Emma đối đầu với Kai, sử dụng kiến thức và sự đoàn kết để chiến thắng.5 bước của Finale:Gathering the team: Emma tập hợp những người sống sót khác, bao gồm cả Chloe, một kỹ sư cơ khí tài năng.Executing the plan: Emma và nhóm của mình lên kế hoạch tấn công căn cứ của Kai.High Tower Surprise: Kai đã chuẩn bị một loại siêu đột biến mạnh hơn nhiều so với dự kiến.Dig Deep Down: Emma sử dụng kiến thức khoa học và sự tin tưởng vào đồng đội để tìm ra cách đánh bại siêu đột biến. Cô nhớ lại lời của Marco về việc luôn tin vào những điều tốt đẹp.Victory: Emma đánh bại Kai và phá hủy phòng thí nghiệm của hắn, ngăn chặn âm mưu tạo ra siêu đột biến.BEAT 15: FINAL IMAGE (Trang 110)Mục đích: Thể hiện sự thay đổi của Emma.Nội dung: Emma làm việc trong phòng thí nghiệm mới với Chloe và Liam, cùng nhau nghiên cứu phương thuốc chữa trị. Cô mỉm cười, ánh mắt tràn đầy hy vọng.Đối lập với Opening như thế nào: Từ một nhà khoa học cô độc trong phòng thí nghiệm tăm tối, Emma trở thành một người lãnh đạo được bao quanh bởi những người đồng đội, cùng nhau xây dựng lại thế giới. Cô không còn cô độc và sợ hãi nữa, mà đã tìm thấy sức mạnh trong sự kết nối và lòng trắc ẩn.SƠ ĐỒ LIÊN KẾT CÁC BEATOpening Image thiết lập trạng thái cô độc của Emma, Catalyst (phòng thí nghiệm bị tấn công) buộc cô phải hành động. Debate thể hiện sự do dự của Emma, nhưng nỗi ám ảnh và trách nhiệm đã thúc đẩy cô Break into Two (rời khỏi phòng thí nghiệm). B Story (Marco) giúp Emma học cách tin tưởng, Fun and Games thể hiện quá trình hợp tác và đối mặt với thử thách. Midpoint (phát hiện âm mưu của Kai) tăng stakes. Bad Guys Close In dồn Emma vào thế khó, All is Lost (cái chết của Marco) đẩy cô xuống vực sâu tuyệt vọng. Dark Night of the Soul giúp Emma nhận ra giá trị của sự kết nối, Break into Three (quyết định đối mặt với Kai) thúc đẩy cô hành động. Finale (đối đầu với Kai) là đỉnh điểm của sự thay đổi, Final Image thể hiện Emma đã trở thành một con người khác, không còn cô độc mà tràn đầy hy vọng.\"}', '<h2>DANH SÁCH CẢNH</h2></p><p><h3>HỒI 1: SETUP:</h3></p><p>Cảnh 1: New York đổ nát, Dr. Emma Taylor làm việc trong phòng thí nghiệm ẩn mình, cố gắng phân tích mẫu virus trong ánh đèn vàng vọt (OPENING IMAGE).<br>Cảnh 2: Emma hồi tưởng lại lời người bố về tầm quan trọng của sự đồng cảm, gợi ý chủ đề chính của phim (THEME STATED).<br>Cảnh 3: Emma làm thí nghiệm một mình, từ chối liên lạc từ bên ngoài, thể hiện sự cô lập và ám ảnh (SETUP).<br>Cảnh 4: Hồi tưởng về cái chết của gia đình Emma trong đợt dịch bệnh đầu tiên, củng cố động cơ và nỗi sợ hãi của cô (SETUP).<br>Cảnh 5: Emma chăm sóc con chuột bạch bị thương trong phòng thí nghiệm, hé lộ lòng trắc ẩn ẩn sâu bên trong (SAVE THE CAT).<br>Cảnh 6: Phòng thí nghiệm của Emma bị tấn công bất ngờ bởi nhóm đột biến, mẫu virus gốc bị đánh cắp (CATALYST).<br>Cảnh 7: Emma bị thương nhẹ và trốn thoát khỏi phòng thí nghiệm, chứng kiến những con đột biến lục soát và phá hủy mọi thứ.<br>Cảnh 8: Emma do dự, cân nhắc việc rời khỏi nơi ẩn náu an toàn, đấu tranh giữa nỗi sợ hãi và trách nhiệm (DEBATE).<br>Cảnh 9: Emma nhớ lại những nỗ lực cứu chữa người bệnh bất thành của mình, thôi thúc cô phải tìm ra phương thuốc bằng mọi giá.<br>Cảnh 10: Emma thu thập những vật dụng cần thiết, kiểm tra khẩu súng tự chế và chuẩn bị cho hành trình nguy hiểm (BREAK INTO TWO).<br>Cảnh 11: Emma khóa cửa phòng thí nghiệm, nhìn lại lần cuối trước khi bước vào thế giới bên ngoài đầy rẫy nguy hiểm.</p><p><h3>HỒI 2A: RESPONSE:</h3></p><p>Cảnh 12: Emma lần theo dấu vết bọn đột biến đến một khu chợ bỏ hoang, nơi cô chạm trán với những kẻ cướp bóc.<br>Cảnh 13: Emma bị tấn công bởi một nhóm cướp, nhưng Marco, một cựu cảnh sát, xuất hiện và giải cứu cô.<br>Cảnh 14: Marco ban đầu hoài nghi về Emma, nhưng sau khi chứng kiến sự quyết tâm của cô, anh đồng ý giúp đỡ (B STORY BEGINS).<br>Cảnh 15: Marco kể về quá khứ của mình, về gia đình anh đã mất và lý do anh sống sót trong thế giới này.<br>Cảnh 16: Emma và Marco hợp tác tìm kiếm thông tin về bọn đột biến, di chuyển qua những con phố đổ nát (FUN AND GAMES).<br>Cảnh 17: Emma sử dụng kiến thức khoa học để chế tạo thuốc nổ tự chế, giúp họ vượt qua một chướng ngại vật.<br>Cảnh 18: Marco dạy Emma cách tự vệ và chiến đấu với đột biến, biến cô thành một chiến binh bất đắc dĩ.<br>Cảnh 19: Emma và Marco chạm trán với Liam, một cựu bác sĩ quân y, người cung cấp cho họ những kiến thức y học quý giá.<br>Cảnh 20: Liam khuyên Emma nên mở lòng và tin tưởng người khác, nhưng Emma vẫn còn dè dặt.<br>Cảnh 21: Cả ba cùng nhau vượt qua một khu vực đầy rẫy cạm bẫy, thể hiện sự phối hợp và tin tưởng lẫn nhau.<br>Cảnh 22: Emma, Marco và Liam tìm thấy một phòng thí nghiệm bỏ hoang, nơi họ phát hiện ra âm mưu của Kai (MIDPOINT).<br>Cảnh 23: Họ phát hiện ra rằng Kai không chỉ muốn virus để thống trị mà còn đang tiến hành những thí nghiệm tàn bạo để tạo ra siêu đột biến.<br>Cảnh 24: Emma nhận ra rằng cô không chỉ phải tìm ra phương thuốc mà còn phải ngăn chặn Kai, stakes tăng cao.</p><p><h3>HỒI 2B: ACTION:</h3></p><p>Cảnh 25: Emma, Marco và Liam thảo luận kế hoạch xâm nhập vào căn cứ của Kai, nhưng gặp bất đồng về cách tiếp cận (BAD GUYS CLOSE IN).<br>Cảnh 26: Kai ra lệnh truy lùng Emma, Marco và Liam, khiến họ liên tục phải trốn chạy và chiến đấu.<br>Cảnh 27: Nhóm của Emma bị tấn công bởi một nhóm đột biến được trang bị vũ khí, nguồn lực của họ ngày càng cạn kiệt.<br>Cảnh 28: Emma và Marco tranh cãi về việc sử dụng bạo lực, Emma muốn dựa vào khoa học, còn Marco muốn trả thù.<br>Cảnh 29: Emma cảm thấy có lỗi vì đã kéo Marco và Liam vào cuộc chiến này, nghi ngờ khả năng của bản thân.<br>Cảnh 30: Trong một cuộc phục kích, Marco hy sinh thân mình để giúp Emma và Liam trốn thoát (ALL IS LOST).<br>Cảnh 31: Emma và Liam trốn thoát, chứng kiến Marco bị bọn đột biến bao vây và giết chết.<br>Cảnh 32: Emma ngồi một mình trong bóng tối, dằn vặt vì cái chết của Marco, cảm thấy mất niềm tin và tuyệt vọng (DARK NIGHT OF THE SOUL).<br>Cảnh 33: Emma hồi tưởng lại những khoảnh khắc bên Marco, nhận ra giá trị của sự tin tưởng và lòng trắc ẩn.<br>Cảnh 34: Liam an ủi Emma, nhắc nhở cô về lý do cô bắt đầu hành trình và tầm quan trọng của hy vọng.<br>Cảnh 35: Emma quyết định đối mặt với Kai, sử dụng những gì cô đã học được từ Marco và Liam (BREAK INTO THREE).</p><p><h3>HỒI 3: CLIMAX:</h3></p><p>Cảnh 36: Emma và Liam tìm đến một khu định cư của những người sống sót, nơi họ gặp Chloe, một kỹ sư cơ khí tài năng.<br>Cảnh 37: Emma, Liam và Chloe tập hợp những người sống sót khác, lên kế hoạch tấn công căn cứ của Kai (GATHERING THE TEAM).<br>Cảnh 38: Emma sử dụng kiến thức khoa học để chế tạo vũ khí và thiết bị hỗ trợ cho cuộc tấn công (EXECUTING THE PLAN).<br>Cảnh 39: Nhóm của Emma xâm nhập vào căn cứ của Kai, đối mặt với những cạm bẫy và đội quân đột biến.<br>Cảnh 40: Emma đối mặt với Kai, người đã tạo ra một loại siêu đột biến mạnh hơn nhiều so với dự kiến (HIGH TOWER SURPRISE).<br>Cảnh 41: Emma sử dụng kiến thức khoa học và sự tin tưởng vào đồng đội để tìm ra cách đánh bại siêu đột biến (DIG DEEP DOWN).<br>Cảnh 42: Emma nhớ lại lời của Marco về việc luôn tin vào những điều tốt đẹp, tìm thấy sức mạnh để chiến đấu.<br>Cảnh 43: Emma đánh bại Kai trong trận chiến cuối cùng, phá hủy phòng thí nghiệm của hắn và ngăn chặn âm mưu tạo ra siêu đột biến (VICTORY).<br>Cảnh 44: Emma, Chloe và Liam làm việc trong phòng thí nghiệm mới, cùng nhau nghiên cứu phương thuốc chữa trị (FINAL IMAGE).<br>Cảnh 45: Emma mỉm cười, ánh mắt tràn đầy hy vọng, hướng về tương lai với những người đồng đội của mình.<br>', '2026-03-16 15:27:00');
INSERT INTO `scenelists` (`id`, `project_id`, `type`, `input_data`, `output_data`, `created_at`) VALUES
(7, 29, 'screenplay', '{\"synopsis\":\"SYNOPSISMỞ ĐẦULâm \\\"LA\\\" Anh, tiền đạo ngôi sao 28 tuổi của đội tuyển Việt Nam, sống trong hào quang của sự nổi tiếng và tài năng. Anh được tung hô là người hùng, nhưng lại cô độc trong chính thế giới bóng đá của mình. Lâm Anh kiêu ngạo, coi thường đồng đội, ám ảnh bởi việc ghi bàn và giành chức vô địch World Cup – danh hiệu cuối cùng anh còn thiếu. Anh bị ám ảnh bởi chấn thương đầu gối trong quá khứ, sợ hãi rằng một sai lầm có thể chấm dứt sự nghiệp. Mở đầu phim, Lâm Anh có một trận đấu tệ hại, bỏ lỡ nhiều cơ hội ghi bàn vì lối chơi cá nhân, khiến đội nhà thua trận. Sau trận đấu, huấn luyện viên Ông Ba thẳng thắn chỉ trích sự ích kỷ của Lâm Anh, cho rằng anh cần học cách tin tưởng đồng đội nếu muốn đạt được thành công. Lời nói của Ông Ba không lay chuyển được Lâm Anh, anh cho rằng huấn luyện viên đang cố gắng kìm hãm tài năng của mình.Sự kiện kích hoạt xảy ra khi Liên đoàn bóng đá Việt Nam thông báo về việc thay đổi huấn luyện viên trưởng và chiến lược mới cho vòng loại World Cup. Ông Tùng, chủ tịch Liên đoàn, đặt áp lực lên đội bóng, yêu cầu phải có kết quả tốt để chứng minh năng lực. Đồng thời, Hoàng \\\"Sói\\\" Hải, tiền đạo ngôi sao của đội tuyển Thái Lan, đối thủ truyền kiếp của Lâm Anh, công khai chế nhạo anh trên mạng xã hội, thách thức Lâm Anh chứng minh bản thân trên sân cỏ. Điều này càng làm tăng thêm áp lực và sự ám ảnh của Lâm Anh về việc phải giành chiến thắng.PHÁT TRIỂNLâm Anh bắt đầu tập luyện với đội tuyển dưới sự dẫn dắt của huấn luyện viên Ông Ba. Ban đầu, anh vẫn giữ lối chơi cá nhân, cố gắng phớt lờ lời khuyên của huấn luyện viên và đồng đội. Anh coi thường Dũng, tiền đạo trẻ tài năng nhưng khiêm tốn, và thường xuyên xảy ra mâu thuẫn với Bình, tiền vệ trung tâm tận tâm. Mai, bạn gái của Lâm Anh, luôn bên cạnh động viên và khuyên nhủ anh, nhưng Lâm Anh vẫn khép kín và không chịu thay đổi.Trong một trận giao hữu quan trọng, Lâm Anh tiếp tục thi đấu ích kỷ, bỏ lỡ cơ hội ghi bàn và khiến đội nhà bị dẫn trước. Giữa hiệp hai, Lâm Anh bị chấn thương đầu gối tái phát sau pha va chạm với Hoàng Hải. Anh phải rời sân và chứng kiến đội nhà thua trận. Chấn thương khiến Lâm Anh rơi vào tuyệt vọng, anh sợ hãi rằng sự nghiệp của mình sẽ kết thúc.Điểm giữa phim (Midpoint) xảy ra khi Lâm Anh tình cờ nghe được cuộc trò chuyện giữa Ông Tùng và Hoàng Hải. Anh phát hiện ra rằng Ông Tùng đã bí mật thỏa thuận với Hoàng Hải để gây áp lực lên Lâm Anh, nhằm mục đích trục lợi cá nhân. Lâm Anh nhận ra rằng mình đã bị lợi dụng và phản bội. Anh cũng nhận ra rằng sự kiêu ngạo và ích kỷ của mình đã khiến anh trở nên mù quáng và không nhận ra những âm mưu xung quanh.CAO TRÀOSau khi biết được sự thật, Lâm Anh quyết định thay đổi. Anh xin lỗi Ông Ba và đồng đội vì những hành động trước đây. Anh bắt đầu lắng nghe lời khuyên của Ông Ba, học cách tin tưởng và phối hợp với đồng đội. Anh cũng hàn gắn mối quan hệ với Mai và Dũng. Lâm Anh nhận ra rằng bóng đá không chỉ là vinh quang cá nhân, mà còn là tinh thần đồng đội và sự hy sinh.Trong trận bán kết vòng loại World Cup, đội tuyển Việt Nam đối đầu với đội tuyển Thái Lan. Hoàng Hải tiếp tục chơi xấu và tìm cách khiêu khích Lâm Anh. Trận đấu diễn ra căng thẳng và kịch tính, cả hai đội đều có những cơ hội ghi bàn. Khi tỷ số đang hòa, Lâm Anh có cơ hội ghi bàn quyết định, nhưng anh nhận thấy Dũng đang ở vị trí thuận lợi hơn. Lâm Anh quyết định chuyền bóng cho Dũng, và Dũng đã ghi bàn thắng, đưa đội tuyển Việt Nam vào chung kết.KẾT THÚCTrong trận chung kết, đối thủ của đội tuyển Việt Nam là một đội bóng mạnh khác. Trận đấu diễn ra vô cùng khó khăn, Lâm Anh và đồng đội phải đối mặt với nhiều thử thách. Tuy nhiên, với tinh thần đoàn kết và sự hy sinh, họ đã chiến đấu hết mình. Ở phút cuối cùng, Lâm Anh bị phạm lỗi trong vòng cấm. Anh có cơ hội thực hiện quả penalty quyết định. Trước sự chứng kiến của hàng triệu khán giả, Lâm Anh đã thực hiện thành công quả penalty, mang về chiến thắng lịch sử cho đội tuyển Việt Nam.Lâm Anh không chỉ giành được chức vô địch World Cup, mà còn học được bài học về sự hy sinh và tinh thần đồng đội. Anh trở thành một người đội trưởng mẫu mực, truyền cảm hứng cho đồng đội và người hâm mộ. Lâm Anh hiểu rằng thành công thực sự không đến từ vinh quang cá nhân, mà đến từ sự đoàn kết, hy sinh và chính trực. Anh sống một cuộc đời ý nghĩa và hạnh phúc, không còn bị ám ảnh bởi quá khứ và những nỗi sợ hãi.CÁC ĐIỂM NGOẶT QUAN TRỌNGInciting Incident: Lâm Anh có một trận đấu tệ hại, bỏ lỡ nhiều cơ hội ghi bàn vì lối chơi cá nhân, khiến đội nhà thua trận. Sau trận đấu, huấn luyện viên Ông Ba thẳng thắn chỉ trích sự ích kỷ của Lâm Anh.Plot Point 1: Liên đoàn bóng đá Việt Nam thông báo về việc thay đổi huấn luyện viên trưởng và chiến lược mới cho vòng loại World Cup. Ông Tùng đặt áp lực lên đội bóng và Hoàng Hải chế nhạo Lâm Anh trên mạng xã hội.Midpoint: Lâm Anh tình cờ nghe được cuộc trò chuyện giữa Ông Tùng và Hoàng Hải, phát hiện ra âm mưu của họ và nhận ra sự ích kỷ của bản thân.Plot Point 2: Lâm Anh quyết định thay đổi, xin lỗi Ông Ba và đồng đội, bắt đầu học cách tin tưởng và phối hợp với đồng đội.Climax: Trong trận bán kết, Lâm Anh chuyền bóng cho Dũng ghi bàn quyết định. Trong trận chung kết, Lâm Anh thực hiện thành công quả penalty, mang về chiến thắng cho đội tuyển Việt Nam.\",\"characters\":\"NHÂN VẬT CHÍNHLÂM \\\"LA\\\" ANHTuổi/Nghề nghiệp: 28, Tiền đạo ngôi sao của đội tuyển quốc gia Việt NamNgoại hình: Cao to, vạm vỡ, có hình xăm biểu tượng trên cánh tay, vẻ ngoài lạnh lùng, tóc vuốt ngược.Tính cách: Tài năng, kiêu ngạo, quyết đoán trên sân cỏ, khó gần, ít chia sẻ cảm xúc thật.Điểm yếu (Flaw): Quá tự tin vào khả năng cá nhân, coi thường đồng đội, nóng tính, ám ảnh bởi thành tích cá nhân.Backstory: Lớn lên trong nghèo khó, từ nhỏ đã phải nỗ lực vượt bậc để khẳng định bản thân. Sự nghiệp thăng tiến nhanh chóng khiến anh trở nên kiêu ngạo và xa cách.Ghost/Wound: Chấn thương đầu gối nghiêm trọng trong quá khứ suýt chấm dứt sự nghiệp, khiến anh luôn sợ hãi thất bại và ám ảnh bởi việc phải chứng tỏ bản thân.WANT (Muốn): Giành chức vô địch World Cup, khẳng định vị thế cầu thủ số một thế giới.NEED (Cần): Học cách tin tưởng đồng đội, vượt qua nỗi sợ hãi thất bại, hiểu được giá trị của sự hy sinh và tinh thần đồng đội.Arc dự kiến: Từ một ngôi sao ích kỷ, chỉ biết đến bản thân và thành tích cá nhân → trở thành một người đội trưởng biết hy sinh vì tập thể, truyền cảm hứng cho đồng đội và trân trọng những giá trị đích thực của bóng đá.Vai trò trong chủ đề: Thể hiện sự cám dỗ của thành công cá nhân và sự ảo tưởng về sức mạnh tuyệt đối, nhưng cuối cùng nhận ra rằng thành công thực sự chỉ đến khi biết hy sinh vì tập thể.NHÂN VẬT PHẢN DIỆNHOÀNG \\\"SÓI\\\" HẢITuổi/Nghề nghiệp: 28, Tiền đạo ngôi sao của đội tuyển quốc gia đối thủ (ví dụ: Thái Lan).Ngoại hình: Vẻ ngoài bóng bẩy, luôn xuất hiện với những món đồ hiệu đắt tiền, nụ cười giả tạo.Tính cách: Xảo quyệt, tham vọng, luôn tìm cách hạ bệ đối thủ bằng mọi thủ đoạn, không từ bất cứ điều gì để đạt được mục đích.Điểm yếu (Flaw): Thiếu tự tin vào khả năng thực sự của bản thân, phải dùng đến những chiêu trò bẩn thỉu để che đậy sự yếu kém.Backstory: Từng là bạn thân của Lâm Anh, nhưng luôn sống trong cái bóng của anh. Sự ganh tị và lòng tham khiến anh đi vào con đường sai trái.Ghost/Wound: Luôn cảm thấy mình thua kém Lâm Anh, ám ảnh bởi việc phải vượt qua anh bằng mọi giá.WANT (Muốn): Đánh bại Lâm Anh, giành chức vô địch World Cup bằng mọi thủ đoạn.NEED (Cần): Nhận ra rằng thành công bằng sự gian dối và thủ đoạn không bao giờ mang lại hạnh phúc thực sự.Arc dự kiến: Không có sự thay đổi tích cực. Tiếp tục lún sâu vào con đường tội lỗi, cuối cùng phải trả giá đắt cho những hành động của mình.Vai trò trong chủ đề: Là gương phản chiếu của Lâm Anh, thể hiện con đường mà Lâm Anh có thể đã đi nếu không học được bài học về sự hy sinh và chính trực. Thể hiện rõ sự tha hóa của con người khi đặt lợi ích cá nhân lên trên tất cả.NHÂN VẬT PHỤÔNG BA - Huấn luyện viên trưởngVai trò: Mentor cho Lâm Anh. Người thầy nghiêm khắc nhưng giàu tình cảm, luôn tin tưởng vào tiềm năng của Lâm Anh và giúp anh nhận ra giá trị của tinh thần đồng đội. Ông là người truyền tải thông điệp về sự hy sinh và chính trực đến Lâm Anh.MAI - Bạn gái của Lâm AnhVai trò: Love Interest. Một cô gái mạnh mẽ, độc lập, luôn ủng hộ Lâm Anh nhưng không ngại chỉ trích những sai lầm của anh. Cô là người giúp Lâm Anh nhận ra giá trị của sự chân thành và tình yêu thương.DŨNG - Đồng đội thân thiết của Lâm AnhVai trò: Best Friend. Một cầu thủ tài năng nhưng khiêm tốn, luôn sẵn sàng hy sinh vì tập thể. Anh là người truyền cảm hứng cho Lâm Anh về tinh thần đồng đội và sự hy sinh.BÌNH - Tiền vệ trung tâmVai trò: Đại diện cho sự tận tâm và trung thành. Bình là một cầu thủ cần cù, luôn thi đấu hết mình vì đội bóng. Sự kiên trì của anh là nguồn động viên cho cả đội.SƠN - Hậu vệ cánhVai trò: Đại diện cho sự dũng cảm và kiên cường. Sơn là một hậu vệ mạnh mẽ, không ngại va chạm và luôn sẵn sàng bảo vệ đồng đội.TUẤN - Thủ mônVai trò: Đại diện cho sự tập trung và kỷ luật. Tuấn là một thủ môn xuất sắc, luôn giữ vững tinh thần và sự tập trung cao độ trong suốt trận đấu.NAM - Tiền vệ tấn công trẻVai trò: Đại diện cho thế hệ trẻ đầy tiềm năng. Nam là một cầu thủ trẻ đầy nhiệt huyết, luôn khao khát học hỏi và cống hiến cho đội bóng.CÔ HƯƠNG - Mẹ của Lâm AnhVai trò: Đại diện cho tình mẫu tử thiêng liêng và sự hy sinh vô điều kiện. Cô luôn là nguồn động viên lớn nhất của Lâm Anh.ÔNG TÙNG - Chủ tịch Liên đoàn bóng đáVai trò: Đại diện cho quyền lực và tham nhũng. Ông là người tạo áp lực lên đội bóng để đạt được những mục tiêu cá nhân.SƠ ĐỒ MỐI QUAN HỆ*   LÂM ANH - ÔNG BA: Mối quan hệ thầy trò, từ xa cách đến tin tưởng và kính trọng.*   LÂM ANH - MAI: Mối quan hệ tình yêu, từ hời hợt đến sâu sắc và chân thành.*   LÂM ANH - DŨNG: Mối quan hệ bạn bè, từ cạnh tranh đến hợp tác và tin tưởng.*   LÂM ANH - HOÀNG HẢI: Mối quan hệ đối địch, từ bạn bè đến kẻ thù.*   LÂM ANH - CÔ HƯƠNG: Mối quan hệ mẹ con, luôn yêu thương và ủng hộ.*   LÂM ANH - ĐỒNG ĐỘI: Mối quan hệ đồng đội, từ xa cách đến đoàn kết và hy sinh vì nhau.*   ÔNG TÙNG - ĐỘI BÓNG: Mối quan hệ quyền lực và áp lực, thể hiện sự tham nhũng và lợi dụng.\",\"structure\":\"CẤU TRÚC 4 HỒIHỒI 1: SETUP (Trang 1-25, khoảng 25 phút)Mục tiêu hồi này: Giới thiệu Lâm Anh, tài năng và sự cô độc của anh; thiết lập vấn đề về sự ích kỷ và ám ảnh thành tích cá nhân.Hình ảnh mở đầu cho thấy Lâm Anh, tiền đạo ngôi sao, ghi bàn thắng đẹp mắt nhưng không ăn mừng cùng đồng đội, thể hiện sự cô độc và tách biệt. Sau đó, phim chuyển sang một trận đấu quan trọng, nơi Lâm Anh liên tục bỏ lỡ cơ hội vì lối chơi cá nhân, dẫn đến thất bại của đội nhà. Huấn luyện viên Ông Ba chỉ trích thẳng thắn sự ích kỷ của anh, nhấn mạnh tầm quan trọng của tinh thần đồng đội. Lâm Anh phớt lờ lời khuyên, cho rằng huấn luyện viên đang kìm hãm tài năng của mình. Giai đoạn do dự thể hiện qua sự bướng bỉnh và cố chấp của Lâm Anh, anh không tin rằng sự thay đổi là cần thiết. Sự kiện kích hoạt (Catalyst) là thông báo về việc thay đổi huấn luyện viên trưởng và chiến lược mới cho vòng loại World Cup, cùng với sự chế nhạo từ Hoàng Hải. Áp lực từ Ông Tùng và sự khiêu khích từ Hoàng Hải khiến Lâm Anh quyết định phải chứng minh bản thân, nhưng vẫn giữ lối suy nghĩ cũ. Cuối hồi 1, Lâm Anh bước vào hành trình chuẩn bị cho vòng loại World Cup, nhưng chưa nhận ra sự cần thiết của việc thay đổi.Các điểm ngoặt quan trọng:Opening Image (Trang 1): Lâm Anh ghi bàn nhưng không ăn mừng cùng đồng đội.Catalyst (Trang 12): Thông báo thay đổi huấn luyện viên và chiến lược, Hoàng Hải chế nhạo Lâm Anh.Break into Two (Trang 25): Lâm Anh bắt đầu tập luyện, quyết tâm chứng minh bản thân.HỒI 2A: RESPONSE (Trang 25-55, khoảng 30 phút)Mục tiêu hồi này: Lâm Anh tập luyện, vẫn giữ lối chơi cá nhân; giới thiệu các nhân vật phụ và mối quan hệ của họ với Lâm Anh.Lâm Anh bắt đầu tập luyện dưới sự dẫn dắt của Ông Ba, nhưng vẫn giữ lối chơi cá nhân và coi thường đồng đội. Tuyến phụ (B-Story) được giới thiệu qua mối quan hệ của Lâm Anh với Mai, người luôn động viên và khuyên nhủ anh, và với Dũng, người mà Lâm Anh coi thường. Các thử thách và thành công ban đầu thể hiện qua những trận giao hữu mà Lâm Anh cố gắng ghi bàn một mình, nhưng không hiệu quả. Anh thường xuyên mâu thuẫn với Bình và không lắng nghe lời khuyên của Ông Ba. Midpoint xảy ra trong một trận giao hữu quan trọng, khi Lâm Anh bị chấn thương đầu gối tái phát sau pha va chạm với Hoàng Hải. Đội nhà thua trận và Lâm Anh rơi vào tuyệt vọng. Anh tin rằng sự nghiệp của mình có thể kết thúc. Sự khám phá quan trọng (Revelation) ở đây là Lâm Anh đối diện với nỗi sợ hãi lớn nhất của mình: thất bại và mất đi sự nghiệp.Các điểm ngoặt quan trọng:B-Story Begins (Trang 30): Giới thiệu mối quan hệ của Lâm Anh với Mai và Dũng.Midpoint (Trang 55): Lâm Anh bị chấn thương, đội nhà thua trận.HỒI 2B: ACTION (Trang 55-85, khoảng 30 phút)Mục tiêu hồi này: Lâm Anh khám phá ra sự thật về âm mưu của Ông Tùng và Hoàng Hải; anh quyết định thay đổi.Hậu quả từ Midpoint là Lâm Anh rơi vào tuyệt vọng và mất niềm tin. Áp lực từ bên ngoài (sự chỉ trích của giới truyền thông) và nội tâm (nỗi sợ hãi thất bại) gia tăng. Lâm Anh tình cờ nghe được cuộc trò chuyện giữa Ông Tùng và Hoàng Hải, phát hiện ra âm mưu của họ (Bad Guys Close In). Mất mát lớn nhất (All Is Lost) là khi Lâm Anh nhận ra mình đã bị lợi dụng và phản bội. Khoảnh khắc tối tăm nhất (Dark Night of the Soul) là khi Lâm Anh đối diện với sự thật về sự ích kỷ và mù quáng của mình. Anh nhận ra rằng chính sự kiêu ngạo đã khiến anh không nhận ra những âm mưu xung quanh. Cuối cùng, Lâm Anh tìm ra giải pháp (Break into Three): anh quyết định thay đổi, xin lỗi Ông Ba và đồng đội, và bắt đầu học cách tin tưởng và phối hợp với họ.Các điểm ngoặt quan trọng:All Is Lost (Trang 75): Lâm Anh nhận ra mình bị lợi dụng và phản bội.Dark Night of the Soul (Trang 75-85): Lâm Anh đối diện với sự ích kỷ của bản thân.Break into Three (Trang 85): Lâm Anh quyết định thay đổi.HỒI 3: CLIMAX (Trang 85-110, khoảng 25 phút)Mục tiêu hồi này: Đội tuyển Việt Nam vượt qua thử thách, Lâm Anh học được bài học về sự hy sinh và tinh thần đồng đội.Lâm Anh thực hiện kế hoạch cuối cùng bằng cách xin lỗi và thay đổi thái độ. Anh bắt đầu lắng nghe lời khuyên của Ông Ba, học cách tin tưởng và phối hợp với đồng đội. Đối đầu cuối cùng (Climax) diễn ra trong trận bán kết vòng loại World Cup với đội tuyển Thái Lan. Hoàng Hải tiếp tục chơi xấu và khiêu khích Lâm Anh. Khi tỷ số đang hòa, Lâm Anh có cơ hội ghi bàn quyết định, nhưng anh quyết định chuyền bóng cho Dũng, người đang ở vị trí thuận lợi hơn. Dũng ghi bàn thắng, đưa đội tuyển Việt Nam vào chung kết. Trong trận chung kết, đội tuyển Việt Nam đối đầu với một đội bóng mạnh khác. Lâm Anh bị phạm lỗi trong vòng cấm và thực hiện thành công quả penalty quyết định, mang về chiến thắng lịch sử. Các tuyến phụ được giải quyết: Lâm Anh hàn gắn mối quan hệ với Mai và Dũng. Hình ảnh cuối cùng (Final Image) là hình ảnh cả đội tuyển Việt Nam ăn mừng chiến thắng cùng nhau, tượng trưng cho sự đoàn kết và tinh thần đồng đội, đối lập với hình ảnh cô đơn của Lâm Anh ở đầu phim.Các điểm ngoặt quan trọng:Climax (Trang 100-105): Trận bán kết và chung kết vòng loại World Cup.Final Image (Trang 110): Đội tuyển Việt Nam ăn mừng chiến thắng cùng nhau.TỔNG QUAN ARC NHÂN VẬT QUA 4 HỒILâm Anh bắt đầu phim là một ngôi sao cô độc, ích kỷ và ám ảnh bởi thành tích cá nhân. Anh trải qua một loạt biến cố, từ chấn thương tái phát đến việc phát hiện ra âm mưu của người khác. Những biến cố này buộc anh phải đối diện với bản thân và thay đổi. Cuối cùng, Lâm Anh học được bài học về sự hy sinh, tinh thần đồng đội và chính trực. Anh trở thành một người đội trưởng mẫu mực, truyền cảm hứng cho đồng đội và người hâm mộ, và nhận ra rằng thành công thực sự đến từ sự đoàn kết và những giá trị đích thực.\",\"beatsheet\":\"BEAT SHEET CHI TIẾTBEAT 1: OPENING IMAGE (Trang 1)Mục đích: Thiết lập tone, mood, và trạng thái \\\"trước\\\" của nhân vậtNội dung: Lâm Anh ghi một bàn thắng đẹp mắt, phô diễn kỹ thuật cá nhân điêu luyện, nhưng không ăn mừng cùng đồng đội. Anh đứng một mình, nhìn khán đài với ánh mắt lạnh lùng, xa cách.Liên kết với Final Image: Đối lập hoàn toàn. Ở cuối phim, Lâm Anh hòa mình vào tập thể, ăn mừng chiến thắng cùng đồng đội, thể hiện sự đoàn kết và tinh thần đồng đội.BEAT 2: THEME STATED (Trang 5)Mục đích: Ai đó (không phải protagonist) nói điều gì liên quan đến chủ đềNội dung: Huấn luyện viên Ông Ba nói với Lâm Anh sau trận đấu tệ hại: \\\"Một mình cậu không thể thắng được cả thế giới. Cậu cần tin tưởng đồng đội.\\\"Chủ đề được ngụ ý: Tinh thần đồng đội quan trọng hơn thành tích cá nhân. Sự hy sinh và đoàn kết mang lại thành công thực sự.BEAT 3: SETUP (Trang 1-10)Mục đích: Giới thiệu thế giới, nhân vật, điểm yếu, stakesNội dung: Cuộc sống thường ngày: Lâm Anh sống trong biệt thự sang trọng, được tung hô bởi truyền thông và người hâm mộ. Anh tập luyện một mình, bỏ qua lời khuyên của huấn luyện viên.Các mối quan hệ quan trọng: Mối quan hệ hời hợt với bạn gái Mai, sự xa cách với đồng đội, đặc biệt là Dũng và Bình.Điểm yếu/vấn đề của nhân vật: Lâm Anh kiêu ngạo, coi thường đồng đội, ám ảnh bởi việc ghi bàn và giành chức vô địch World Cup. Anh sợ hãi chấn thương tái phát.\\\"Save the Cat\\\" moment: Lâm Anh lặng lẽ quyên góp tiền cho một quỹ từ thiện giúp đỡ trẻ em nghèo, thể hiện một phần con người nhân ái ẩn sau vẻ ngoài lạnh lùng.BEAT 4: CATALYST (Trang 12)Mục đích: Sự kiện phá vỡ trạng thái cân bằngNội dung: Liên đoàn bóng đá Việt Nam thông báo về việc thay đổi huấn luyện viên trưởng và chiến lược mới cho vòng loại World Cup. Chủ tịch Ông Tùng đặt áp lực lên đội bóng. Hoàng Hải công khai chế nhạo Lâm Anh trên mạng xã hội.Tại sao nhân vật không thể bỏ qua: Áp lực từ Liên đoàn, sự khiêu khích từ đối thủ truyền kiếp Hoàng Hải, và nỗi ám ảnh về việc phải chứng minh bản thân khiến Lâm Anh không thể đứng ngoài cuộc.BEAT 5: DEBATE (Trang 12-25)Mục đích: Nhân vật do dự, cân nhắcNội dung: Lâm Anh đấu tranh nội tâm. Một mặt, anh muốn tiếp tục lối chơi cá nhân để chứng tỏ tài năng. Mặt khác, anh nhận thấy áp lực ngày càng lớn và những lời chỉ trích gay gắt. Anh tự hỏi liệu mình có nên thay đổi hay không.Nội tâm nhân vật: Sợ hãi mất đi vị thế, hoài nghi về khả năng của đồng đội, nhưng cũng khao khát chiến thắng và sự công nhận.BEAT 6: BREAK INTO TWO (Trang 25)Mục đích: Nhân vật CHỌN hành động, bước vào Act 2Nội dung: Lâm Anh quyết định tham gia tập luyện với đội tuyển dưới sự dẫn dắt của huấn luyện viên Ông Ba. Anh vẫn giữ lối chơi cá nhân, nhưng bắt đầu để ý hơn đến những gì diễn ra xung quanh.Đây là điểm không thể quay lại vì: Lâm Anh đã bước chân vào hành trình chuẩn bị cho vòng loại World Cup, buộc phải đối mặt với những thử thách mới và những người xung quanh.BEAT 7: B STORY (Trang 30)Mục đích: Giới thiệu tuyến phụ (thường là love interest), thể hiện chủ đềNội dung: Giới thiệu mối quan hệ giữa Lâm Anh và Mai. Mai luôn bên cạnh động viên và khuyên nhủ Lâm Anh, nhưng anh vẫn khép kín và khó mở lòng.Cách B-story phản ánh chủ đề: Mai đại diện cho tình yêu thương và sự chân thành. Mối quan hệ của cô với Lâm Anh cho thấy tầm quan trọng của việc mở lòng và tin tưởng người khác.BEAT 8: FUN AND GAMES (Trang 30-55)Mục đích: \\\"Promise of the premise\\\" - lý do khán giả xem phimNội dung: Cảnh fun 1: Lâm Anh cố gắng phớt lờ lời khuyên của Ông Ba trong các buổi tập, dẫn đến những tình huống hài hước và bế tắc.Cảnh fun 2: Lâm Anh tranh cãi với Bình về chiến thuật, thể hiện sự bất đồng quan điểm và cái tôi lớn của cả hai.Cảnh fun 3: Lâm Anh tham gia một trận giao hữu, cố gắng ghi bàn một mình nhưng không thành công, khiến đội nhà gặp khó khăn.Nhân vật đang học/làm gì: Lâm Anh đang cố gắng chứng minh bản thân, nhưng vẫn chưa nhận ra giá trị của tinh thần đồng đội. Anh đang học cách thích nghi với môi trường mới, nhưng vẫn giữ lối suy nghĩ cũ.BEAT 9: MIDPOINT (Trang 55)Mục đích: False Victory hoặc False Defeat + RevelationLoại: False DefeatNội dung: Trong một trận giao hữu quan trọng, Lâm Anh bị chấn thương đầu gối tái phát sau pha va chạm với Hoàng Hải. Anh phải rời sân và chứng kiến đội nhà thua trận.Revelation/Stakes mới: Lâm Anh nhận ra rằng sự nghiệp của mình có thể kết thúc. Anh cũng nhận ra rằng sự ích kỷ của mình đã khiến đội nhà thất bại.Tại sao đây là điểm không thể quay lại: Chấn thương và thất bại khiến Lâm Anh rơi vào tuyệt vọng và buộc phải đối diện với những nỗi sợ hãi lớn nhất của mình.BEAT 10: BAD GUYS CLOSE IN (Trang 55-75)Mục đích: Áp lực từ bên ngoài VÀ bên trong tăng caoÁp lực bên ngoài:Sự chỉ trích gay gắt từ giới truyền thông và người hâm mộ sau trận thua.Áp lực từ Ông Tùng về việc phải có kết quả tốt trong vòng loại World Cup.Áp lực bên trong (đội nhóm tan rã, nghi ngờ...):Lâm Anh mất niềm tin vào bản thân và đồng đội.Mối quan hệ giữa Lâm Anh và Mai trở nên căng thẳng.BEAT 11: ALL IS LOST (Trang 75)Mục đích: Điểm thấp nhất, \\\"whiff of death\\\"Nội dung: Lâm Anh tình cờ nghe được cuộc trò chuyện giữa Ông Tùng và Hoàng Hải, phát hiện ra âm mưu của họ. Anh nhận ra mình đã bị lợi dụng và phản bội.Mất mát: Mất niềm tin vào những người xung quanh, nhận ra sự thật phũ phàng về thế giới bóng đá.Tại sao nhân vật tưởng như hết hy vọng: Lâm Anh cảm thấy cô đơn và lạc lõng, không biết phải tin vào ai. Anh mất phương hướng và không còn động lực để tiếp tục.BEAT 12: DARK NIGHT OF THE SOUL (Trang 75-85)Mục đích: Nhân vật đối mặt với bản thân, với LieNội dung: Lâm Anh ngồi một mình trong bóng tối, suy ngẫm về những sai lầm của mình. Anh nhớ lại những lời khuyên của Ông Ba và Mai.Nhận ra điều gì: Lâm Anh nhận ra rằng sự ích kỷ và kiêu ngạo đã khiến anh mù quáng và không nhận ra những âm mưu xung quanh. Anh cũng nhận ra rằng bóng đá không chỉ là vinh quang cá nhân, mà còn là tinh thần đồng đội và sự hy sinh.BEAT 13: BREAK INTO THREE (Trang 85)Mục đích: Tìm ra giải pháp, kết hợp A + B storyNội dung: Lâm Anh quyết định thay đổi. Anh xin lỗi Ông Ba và đồng đội vì những hành động trước đây. Anh bắt đầu lắng nghe lời khuyên của Ông Ba, học cách tin tưởng và phối hợp với đồng đội. Anh cũng hàn gắn mối quan hệ với Mai.Cách B-story giúp tìm ra giải pháp: Tình yêu và sự tha thứ của Mai giúp Lâm Anh có thêm động lực để thay đổi.BEAT 14: FINALE (Trang 85-110)Mục đích: Thực hiện kế hoạch, đối đầu cuối cùng5 bước của Finale:Gathering the team: Lâm Anh xin lỗi và thuyết phục đồng đội tin tưởng anh một lần nữa.Executing the plan: Đội tuyển Việt Nam tập luyện chăm chỉ, xây dựng chiến thuật dựa trên tinh thần đồng đội.High Tower Surprise: Hoàng Hải tiếp tục chơi xấu và tìm cách khiêu khích Lâm Anh trong trận bán kết.Dig Deep Down: Lâm Anh nhận thấy Dũng đang ở vị trí thuận lợi hơn trong trận bán kết và quyết định chuyền bóng cho Dũng ghi bàn quyết định. Trong trận chung kết, Lâm Anh vượt qua áp lực để thực hiện thành công quả penalty.Victory/Defeat: Đội tuyển Việt Nam giành chiến thắng lịch sử, vô địch vòng loại World Cup.BEAT 15: FINAL IMAGE (Trang 110)Mục đích: Hình ảnh đối lập với Opening, chứng minh sự thay đổiNội dung: Cả đội tuyển Việt Nam ăn mừng chiến thắng cùng nhau, ôm nhau và hát vang bài ca chiến thắng. Lâm Anh đứng giữa vòng tay đồng đội, tươi cười rạng rỡ.Đối lập với Opening như thế nào: Ở đầu phim, Lâm Anh cô đơn và xa cách. Ở cuối phim, anh hòa mình vào tập thể, thể hiện sự đoàn kết và tinh thần đồng đội.SƠ ĐỒ LIÊN KẾT CÁC BEATLâm Anh khởi đầu là một ngôi sao cô đơn, ích kỷ (Opening Image). Sự chỉ trích của huấn luyện viên (Theme Stated) và áp lực từ bên ngoài (Catalyst) khiến anh phải tham gia vào hành trình mới (Break into Two). Trong quá trình đó, anh gặp gỡ những người quan trọng (B Story), nhưng vẫn giữ lối chơi cá nhân (Fun and Games). Chấn thương và thất bại (Midpoint) khiến anh rơi vào tuyệt vọng, nhưng sự phản bội (All is Lost) buộc anh phải đối diện với bản thân (Dark Night of the Soul). Cuối cùng, anh quyết định thay đổi (Break into Three), hợp tác với đồng đội (Finale) và giành chiến thắng (Final Image). Mỗi beat đều là một bước tiến trong arc nhân vật của Lâm Anh, từ sự cô đơn đến sự hòa nhập, từ sự ích kỷ đến sự hy sinh.\"}', '<h2>DANH SÁCH CẢNH</h2></p><p><h3>HỒI 1: SETUP:</h3></p><p>Cảnh 1: Sân vận động quốc gia - Đêm. Lâm Anh ghi bàn thắng đẹp mắt nhưng không ăn mừng cùng đồng đội, ánh mắt lạnh lùng hướng về khán đài, thể hiện sự cô độc.</p><p>Cảnh 2: Phòng thay đồ - Đêm. Sau trận đấu, HLV Ông Ba chỉ trích Lâm Anh vì lối chơi cá nhân, nhắc nhở anh về tầm quan trọng của tinh thần đồng đội.</p><p>Cảnh 3: Biệt thự sang trọng của Lâm Anh - Đêm. Lâm Anh xem lại highlight bàn thắng của mình, phớt lờ lời khuyên của HLV, cho rằng đó là sự ghen tị tài năng.</p><p>Cảnh 4: Sân tập - Sáng. Lâm Anh tập luyện một mình, bỏ qua các bài tập nhóm, thể hiện sự tự tin thái quá vào khả năng cá nhân.</p><p>Cảnh 5: Quán cafe - Trưa. Lâm Anh gặp Mai, bạn gái anh, Mai khuyên anh nên lắng nghe HLV và đồng đội, nhưng Lâm Anh gạt đi.</p><p>Cảnh 6: Sân tập - Chiều. Lâm Anh tranh cãi với Dũng và Bình về chiến thuật, thể hiện sự coi thường và bất hợp tác.</p><p>Cảnh 7: Trung tâm thể thao - Tối. Lâm Anh lặng lẽ quyên góp tiền cho quỹ từ thiện, thể hiện mặt tốt bụng ẩn sau vẻ ngoài lạnh lùng.</p><p>Cảnh 8: Văn phòng Liên đoàn bóng đá - Ngày. Ông Tùng thông báo về việc thay đổi HLV trưởng và chiến lược mới, gây áp lực lên đội tuyển.</p><p>Cảnh 9: Mạng xã hội - Ngày. Hoàng Hải đăng tải video chế nhạo Lâm Anh, thách thức anh chứng minh bản thân trên sân cỏ.</p><p>Cảnh 10: Biệt thự của Lâm Anh - Đêm. Lâm Anh xem video của Hoàng Hải, tức giận và quyết tâm chứng minh mình giỏi hơn.</p><p>Cảnh 11: Sân tập - Sáng. Lâm Anh tham gia buổi tập đầu tiên dưới sự dẫn dắt của HLV Ông Ba, nhưng vẫn giữ lối chơi cá nhân.</p><p><h3>HỒI 2A: RESPONSE:</h3></p><p>Cảnh 12: Sân tập - Chiều. Lâm Anh cố gắng phớt lờ lời khuyên của HLV Ông Ba, dẫn đến những tình huống bế tắc và khó khăn trong buổi tập.</p><p>Cảnh 13: Phòng thay đồ - Chiều. Lâm Anh tranh cãi gay gắt với Bình về chiến thuật, thể hiện sự bất đồng và cái tôi lớn của cả hai.</p><p>Cảnh 14: Sân vận động - Ngày. Lâm Anh tham gia trận giao hữu, cố gắng ghi bàn một mình nhưng không thành công, khiến đội nhà gặp khó khăn.</p><p>Cảnh 15: Quán bar - Đêm. Lâm Anh và Mai cãi nhau vì sự ích kỷ của anh trên sân cỏ, mối quan hệ bắt đầu căng thẳng.</p><p>Cảnh 16: Phòng vật lý trị liệu - Ngày. Lâm Anh điều trị chấn thương đầu gối, nỗi sợ hãi tái phát chấn thương ám ảnh anh.</p><p>Cảnh 17: Sân vận động - Đêm. Trận giao hữu quan trọng, Lâm Anh va chạm với Hoàng Hải, chấn thương đầu gối tái phát.</p><p>Cảnh 18: Bệnh viện - Đêm. Lâm Anh đau đớn trên giường bệnh, lo sợ sự nghiệp chấm dứt, đội nhà thua trận.</p><p><h3>HỒI 2B: ACTION:</h3></p><p>Cảnh 19: Phòng bệnh viện - Ngày. Lâm Anh đọc báo, nhận những lời chỉ trích gay gắt từ giới truyền thông và người hâm mộ.</p><p>Cảnh 20: Văn phòng Ông Tùng - Ngày. Ông Tùng gây áp lực lên HLV Ông Ba về việc phải có kết quả tốt trong vòng loại World Cup.</p><p>Cảnh 21: Phòng bệnh viện - Đêm. Mai đến thăm Lâm Anh, động viên anh, nhưng Lâm Anh lạnh lùng và mất niềm tin.</p><p>Cảnh 22: Hành lang bệnh viện - Đêm. Lâm Anh tình cờ nghe được cuộc trò chuyện giữa Ông Tùng và Hoàng Hải về âm mưu của họ.</p><p>Cảnh 23: Phòng bệnh viện - Đêm. Lâm Anh suy sụp khi nhận ra mình bị lợi dụng và phản bội, mất niềm tin vào mọi thứ.</p><p>Cảnh 24: Biệt thự của Lâm Anh - Đêm. Lâm Anh ngồi một mình trong bóng tối, suy ngẫm về những sai lầm của mình.</p><p>Cảnh 25: Biệt thự của Lâm Anh - Sáng. Lâm Anh quyết định thay đổi, gọi điện xin lỗi HLV Ông Ba và hẹn gặp.</p><p>Cảnh 26: Sân tập - Sáng. Lâm Anh xin lỗi HLV Ông Ba và đồng đội, bày tỏ mong muốn được chuộc lỗi và thay đổi.</p><p><h3>HỒI 3: CLIMAX:</h3></p><p>Cảnh 27: Sân tập - Các ngày. Lâm Anh tập luyện chăm chỉ, lắng nghe lời khuyên của HLV, học cách tin tưởng và phối hợp với đồng đội.</p><p>Cảnh 28: Quán cafe - Ngày. Lâm Anh xin lỗi Mai, hàn gắn mối quan hệ, Mai động viên và ủng hộ anh.</p><p>Cảnh 29: Sân tập - Chiều. Đội tuyển Việt Nam tập luyện chiến thuật mới dựa trên tinh thần đồng đội.</p><p>Cảnh 30: Phòng thay đồ - Trước trận bán kết. HLV Ông Ba động viên tinh thần toàn đội, nhấn mạnh sự đoàn kết và hy sinh.</p><p>Cảnh 31: Sân vận động - Trận bán kết. Hoàng Hải chơi xấu và tìm cách khiêu khích Lâm Anh, khiến trận đấu trở nên căng thẳng.</p><p>Cảnh 32: Sân vận động - Trận bán kết. Tỷ số hòa, Lâm Anh có cơ hội ghi bàn nhưng quyết định chuyền bóng cho Dũng ở vị trí thuận lợi hơn.</p><p>Cảnh 33: Sân vận động - Trận bán kết. Dũng ghi bàn thắng quyết định, đưa đội tuyển Việt Nam vào chung kết.</p><p>Cảnh 34: Phòng thay đồ - Sau trận bán kết. Cả đội ăn mừng chiến thắng, Lâm Anh và Dũng ôm nhau, thể hiện tình đồng đội.</p><p>Cảnh 35: Sân vận động - Trận chung kết. Đội tuyển Việt Nam đối đầu với đội bóng mạnh, trận đấu diễn ra vô cùng khó khăn.</p><p>Cảnh 36: Sân vận động - Trận chung kết. Lâm Anh bị phạm lỗi trong vòng cấm ở phút cuối cùng, đội nhà được hưởng penalty.</p><p>Cảnh 37: Sân vận động - Trận chung kết. Lâm Anh thực hiện thành công quả penalty, mang về chiến thắng lịch sử cho đội tuyển Việt Nam.</p><p>Cảnh 38: Sân vận động - Sau trận chung kết. Cả đội tuyển Việt Nam ăn mừng chiến thắng, ôm nhau và hát vang bài ca chiến thắng.</p><p>Cảnh 39: Khán đài - Sau trận chung kết. Mai chạy xuống sân ôm Lâm Anh, cả hai trao nhau nụ hôn ngọt ngào.</p><p>Cảnh 40: Đường phố - Đêm. Đoàn xe chở đội tuyển Việt Nam diễu hành qua các đường phố, người hâm mộ reo hò và cổ vũ.</p><p>Cảnh 41: Biệt thự của Lâm Anh - Đêm. Lâm Anh xem lại video bàn thắng của mình, mỉm cười hạnh phúc, không còn cô đơn.</p><p>Cảnh 42: Nhà của Lâm Anh - Ngày. Lâm Anh về thăm mẹ, hai mẹ con ôm nhau hạnh phúc, Lâm Anh khoe huy chương vô địch.</p><p>Cảnh 43: Sân vận động - Ngày. Lâm Anh hướng dẫn các cầu thủ trẻ, truyền cảm hứng về tinh thần đồng đội và sự hy sinh.<br>', '2026-03-30 03:37:21');

