INSERT INTO `stories` (`id`, `project_id`, `input_data`, `output_data`, `created_at`) VALUES
(3, 26, '{\"file_name\":\"Nội dung đã dán\"}', 'Ngày xưa, có một đứa bé thông minh tên là Nguyễn Kỳ, mẹ mất sớm, cha lấy vợ khác. Kỳ bị dì ghẻ hành hạ ác nghiệt nên phải bỏ nhà mà đi.\n\nLang thang khắp nơi, Kỳ gặp một cụ cử cho ở lại nhà và cho học chữ. Sẵn khiếu thông minh, Kỳ không những theo kịp các bạn, mà còn nổi tiếng giỏi văn thơ.\n\nMột hôm Kỳ theo bạn học đi xem ca múa, thấy mình nghèo nên đứng trong góc nhà, chợt cô đào hát trông thấy, và hôm sau, khi Kỳ đang ngồi đọc sách thì cô đào đem 10 nén bạc đến làm quen. Kỳ nhất định không lấy, nhưng cô ta nài ép, để bạc đấy rồi bỏ đi. Cách ít lâu, nàng trở lại, rồi trở lại nữa. Hai bên dần dần quen nhau. Một hôm, không còn tự chủ được trước người con gái đẹp, giọng thướt tha, Kỳ làm một cử chỉ suồng sã, rồi hối hận ngay. Nhưng cô đào nghiêm nghị trách:\n\n“Anh chớ vội tưởng lầm, em tìm đến anh vì trọng người đứng đắn, vì nghĩ đến tương lai, muốn tìm nơi nương tựa lâu dài, anh đừng nghĩ em là phường bậy bạ.”\n\nTừ đó Kỳ càng trọng kính cô đào hơn, và cô vẫn giúp Kỳ qua cơn túng thiếu.\n\nTrước ngày lên đường đi thi, Kỳ muốn biết tông tích cô đào, muốn liên lạc với cô sau này, nhưng cô chỉ nói:\n\n“Sau này nếu anh không quên em, thì em sẽ tìm đến với anh, nếu anh quên em, thì hỏi tông tích em cũng vô ích. Phần em, em không đòi anh hứa gì cả, chỉ có Trời biết lòng em.”\n\nKhi Kỳ thi đỗ trở về quê, cha chàng bắt kết hôn với người “môn đăng hộ đối”. Kỳ hết sức từ chối, nhất quyết thà chết hơn phụ bạc người đã một lần yêu thương giúp đỡ, nhưng cha chàng cũng nhất quyết không chịu cho quan chức kết duyên với cô ả đào, không nhận ả đào làm con dâu. Nguyễn Kỳ đau khổ, nhưng lễ giáo bắt buộc, bổn phận làm con bắt buộc, nên chàng đành phải lấy vợ theo ý cha.\n\nNăm sau, chàng ra kinh đô thi tiến sĩ, cô đào mang đủ thứ đến thăm. Thấy Kỳ có vẻ ngượng ngùng, cô hiểu ngay, và từ biệt hẳn.\n\nNguyễn Kỳ thi đỗ, làm quan trong triều, đi sứ bên Tàu, dẹp loạn ở Hải dương, được vua ban thưởng tước “quận công”.\n\nDanh vọng cao, tiền bạc sẵn, con cái đông, nhưng Kỳ luôn nhớ tới tình cô đào hát xưa, cho người dọ hỏi khắp nơi, nhưng không gặp.\n\nMột hôm, trong bữa tiệc tại nhà người quan bạn, Kỳ đã tình cờ gặp lại cô đào, bấy giờ nàng đã có chồng làm lính, nhưng nay chồng đã chết, chỉ còn có mẹ già yếu bệnh, nàng phải trở lại nghiệp hát để nuôi mình và nuôi mẹ.\n\nNguyễn Kỳ cố mời hai mẹ con về ở trong dinh, nàng đành chấp nhận. Kỳ dành cho mẹ con ngôi nhà riêng, và không để cho thiếu thốn vật gì. Một năm sau bà cụ mất, Nguyễn Kỳ cho chôn cất trọng thể. Xong rồi nàng cảm ơn và xin phép từ biệt. Nguyễn kỳ không giữ lại được, nài nỉ nàng nhận lấy vài nén bạc, nàng cũng từ chối mà ra đi.', '2026-03-03 08:19:55'),
(4, 27, '{\"file_name\":\"Nội dung đã dán\"}', 'Xưa có một anh chàng tiều phu nghèo, cha mẹ anh bệnh nặng nên qua đời sớm, anh phải sống mồ côi cha mẹ từ nhỏ và tài sản của anh chỉ có một chiếc rìu. Hàng ngày anh phải xách rìu vào rừng để đốn củi bán để lấy tiền kiếm sống qua ngày. Cạnh bìa rừng có một con sông nước chảy rất xiết, ai đó lỡ trượt chân rơi xuống sông thì rất khó bơi vào bờ.\n\nMột hôm, như thường ngày chàng tiều phu vác rìu vào rừng để đốn củi, trong lúc đang chặt củi cạnh bờ sông thì chẳng may chiếc rìu của chàng bị gãy cán và lưỡi rìu văng xuống sông. Vì dòng sông nước chảy quá xiết nên mặc dù biết bơi nhưng anh chàng vẫn không thể xuống sông để tìm lưỡi rìu. Thất vọng anh chàng tiều phu ngồi khóc than thở.\n\nBỗng từ đâu đó có một ông cụ tóc trắng bạc phơ, râu dài, đôi mắt rất hiền từ xuất hiện trước mặt chàng, ông cụ nhìn chàng tiêu phu và hỏi:\n\n-Này con, con đang có chuyện gì mà ta thấy con khóc và buồn bã như vậy?\n\nAnh chàng tiều phu trả lời ông cụ:\n\n-Thưa cụ, bố mẹ cháu mất sớm, cháu phải sống mồ côi từ nhỏ, gia cảnh nhà cháu rất nghèo, tài sản duy nhất của cháu là chiếc rìu sắt mà bố mẹ cháu trước lúc qua đời để lại. Có chiếc rìu đó cháu còn vào rừng đốn củi kiếm sống qua ngày, giờ đây nó đã bị rơi xuống sông, cháu không biết lấy gì để kiếm sống qua ngày nữa. Vì vậy cháu buồn lắm cụ ạ!\n\nÔng cụ đáp lời chàng tiều phu:\n\n-Ta tưởng chuyện gì lớn, cháu đừng khóc nữa, để ta lặn xuống sông lấy hộ cháu chiếc rìu lên.\n\nDứt lời, ông cụ lao mình xuống dòng sông đang chảy rất xiết. Một lúc sau, ông cụ ngoi lên khỏi mặt nước tay cầm một chiếc rìu bằng bạc sáng loáng và hỏi anh chàng tiều phu nghèo:\n\n– Đây có phải lưỡi rìu mà con đã làm rơi xuống không ?\n\nAnh chàng tiều phu nhìn lưỡi rìu bằng bạc thấy không phải của mình nên anh lắc đầu và bảo ông cụ:\n\n– Không phải lưỡi rìu của cháu cụ ạ, lưỡi rìu của cháu bằng sắt cơ.\n\nLần thứ hai, ông cụ lại lao mình xuống dòng sông chảy xiết để tìm chiếc rìu cho chàng tiều phu. Một lúc sau, ông cụ ngoi lên khỏi mặt nước tay cầm chiếc rìu bằng vàng và hỏi chàng tiều phu:\n\n-Đây có phải là lưỡi rìu mà con đã sơ ý làm rơi xuống sông không?\n\nAnh chàng tiều phu nhìn lưỡi rìu bằng vàng sáng chói, anh lại lắc đầu và bảo:\n\n-Không phải là lưỡi rìu của con cụ ạ\n\nLần thứ ba, ông cụ lại lao mình xuống sông và lần này khi lên ông cụ cầm trên tay là chiếc rìu bằng sắt của anh chàng tiều phu đánh rơi. Ông cụ lại hỏi:\n\n-Vậy đây có phải là lưỡi rìu của con không!\n\nThấy đúng là lưỡi rìu của mình rồi, anh chàng tiều phu reo lên sung sướng:\n\n-Vâng cụ, đây đúng là lưỡi rìu của con, con cảm ơn cụ đã tìm hộ con lưỡi rìu để con có cái đốn củi kiếm sống qua ngày.\n\nÔng cụ đưa cho anh chàng tiều phu lưỡi rìu bằng sắt của anh và khen:\n\n-Con quả là người thật thà và trung thực, không hề ham tiền bạc và lợi lộc. Nay ta tặng thêm cho con hai lưỡi rìu bằng vàng và bạc này. Đây là quà ta tặng con, con cứ vui vẻ nhận.\n\nAnh chàng tiều phu vui vẻ đỡ lấy hai lưỡi rìu mà ông cụ tặng và cảm tạ. Ông cụ hóa phép và biến mất. Lúc đó anh chàng tiều phu mới biết rằng mình vừa được bụt giúp đỡ.', '2026-03-04 08:49:15'),
(5, 28, '{\"file_name\":\"screenplay_story_script_2026-03-01.docx\"}', 'NGOẠI. RỪNG - SÁNG\nÁnh bình minh len lỏi qua những tán cây cổ thụ, tạo thành những vệt sáng vàng trên mặt đất ẩm ướt. Sương sớm còn đọng lại trên lá cây, lấp lánh như những viên ngọc trai.\nANH TIỀU PHU\n(vẻ mặt khắc khổ)\nđi xuyên qua khu rừng. Quần áo anh ta sờn rách, lấm lem bùn đất. Anh vác trên vai chiếc rìu cũ kỹ, lưỡi rìu đã mòn vẹt.\nTiếng chim hót líu lo vang vọng trong không gian tĩnh lặng. Anh Tiều Phu dừng lại, đưa tay lau mồ hôi trên trán. Anh thở dài, nhìn xung quanh.\nANH TIỀU PHU\n    (lẩm bẩm)\nLại một ngày nữa... Không biết hôm nay có kiếm đủ củi không.\nAnh siết chặt cán rìu, tiếp tục bước đi. Tiếng bước chân anh vang vọng trong khu rừng vắng vẻ.\nMột con sóc nhỏ nhảy thoăn thoắt từ cành cây này sang cành cây khác, nhìn anh tò mò. Anh Tiều Phu khẽ mỉm cười.\nANH TIỀU PHU\n    (nói với con sóc)\nChào bạn nhỏ. Hôm nay ta lại đến làm phiền khu rừng của các ngươi rồi.\nCon sóc nghiêng đầu, rồi vụt biến mất vào những tán cây xanh. Anh Tiều Phu lắc đầu, tiếp tục đi sâu vào rừng.\nAnh dừng lại trước một gốc cây lớn, thân cây xù xì, đầy rêu phong. Anh đặt rìu xuống đất, xoa xoa đôi tay.\nANH TIỀU PHU\n    (tự nhủ)\nCây này được đấy. Chắc sẽ được nhiều củi.\nAnh nhặt chiếc rìu lên, giơ cao. Ánh mắt anh ánh lên một tia quyết tâm.\nTiếng rìu chém vào thân cây vang vọng cả khu rừng. Những mảnh gỗ vụn bắn tung tóe. Mồ hôi túa ra trên trán anh.\nANH TIỀU PHU\n    (vừa chém vừa thở)\nCố lên... Cố lên... Phải kiếm đủ củi...\nAnh vung rìu liên tục, không ngừng nghỉ. Thân cây dần dần bị xẻ làm đôi. Anh Tiều Phu dừng lại, thở dốc.\nAnh nhìn thành quả của mình, một đống củi lớn nằm ngổn ngang trên mặt đất. Anh mỉm cười, một nụ cười mệt mỏi nhưng mãn nguyện.\nANH TIỀU PHU\n    (thở phào)\nVậy là đủ cho hôm nay rồi.\nAnh bắt đầu bó củi lại, chuẩn bị mang về nhà. Ánh nắng mặt trời đã lên cao, chiếu sáng cả khu rừng.\n\nNỘI. NHÀ - TỐI\nCăn nhà tranh tối om, chỉ le lói ánh lửa bập bùng từ bếp lò. Mùi khói bếp hòa lẫn với mùi ẩm mốc của đất. Một chiếc bàn gỗ ọp ẹp đặt giữa nhà, trên bàn bày một bát cơm trắng và một ít rau dại luộc.\nANH TIỀU PHU\n    (mệt mỏi)\n    (Vừa bước vào, đặt bó củi xuống góc nhà)\nVề đến nhà rồi...\nAnh bước tới bếp lò, khều than cho lửa bùng lên. Ánh lửa hắt lên khuôn mặt gầy gò, lấm lem của anh. Anh nhìn bó củi vừa kiếm được, thở dài.\nANH TIỀU PHU\n    (lẩm bẩm)\nChỉ đủ sưởi ấm qua đêm.\nAnh lững thững bước tới bàn ăn, ngồi xuống chiếc ghế gỗ đã sờn cũ. Anh cầm bát cơm lên, gắp một ít rau dại, chậm rãi nhai.\nKhông gian tĩnh lặng đến mức có thể nghe thấy tiếng dế kêu ngoài vườn. Anh Tiều Phu ngước mắt nhìn ra ngoài cửa sổ, bóng đêm bao trùm.\nANH TIỀU PHU\n    (nói một mình)\nKhông biết đến bao giờ mới thoát khỏi cảnh này...\nAnh đặt bát cơm xuống, đứng dậy, đi tới một góc nhà. Anh mở một chiếc hòm gỗ nhỏ, bên trong chỉ có vài bộ quần áo cũ và một ít tiền xu lẻ.\nAnh cầm một đồng xu lên, nhìn nó xoay xoay giữa các ngón tay. Ánh mắt anh lộ vẻ lo lắng.\nANH TIỀU PHU\n    (thở dài)\nChẳng còn bao nhiêu nữa...\nAnh bỏ đồng xu vào lại hòm, đóng nắp lại. Anh quay trở lại bàn ăn, tiếp tục ăn bữa cơm đạm bạc.\nBên ngoài, gió bắt đầu thổi mạnh, tiếng lá cây xào xạc. Căn nhà tranh rung lên nhè nhẹ. Anh Tiều Phu ăn xong bát cơm, đặt bát xuống.\nANH TIỀU PHU\n    (nhìn ra ngoài cửa sổ)\nBão về rồi...\nAnh đứng dậy, đi tới cửa, đóng chặt lại. Anh quay trở lại bếp lò, cho thêm củi vào. Ánh lửa bùng lên mạnh mẽ hơn, xua tan đi phần nào bóng tối trong căn nhà.\nAnh ngồi xuống bên bếp lò, nhìn ngọn lửa nhảy múa. Khuôn mặt anh giãn ra một chút, có lẽ vì hơi ấm từ ngọn lửa, hoặc có lẽ vì anh đang suy nghĩ về một điều gì đó tốt đẹp hơn.\nANH TIỀU PHU\n    (nhỏ nhẹ)\nRồi mọi chuyện sẽ ổn thôi...\nÁnh mắt anh nhìn vào ngọn lửa, ánh lên một tia hy vọng mong manh.\n\nNGOẠI. RỪNG - SÁNG\nÁnh sáng yếu ớt xuyên qua những đám mây xám xịt. Cơn bão đêm qua để lại một khu rừng ướt át, lạnh lẽo. Cây cối ngả nghiêng, cành lá gãy đổ ngổn ngang.\nANH TIỀU PHU\n    (vẻ mặt u ám)\nBước ra khỏi căn nhà tranh. Anh khoác lên mình chiếc áo tơi đã rách vài chỗ.\nAnh nhìn những bó củi ướt sũng nằm bên hiên, thở dài.\nANH TIỀU PHU\n    (lẩm bẩm)\n    (nhìn lên trời)\nÔng trời thật biết trêu ngươi...\nAnh vác chiếc rìu lên vai, bước đi nặng nhọc. Chiếc rìu va vào vai anh, tạo ra tiếng động khô khốc.\nAnh bước vào rừng. Không khí ẩm ướt và lạnh lẽo bao trùm lấy anh. Anh rùng mình.\nAnh dừng lại trước một gốc cây lớn, bị sét đánh gãy làm đôi.\nANH TIỀU PHU\n    (chán nản)\nNgay cả cây cũng không sống nổi...\nAnh đặt rìu xuống đất. Anh ngồi phịch xuống gốc cây, hai tay ôm mặt.\nANH TIỀU PHU\n    (khàn giọng)\nMình phải làm gì đây...?\nMột lúc sau, anh ngẩng đầu lên. Ánh mắt anh vẫn đượm buồn, nhưng đã có thêm một chút kiên định.\nAnh đứng dậy, nhặt chiếc rìu lên. Anh nhìn vào lưỡi rìu mòn vẹt.\nANH TIỀU PHU\n    (quyết tâm)\nKhông thể bỏ cuộc...\nAnh tiến đến một cây nhỏ hơn, chưa bị ảnh hưởng bởi cơn bão. Anh giơ rìu lên.\nTiếng rìu chém vào thân cây vang lên yếu ớt. Những mảnh gỗ vụn bắn ra ít ỏi.\nANH TIỀU PHU\n    (thở dốc)\n    (vừa chém vừa lẩm bẩm)\nPhải cố gắng... Phải sống...\nAnh vung rìu chậm chạp, nặng nhọc. Mồ hôi túa ra trên trán anh, hòa lẫn với những giọt mưa còn sót lại trên lá cây.\nCây rung lên sau mỗi nhát rìu. Anh cắn răng, cố gắng hết sức.\nSau một hồi lâu, cây đổ xuống. Anh Tiều Phu thở hổn hển, dựa vào gốc cây.\nAnh nhìn đống củi nhỏ bé vừa kiếm được. Ánh mắt anh vẫn chưa hết vẻ chán nản.\nANH TIỀU PHU\n    (thì thầm)\nChẳng được bao nhiêu...\nAnh bắt đầu bó củi lại. Tay anh run rẩy vì mệt mỏi và đói khát.\nKhi anh đang cố gắng buộc chặt bó củi, một cơn gió mạnh thổi qua, cuốn bay chiếc mũ rách của anh.\nChiếc mũ lăn lông lốc trên mặt đất ướt át. Anh Tiều Phu nhìn theo, bất lực.\nANH TIỀU PHU\n    (với giọng tuyệt vọng)\nĐến cái mũ cũng bỏ ta mà đi...\nAnh cúi xuống, nhặt chiếc mũ lên. Anh ôm nó vào lòng, như ôm lấy một người bạn thân thiết.\nANH TIỀU PHU\n    (nước mắt lưng tròng)\nTa phải làm gì đây...?\nAnh Tiều Phu ngồi bệt xuống đất, ôm chiếc mũ rách nát. Khuôn mặt anh lộ rõ vẻ mệt mỏi, chán nản và tuyệt vọng.\n\n\nNGOẠI. BỜ SÔNG - TRƯA\nMặt trời lên cao hơn, nhưng những đám mây vẫn che khuất ánh nắng. Anh Tiều Phu ngồi bệt dưới gốc cây, ôm chiếc mũ rách nát vào lòng. Nước mắt anh chực trào ra.\nAnh đứng dậy, lau vội nước mắt. Anh nhìn về phía dòng sông lững lờ trôi.\nANH TIỀU PHU\n    (tự nhủ)\nPhải cố lên. Không thể gục ngã.\nAnh vác bó củi nhỏ lên vai, bước đi. Anh đi dọc theo bờ sông, tìm một chỗ bằng phẳng để tiếp tục đốn củi.\nAnh dừng lại ở một khoảng đất trống, gần một cây cổ thụ lớn. Anh đặt bó củi xuống, phủi tay.\nANH TIỀU PHU\n    (thở dài)\nChỗ này được đấy.\nAnh tiến đến cây cổ thụ, quan sát. Thân cây to lớn, xù xì, nhưng đã mục ruỗng nhiều chỗ.\nANH TIỀU PHU\n    (lẩm bẩm)\nCây này dễ đốn... Nhưng củi có tốt không?\nAnh nhặt chiếc rìu lên, giơ cao. Anh nhắm vào một cành cây lớn, vung rìu chém mạnh.\nCHOANG!\nLưỡi rìu gãy làm đôi, văng ra khỏi cán. Phần lưỡi kim loại bắn thẳng xuống sông, tạo thành một vệt nước nhỏ.\nAnh Tiều Phu đứng sững người, hai tay vẫn nắm chặt cán rìu. Anh nhìn xuống cán rìu gãy, rồi nhìn về phía dòng sông.\nANH TIỀU PHU\n    (kinh hãi)\nKhông...\nAnh ném cán rìu xuống đất. Anh chạy đến bờ sông, quỳ xuống. Anh nhìn theo dòng nước chảy xiết.\nANH TIỀU PHU\n    (tuyệt vọng)\nKhông thể nào...\nAnh đưa tay lên ôm mặt. Nước mắt anh trào ra, lăn dài trên gò má. Anh khóc nức nở.\nANH TIỀU PHU\n    (gào lên)\nTại sao... Tại sao lại như vậy...?\nAnh nhìn dòng sông, như thể nó là kẻ thù của mình. Anh nắm chặt tay thành nắm đấm, run rẩy.\nANH TIỀU PHU\n    (thù hằn)\nTrả lại cho ta... Trả lại rìu cho ta...!\nAnh đứng dậy, lảo đảo. Anh nhìn xung quanh, như tìm kiếm một phép màu. Nhưng chỉ có khu rừng ướt át, lạnh lẽo và dòng sông vô tình.\nAnh Tiều Phu gục xuống, ôm mặt khóc. Tiếng khóc của anh vang vọng trong khu rừng vắng vẻ.\n\n\nNGOẠI. BỜ SÔNG - CHIỀU\nAnh Tiều Phu vẫn gục bên bờ sông, vai run lên từng hồi. Tiếng khóc nghẹn ngào hòa lẫn vào tiếng gió rít qua những hàng cây. Bó củi nhỏ nằm chỏng chơ bên cạnh, vô dụng.\nBỗng, một bóng người đổ dài trên mặt đất trước mặt anh. Anh Tiều Phu ngẩng đầu, mắt đỏ hoe.\nMột ÔNG CỤ, tóc bạc phơ như cước, đứng đó. Khuôn mặt ông hiền từ, ánh mắt ấm áp như ánh mặt trời chiều. Ông chống một cây gậy trúc, dáng vẻ chậm rãi, khoan thai.\nANH TIỀU PHU\n    (ngạc nhiên, giọng lạc đi)\nÔng... ông là ai?\nÔng Cụ mỉm cười, nụ cười hiền hậu như một cơn gió nhẹ.\nÔNG CỤ\nMột người qua đường. Ta nghe thấy tiếng khóc của con, nên ghé lại xem sao. Có chuyện gì vậy, chàng trai?\nAnh Tiều Phu cúi gằm mặt, xấu hổ vì để người lạ thấy cảnh mình thảm hại như vậy.\nANH TIỀU PHU\n    (khẽ nói)\nKhông có gì đâu ông... Chỉ là...\nÔNG CỤ\n    (kiên nhẫn)\nChỉ là gì? Con cứ nói, biết đâu ta có thể giúp được.\nAnh Tiều Phu ngập ngừng, rồi quyết định kể lại mọi chuyện. Anh kể về cuộc sống nghèo khó, về cơn bão đêm qua, về lưỡi rìu bị gãy và rơi xuống sông. Giọng anh nghẹn lại khi nhắc đến chiếc rìu, công cụ kiếm sống duy nhất của mình.\nÔNG CỤ\n    (lắng nghe chăm chú)\nTa hiểu rồi. Con mất rìu, coi như mất đi tất cả.\nAnh Tiều Phu gật đầu, nước mắt lại trào ra.\nANH TIỀU PHU\n    (nức nở)\nĐúng vậy... Con không biết phải làm gì nữa...\nÔng Cụ thở dài, đưa tay vỗ nhẹ lên vai Anh Tiều Phu.\nÔNG CỤ\nĐừng buồn, chàng trai. Mọi chuyện rồi sẽ ổn thôi. Con có muốn ta giúp con tìm lại chiếc rìu không?\nAnh Tiều Phu ngẩng phắt lên, mắt mở to. Anh không tin vào tai mình.\nANH TIỀU PHU\n    (vội vàng)\nÔng... ông có thể giúp con sao? Nhưng... con sông này sâu lắm, lại chảy xiết nữa...\nÔNG CỤ\n    (mỉm cười)\nCon đừng lo. Ta có cách của ta. Chỉ cần con đồng ý, ta sẽ giúp con tìm lại chiếc rìu.\nAnh Tiều Phu nhìn Ông Cụ, ánh mắt đầy hy vọng. Anh không còn lựa chọn nào khác.\nANH TIỀU PHU\n    (quyết tâm)\nCon đồng ý! Xin ông giúp con!\nÔng Cụ gật đầu hài lòng. Ông chống gậy, tiến lại gần mép sông. Ông nhìn xuống dòng nước, vẻ mặt trầm ngâm.\nÔNG CỤ\nĐược rồi. Con hãy ngồi đây chờ ta. Ta sẽ lặn xuống tìm.\nÔng Cụ cởi bỏ chiếc áo dài, gấp gọn gàng đặt lên tảng đá. Ông xắn ống quần lên, để lộ đôi chân gầy guộc, đầy những vết chai sạn.\nANH TIỀU PHU\n    (lo lắng)\nÔng... ông cẩn thận nhé! Nước lạnh lắm đấy!\nÔng Cụ quay lại, mỉm cười trấn an Anh Tiều Phu.\nÔNG CỤ\nCon cứ yên tâm. Ta không sao đâu.\nRồi Ông Cụ từ từ bước xuống sông. Nước ngập đến đầu gối, đến bụng, rồi đến ngực. Ông hít một hơi thật sâu, nhắm mắt lại, rồi lặn xuống dòng nước lạnh giá.\nAnh Tiều Phu hồi hộp nhìn theo. Mặt sông gợn sóng lăn tăn, rồi trở lại phẳng lặng. Anh nín thở, chờ đợi.', '2026-03-16 13:15:01');

